WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[34566] = { title = "At Your Command", description = "Commander, the outpost is nearly fully operational.\n\nGazlowe provided us with two different blueprints to fill this final plot - an Arsenal or an Arcane Sanctum.\n\nEither one would provide us with the additional firepower we need to stop the Iron Horde's advance.\n\nThe plans are on the drafting table. It's your call.", objectives = "" }
WordHunterWoW_QuestEN[34569] = { title = "The Quarry Quandary", description = "Now that our arsenal is built we need a skilled smith to operate it.\n\nWe recently caught an Iron Horde deserter who claims he used to be one of the Blackrock's best iron workers.\n\nNormally I'd ignore the ravings of a captive, but the weapons we took out of his pack had the finest workmanship I've ever seen.\n\nCommander, I think we should see if he's as good as he claims.", objectives = "" }
WordHunterWoW_QuestEN[34571] = { title = "Out of Jovite", description = "Ared and I came this way because we needed a good supply of metal to build his designs and some of the best metal is the jovite that comes from the mine in Kuuro's Claim. In order to supply the artillery tower I'm going to need this metal.\n\nUnfortunately that place was recently overwhelmed by a pack of goren, so you're going to have to fight your way in to get the ore before they manage to devour it.\n\nNothing that should be too much of a problem for you.", objectives = "" }
WordHunterWoW_QuestEN[34572] = { title = "Obliterating Ogres", description = "With actual ogre mages present, the Highmaul have been increasing patrols and aggression.\n\nThinning their ranks will go a long way to deterring the Highmaul from making a comeback in Nagrand.\n\nHead up to my sister Mirana afterwards, she should have more news.", objectives = "" }
WordHunterWoW_QuestEN[34573] = { title = "Iridium Recovery", description = "Ared used to always teach me that the purity of the metal is key. If the metal isn't pure it will crack under stress and be of no use to anyone.\n\nFor the artillery tower to function I'll need to make metal as pure as my master would, and for that I need a strong flux.\n\nThe dust from crushed iridium geodes would work in a pinch, but we need to find some first. They tend to congregate underground, so check out the mine in Kuuro's Claim nearby.", objectives = "" }
WordHunterWoW_QuestEN[34575] = { title = "Step Three: Prophet!", description = "You have arrived in Shadowmoon Valley. It is time to speak with the prophet.", objectives = "" }
WordHunterWoW_QuestEN[34576] = { title = "Iridium Recovery", description = "My goods used to be for the very best, now the Iron Horde make copies out of poor metal and give them to everyone.\n\nI'm going to show them what a real smith can do in your arsenal, but first I'm going to need a powerful flux to make the metal as pure as it can get.\n\nThe dust from crushed iridium geodes would work in a pinch but we need to find some first. They tend to congregate underground, so check out the mine in Kuuro's Claim nearby.", objectives = "" }
WordHunterWoW_QuestEN[34577] = { title = "Out of Jovite", description = "Crafting good equipment requires the best metal and some of the best metal is the jovite that comes from the mine in Kuuro's Claim, just east of here. In order to supply the arsenal I'm going to need this metal.\n\nUnfortunately the place was recently overwhelmed by a pack of goren so you're going to have to fight your way in to get the ore before they manage to devour it.\n\nNothing that should be too much of a problem for you, sir.", objectives = "" }
WordHunterWoW_QuestEN[34578] = { title = "Going to the Gordunni", description = "We have a good supply of jovite now but there just isn't enough of the material in the mine to keep the artillery tower in stock for long. Down south of here there's a mountain that's just full of the stuff but there's one problem; Ogres!\n\nThe Gordunni live on top of that mountain and they have begun trading the jovite to the Iron Horde.\n\nWe need to go down there and secure the minerals for ourselves.\n\nI'll pack some supplies and meet you near their fortress down south.", objectives = "" }
WordHunterWoW_QuestEN[34579] = { title = "Gas Guzzlers", description = "Sir, to make the best equipment for your arsenal I need not only the best materials, but to use the best techniques.\n\nOver the years I've developed a method to greatly strengthen my metal, but it does require an exotic resource: goren gut gas!\n\nThe nearby mine at Kuuro's Claim just came down with an infestation of the things. Could you collect a few samples for the arsenal supplies? Just kill a few goren and give their bodies a good prod with this gas extractor.", objectives = "" }
WordHunterWoW_QuestEN[34582] = { title = "Finding a Foothold", description = "So, you are the one that has led my children home? I have been waiting for you.\n\nThe Iron Horde grows stronger every day.\n\nI have foreseen a great battle, but my visions are clouded. It's as if time is sitting on top of itself. \n\nOne thing is certain, your presence here is of great importance.", objectives = "" }
WordHunterWoW_QuestEN[34583] = { title = "For the Alliance!", description = "We wouldn't have survived Tanaan without your strength, {name}. Many draenei and Alliance alike owe you a great debt.\n\nBefore we departed for the Dark Portal, King Wrynn personally recommended that I place you in charge of our operations here in Draenor. After seeing you in action, I'm inclined to agree.\n\nThis is your garrison to found. Plant the banner and we'll begin construction immediately, commander.", objectives = "" }
WordHunterWoW_QuestEN[34584] = { title = "Looking for Lumber", description = "Some of the trees around here look small enough that the workers should be able to down them in no time.\n\nWe can leave the hard labor to Shelly's men, but if you'd be willing to mark the trees for them to start with, we should be able to get this operation rolling much faster.", objectives = "" }
WordHunterWoW_QuestEN[34585] = { title = "Quakefist", description = "I'm getting reports of a giant in the forest.\n\nA few of the Karabor peacekeepers have followed it to a cave. In all honesty I don't think any of our troops are willing to engage the beast.\n\nMaybe you could investigate? I'm sure the peacekeepers would appreciate the help.", objectives = "" }
WordHunterWoW_QuestEN[34586] = { title = "Establish Your Garrison", description = "I'm impressed with how quickly you have pulled this group together, commander.\n\nI think it's time we start putting up some walls and establishing a firm perimeter around our base.", objectives = "" }
WordHunterWoW_QuestEN[34587] = { title = "Build Your Barracks", description = "I must say, commander, this garrison has really come along.\n\nWe have enough materials, all we need now are the blueprints I drafted up and I can begin construction on your barracks.\n\nHmm... now where did I put those blueprints?", objectives = "" }
WordHunterWoW_QuestEN[34592] = { title = "A Gronnling Problem", description = "It's gonna be quite a task to build you a fortress if there's gronnlings rampaging around.\n\nI don't think anyone else here can handle taking those big beasts out, so you might need to take care of it yourself.", objectives = "" }
WordHunterWoW_QuestEN[34593] = { title = "Obtaining Ogre Offensive Orders", description = "My sister, Mirana, is scouting the upper bluff while I've checked out the lower area. There are two particular ogre mages that do a lot of bossing around in the lower area.\n\nThey seem to have some orders or scrolls on them that would help us figure out what's really going on.\n\nCollect that information and meet with my sister on the long stairway up there.", objectives = "" }
WordHunterWoW_QuestEN[34596] = { title = "Reglakk's Research", description = "These ogres have been using ancient Titan artifacts to empower a small cadre of specialized units called the Breakers. This Magister Reglakk is here studying ways to improve the process.\n\nLet's put a stop to whatever rituals he has going up on the bluff.", objectives = "" }
WordHunterWoW_QuestEN[34597] = { title = "Removing the Paper Trail", description = "This box is filled with writings and diagrams that oddly resemble research into the nullification of magic.\n\nIt would be best to ruin these efforts by destroying any research found.", objectives = "" }
WordHunterWoW_QuestEN[34598] = { title = "The Missing Caravan", description = "I've got a problem and you look like you're just the {race} for the job!\n\nA trade shipment was supposed to arrive yesterday, but it's nowhere to be found. I'm running low on merchandise here and I need somebody to go find out what happened!\n\nIf I were to guess, I'd say the saberon are probably involved. Those brutes have been a pain in our side ever since we got here!\n\nSearch for the wagon on the road near Sabermaw and hurry! Time is money!", objectives = "" }
WordHunterWoW_QuestEN[34609] = { title = "Creating the Ink", description = "We need a way to create an artificial nexus at your tower.\n\nI know where we can get the conduit to do that, but it's well-guarded. We need to keep our cool and do this the right way.\n\nI have a plan - a scroll of mass teleportation.\n\nThe fungal giants and shamblers down below are covered with pustules full of an oily substance. We can use the oil to craft a makeshift ink substitute for the scroll.", objectives = "" }
WordHunterWoW_QuestEN[34612] = { title = "Forming the Scroll", description = "We'll need arcane parchment to make the scroll.\n\nThe arcane energy everywhere at this nexus froze the ancients in place and settled in their bark.\n\nIf we take pieces from the few that haven't been destroyed by the fungal creatures, I can mold them into parchment.", objectives = "" }
WordHunterWoW_QuestEN[34616] = { title = "Ravenous Ravens", description = "Do you see that? There is a gigantic raven just past the tree line.\n\nI'm not getting anywhere near that. In fact, I'm not sure any of the men are sufficiently equipped to deal with a threat like that. \n\nDo you want to handle this one yourself, commander?\n\nOnce those ravens are gone we can start sending more troops into the woods. So we will be killing two birds with one stone... or should I say kill five birds with...\n\n<Confused by his own analogy, Baros scratches his head.>\n\nYou get the point.", objectives = "" }
WordHunterWoW_QuestEN[34619] = { title = "Gathering the Spark", description = "We need arcane energy to complete our scroll. It needs that to coalesce the scroll together.\n\nI have an artifact that can capture energy vortexes in the caldera below, so let's get moving.", objectives = "" }
WordHunterWoW_QuestEN[34624] = { title = "Gas Guzzlers", description = "To complete my master's designs and to stock up the artillery tower we need to use an exotic resource, namely goren gut gas.\n\nThe nearby mine at Kuuro's Claim just came down with an infestation of the things. Could you collect a few samples for me? The stuff is concentrated, so only a few are needed. Just kill one and give its body a good prod with this gas extractor.", objectives = "" }
WordHunterWoW_QuestEN[34631] = { title = "An Audience With The Archmage", description = "I'm pleased to report that your Arcane Sanctum is up and running, commander!\n\nEverything is exactly as the blueprint says... except for this note Baros scrawled on the bottom. \"Don't forget to connect the sanctum to the ley line network!\"\n\nCommander, I'm a foreman, not a mage. I... have absolutely no idea how to do that.\n\nWe've found Archmage Khadgar and some other Kirin Tor not far from here. To the east, near the mountains. Perhaps we should ask them for a hand?", objectives = "" }
WordHunterWoW_QuestEN[34632] = { title = "An Audience With The Archmage", description = "Your Arcane Sanctum is coming along nicely, commander.\n\nEverything's built to spec... except for one detail Gazlowe scrawled in at the bottom of the blueprint. \"Don't forget to connect the sanctum to the ley line network!\"\n\nI, uh... I have no idea how to do that.\n\nI'm sorry commander, but magic just isn't my thing. We did spot Archmage Khadgar and some Kirin Tor not far from here. To the east, up near the mountains.\n\nMaybe we should ask them for help?", objectives = "" }
WordHunterWoW_QuestEN[34634] = { title = "Creating the Ink", description = "We're going to need a way to create an artificial nexus at your tower.\n\nI know where we can get what we need, but it's heavily protected. We don't have the firepower to just waltz in the front door.\n\nI have a plan - a scroll of mass teleportation.\n\nThe fungal giants and spore creatures down below are covered in pustules filled with an oily substance. If we gather enough of the oil I can craft a makeshift ink substitute for the scroll.", objectives = "" }
WordHunterWoW_QuestEN[34635] = { title = "Forming the Scroll", description = "For this plan to work, we'll need infused parchment.\n\nThe latent arcane energy at this nexus quickly froze the ancients in place and settled in their bark.\n\nIf we rip off strips from the few that haven't been destroyed by the fungal creatures, I can form them into parchment.", objectives = "" }
WordHunterWoW_QuestEN[34636] = { title = "Gathering the Spark", description = "We need to get our hands on arcane energy to complete our scroll. It needs that fiery kick.\n\nI have a device capable of capturing energy in the space below, so let's get moving. The infused creatures shouldn't be an issue for the two of us.", objectives = "" }
WordHunterWoW_QuestEN[34646] = { title = "Qiana Moonshadow", description = "If we are to win this war we are going to need more than foot soldiers. We need champions.\n\nQiana Moonshadow's performance in Tanaan and Eventide Landing was quite impressive.\n\nPerhaps you should speak with her about taking on a greater role in the battle against the Iron Horde.", objectives = "" }
WordHunterWoW_QuestEN[34653] = { title = "Arakkoa Exodus", description = "I assume you're familiar with the arakkoa, commander? Great, flying birdfolk. Extremely territorial.\n\nSome, however, have withered wings - a disease, maybe. They seem to be outcast from arakkoa society. You find them now and then, squatting in forgotten ruins or peddling trinkets on the roadside.\n\nIt seems the Iron Horde has incited the arakkoa by moving into their lands, and the outcasts are fleeing in droves.\n\nWe should make contact with these outcasts - they could have valuable information.", objectives = "" }
WordHunterWoW_QuestEN[34655] = { title = "The Shadows of Skettis", description = "My people flee our homeland in droves. I sell trinkets to ease the journey.\n\nBut I see that you are not interested in trinkets... No, what you seek are answers.\n\nSkettis lies just ahead. Once a great city built by Terokk as a refuge for the unwanted. Now a ruined slum.\n\nAn old storyteller lives there - a scrollkeeper named Reshad. Find him and speak these words: \"Shadows gather.\" He will know you are a friend.\n\nNow go. Your presence is bad for business.", objectives = "" }
WordHunterWoW_QuestEN[34656] = { title = "Hidden in Plain Sight", description = "<Reshad begins hastily stuffing scrolls into his robes.>\n\nI thought I would have more time to prepare! There are powerful relics hidden out there in Skettis - if I leave without them, I may as well have died.\n\nThe first is a pair of wingblades being held by an effigy near the front gate. You likely walked right past them on your way in.\n\nAnother effigy on the east side of the ruins bears a white mask over its face.\n\nBring those relics to me, and their secrets shall be yours.", objectives = "" }
WordHunterWoW_QuestEN[34657] = { title = "Adherents of the Sun God", description = "The arakkoa from Skyreach are all ruled by the Adherents of Rukhmar. They revile those of us who bear the Curse of Sethe, and decree that we must be purged in the name of their sun god.\n\nSoon their gaze will turn to lands beyond Arak.\n\nChallenge their warriors. Buy me time to prepare my escape, and help me set into motion their downfall.", objectives = "" }
WordHunterWoW_QuestEN[34658] = { title = "Orders From On High", description = "The Adherents of Rukhmar are the ruling body atop the spires. Their influence is absolute. Their proclamations taken as the will of Rukhmar Herself.\n\nThe herald leading this purge is surely carrying out such orders - likely no more than a list of names and places they plan to erase.\n\nThat list would prove invaluable in the days to come. Acquire it for me, and shut that herald up!", objectives = "" }
WordHunterWoW_QuestEN[34659] = { title = "The Crone", description = "Do you remember our greeting, {name}?\n\n\"Shadows gather when the raven swallows the day.\"\n\nIt is more than an old verse - it is a call to action. Followers of the old ways are gathering, and I must join them. You are needed, too, I should think\n\nFollow this road down to Crow's Crook. There you will find the home of an old crone. Greet her as you greeted me, and she will guide the way.\n\nYou will not see me, but I will be close behind.", objectives = "" }
WordHunterWoW_QuestEN[34662] = { title = "Ring of Trials: Crushmaul", description = "So you want to fight in the Ring of Trials do you? It's your funeral, bub!\n\nYour first fight is against an exceptionally large and angry ogre named Crushmaul. That's not all though, you'll have to take out his armored boar companion too; Crushmaul never goes into the ring without him!\n\nI hope your affairs are in order, because the last gladiator that fought Crushmaul went home in a body bag...\n\nI'm counting on you! Get your ass inside the arena and speak with my associate Guzrug to start the fight!", objectives = "" }
WordHunterWoW_QuestEN[34663] = { title = "Ring of Trials: Raketalon", description = "You may have defeated Crushmaul, but the party's over now...you've got another fight!\n\nThe Highmaul take gladiatin' seriously; so when they built the Ring of Trials, they searched far and wide for the most brutal creatures they could find!\n\nYou're up against a dread raven the ogres are calling Raketalon! I'm telling you, {name}, something about that bird just ain't right...I think it truly enjoys the act of killing!\n\nRaketalon toyed with the last gladiator for hours before eating him.\n\nTry not to die!", objectives = "" }
WordHunterWoW_QuestEN[34664] = { title = "Ring of Trials: Hol'yelaa", description = "You won your first two fights, but it's only going to get tougher from here!\n\nYour next fight is against Hol'yelaa, a former rangari who is as crazy as they come.\n\nNo, really... Hol'yelaa is bonkers!\n\nYears ago, while on a scouting mission, he single handedly saved his entire rangari unit from a pack of Garn. But something inside of him snapped....\n\nIt wasn't long before Hol'yelaa went completely marbles and turned on his own unit!\n\nAlright, the pep talk is over! Get in there and kick some ass!", objectives = "" }
WordHunterWoW_QuestEN[34665] = { title = "Ring of Trials: Captain Boomspark", description = "You've been making a name for yourself in the arena, {name}!\n\nDon't get too excited though...fame has its consequences! You've been challenged by an up-and-coming gladiator who is looking to make a name for himself, sound familiar?\n\nYour next fight is against Captain Boomspark, a mercenary who came here to fight for the Iron Horde.\n\nThe Iron Horde ain't exactly throwing piles of gold around, so now he's here!\n\nHe's got a shredder, so watch out for the blades... and the fire too... especially the fire!", objectives = "" }
WordHunterWoW_QuestEN[34666] = { title = "Ring of Trials: Roakk the Zealot", description = "The final match is at hand, {name}! You've decimated all of the best challengers! There's nowhere to go from here but the very top...the reigning champion of the Ring of Trials!\n\nThe current champ is an arakkoa named Roakk the Zealot. Roakk is a lunatic! He says he's on some divine crusade for the sun or something.\n\nCrazy or not, he's one of the most dangerous fighters I've ever seen and has even fought in the Highmaul Coliseum!\n\nI'm not going to lie, you're probably going to die in there...good luck!", objectives = "" }
WordHunterWoW_QuestEN[34672] = { title = "The Rise of Aku'mai", description = "We barely escaped the Twilight's Hammer sacrificial altar, but there are others who need help deeper within these caves. If these cultists complete their blood ritual, they will unleash Aku'mai the Devourer onto the world. You cannot let this happen.", objectives = "" }
WordHunterWoW_QuestEN[34673] = { title = "The Rise of Aku'mai", description = "We barely escaped de Twilight's Hammer sacrificial altar, but others be needin' help deeper in. If de blood ritual be complete, they be unleashin' Aku'mai da Devourer. Don let this be happenin', mon.", objectives = "" }
WordHunterWoW_QuestEN[34674] = { title = "Taking the Fight to Nagrand", description = "**Eyes Only -- Commander {name}**\n\nWith the fall of the rangari base at Telaar, Vindicator Yrel, recommended we establish a new foothold in Nagrand.\n\nI've taken the liberty of dispatching some of our men and supplies. Rangari D'kaan's already reporting that a new outpost is nearly complete. He has indicated that they are ready to receive you.\n\nA gryphon is waiting to catch you up with the latest caravan shipment whenever you're ready, sir.\n\n-- Bodrick Grey, SI:7", objectives = "" }
WordHunterWoW_QuestEN[34675] = { title = "The Might of the Warsong", description = "<The officer is in a great deal of pain. It's clear that he's not long for this world.>\n\nThe Warsong. Surprise attack.\n\nHeaded... west.\n\n<He takes a moment, before continuing.>\n\nThey took the... blueprints....\n\n<These are his last words.>", objectives = "" }
WordHunterWoW_QuestEN[34676] = { title = "The Critical Path", description = "The auburn forests of Talador sit at a critical crossroads of this continent, commander. The Iron Horde's fleet is already en route from Gorgrond to Shattrath on the west coast.\n\nTalador will fall if we don't reinforce them. I took the liberty of dispatching Foreman Eksos, who has already begun construction on an outpost for your forces not far from the Iron Horde landing point. He awaits your orders sir.", objectives = "" }
WordHunterWoW_QuestEN[34678] = { title = "Up and Running", description = "The Warsong struck us hard. We lost Telaar, but we have a rare opportunity to strike at the heart of the Warsong.\n\nWe need your wisdom and leadership to pull it off, {name}.\n\nFirst though, we're going to get our survivors out of Telaar. My rangari are ready to strike. We just need to get you to them.\n\nThaelin has a copter that can get you to them. Unfortunately, his hands are full just trying to keep the infernal thing running.\n\nHelp him get it up and running?", objectives = "" }
WordHunterWoW_QuestEN[34681] = { title = "It's a Matter of Strategy", description = "Da Iron Horde have proved themselves worthy foes.\n\nThey managed to get their fleet movin' to Talador from Gorgrond without my spies seein' a thing. Talador be a crossroads for the whole continent. We can't let them have it.\n\nDon't worry boss, we got a plan. Foreman Grobash be settin' up an outpost for our forces as we speak. They be ready for you when you arrive, commander.", objectives = "" }
WordHunterWoW_QuestEN[34682] = { title = "Operation: Surprise Party", description = "There weren't many survivors of the Warsong attack. The few remaining rangari have gone up to one of the bluffs overlooking Telaar.\n\nThe rangari are waiting for you. They're planning a surprise counter-attack.\n\nMy copter's taken a beating. The auto-pilot's set to take you up there. I think she's got one last trip in her.\n\nMaybe.", objectives = "" }
WordHunterWoW_QuestEN[34683] = { title = "One Step Ahead", description = "Boss, Durotan set off with Draka and Gazlowe to track da Iron Horde's movements along da coast.\n\nDey waitin' for ya on the cliffs to da northwest.", objectives = "" }
WordHunterWoW_QuestEN[34685] = { title = "As the Smoke Rises", description = "Aruuna burns.\n\nThe arakkoa swooped down from their spires and are turning everything to ash. Draenei, talbuk, even orc; they care not for allegiances. They merely want to watch the world burn.\n\nI barely escaped with my life, but my best friend, Barum, stayed behind to find his daughter. The others all say you are a great champion. Please, I beg of you, go to Aruuna and find them.", objectives = "" }
WordHunterWoW_QuestEN[34691] = { title = "Just the Beginning", description = "I forgive Orgrim. He acted as well all must - we do what our hearts tell us is right.\n\nWe should return to your outpost and discuss our next course of action. There is nothing left for us here.\n\nI will ask the human to open a portal for us. We shall speak again there.", objectives = "" }
WordHunterWoW_QuestEN[34692] = { title = "Delegating on Draenor", description = "There is more work to do on Draenor than we can possibly handle by ourselves. We need to start delegating.\n\nA group of night elves need a champion at Starfall Outpost.\n\nQiana is a perfect fit for this mission.", objectives = "" }
WordHunterWoW_QuestEN[34696] = { title = "The Lady of Light", description = "{name}, yes? You are the one in charge here? I am Knight-Lord Dranarus, at your service.\n\nLady Liadrin has responded to a suspected demon presence near Auchindoun, southwest of here. She has asked specifically for your assistance in ensuring Auchindoun does not fall into Gul'dan's hands.\n\nIf you could set forth at your nearest convenience, I am sure the Lady would be most grateful.", objectives = "" }
WordHunterWoW_QuestEN[34697] = { title = "A Rediscovered Legend", description = "If your troops are going to learn to fight people you better get people to fight! And they better be good.\n\nEver hear of Kash'drakor?\n\nHe's a big famous Frostwolf orc warrior type that tried to kill us Skulls. He would have won too, if the ogres hadn't snatched him.\n\nTo the north is the Stonemaul Arena where they took him and a bunch of other big bad mean fighter gladiators.\n\nIf you can find a way to free them, they could be the best trainers you could hope for.", objectives = "" }
WordHunterWoW_QuestEN[34698] = { title = "Slave Hunters", description = "Anytime a gladiator escapes Stonemaul, they send their hardened slave hunters after us.\n\nI consider myself a capable warrior, years of surviving in an arena have taught me that.\n\nBut these slave hunters keep pendants magically tethered to the slaves. With these pendants they can track us down anywhere we go, and kill us in our sleep or when our guard is down.\n\nI have no right to ask this, but can you enter Stonemaul and retrieve these pendants?", objectives = "" }
WordHunterWoW_QuestEN[34699] = { title = "Getting Gladiators", description = "When we fled Stonemaul, we had to leave others behind.\n\nIf we try to rescue them and are recognized, the ogres will know our purpose, and the first thing they will do is kill our friends.\n\nThe ogres do not know you, which might give you a fighting chance.\n\nEnter Stonemaul, find the other gladiators, and release them from their bonds. Do this and you will have our loyalty.", objectives = "" }
WordHunterWoW_QuestEN[34700] = { title = "Nazgrel", description = "Escaping Stonemaul was the easy part. The ogre filth that rule the pits still have my son.\n\nFor a while they used him as leverage to ensure I would fight in their arenas. But now that I have escaped they will try to train him to replace me.\n\nPlease, rescue my son. If they see me they will kill him instantly.", objectives = "" }
WordHunterWoW_QuestEN[34701] = { title = "Speaker for the Dead", description = "Oh, praise the Light, you're here! Exarch Maladaar asked for me to find you.\n\nWe need your help. Auchindoun is under attack by demons!\n\nGo to the Burning Front to the southwest as soon as possible! You're one of the few people he trusts to help lead the defense.", objectives = "" }
WordHunterWoW_QuestEN[34702] = { title = "Krav'ogra", description = "Stonemaul has chieftain, and it has slavemaster. Today, we kill both.\n\nFirst, Slavemaster Ok'mok. Me fight in arenas since me your size. Me know cruelty. Slavemaster Ok'mok is cruelty.\n\nWant to be true gladiator? Go to Stonemaul Arena, bang challenge gong in center of arena, and face beasts of slavemaster.\n\nMaybe you make Ok'mok so mad he jump down himself to kill you. If he do, kill him instead.", objectives = "" }
WordHunterWoW_QuestEN[34703] = { title = "The Axe of Kor'gall", description = "Time for vengeance! We are going to kill Kor'gall and you are going to take his axe.\n\nShatter this feeble barrier, follow the bridge beyond until you reach the chieftain's throne.\n\nYou freed us, so the honor of first blood is yours. Strike the first blow and we will join you in the cutting.", objectives = "" }
WordHunterWoW_QuestEN[34704] = { title = "A Rediscovered Legend", description = "This Sparring Arena is a good start, but we will need trainers to help mold your forces into worthy fighters.\n\nThere has been a reported spotting of a draenei to the west who matches the description of Akaani.\n\nThis is interesting, as we all believed her dead. She was one of the finest warriors the draenei have ever fielded and a master of nearly any weapon forged or found.\n\nCommander, you could not ask for a more skilled trainer. I advise seeking her out, if it is really her...", objectives = "" }
WordHunterWoW_QuestEN[34706] = { title = "Come Together", description = "Your work is done here, {name}. I will stay here for now and help clean up any remaining demons.\n\nYou should return to your outpost and let Dranarus know of our success. He can relay that information to Azeroth.", objectives = "" }
WordHunterWoW_QuestEN[34707] = { title = "Come Together", description = "Gul'dan and his cronies would do well to remember this day. We Auchenai are not to be trifled with.\n\nYou should inform Vindicator Icia in your outpost of our success. She can reach out to the scattered refugees and their families.", objectives = "" }
WordHunterWoW_QuestEN[34709] = { title = "Every Bit Counts", description = "The Jorune Mine, west of here, needs your help!\n\nMy good friend Ageilaa sent me to look for help. Exarch Maladaar sent over what vindicators he could spare, but it isn't enough!\n\nWill you go to the mine and help us? We need the crystals from the mine to create more defenses like the crystals you see on the Burning Front.", objectives = "" }
WordHunterWoW_QuestEN[34710] = { title = "Every Bit Counts", description = "Manduil Skycaller was sent on a sensitive mission to Jorune Mine, but he hasn't returned for hours.\n\nI suspect he requires assistance. I will let him brief you on the situation when you find him, but he is likely deep within the mine.\n\nYou should report to Ageilaa, a local draenei miner who has agreed to cooperate with us in exchange for helping her regain control of the mine.", objectives = "" }
WordHunterWoW_QuestEN[34711] = { title = "Due Cause to Celebrate", description = "Shall we return to your outpost? It would be a much better - and safer - place to celebrate.\n\nI'll teleport us there.", objectives = "" }
WordHunterWoW_QuestEN[34712] = { title = "Due Cause to Celebrate", description = "This isn't exactly my idea of the best place to talk.\n\nShall we return to your outpost? It will be a much better place to celebrate.\n\nI'll teleport us there.", objectives = "" }
WordHunterWoW_QuestEN[34716] = { title = "Mo'mor Might Know", description = "We know the Warsong packleader that attacked the caravan is in Telaar. She has the blueprints.\n\nWe don't know where she is down there, but there's one who might.\n\nVindicator Mo'mor was last seen alive, but taken prisoner. If he's still alive, he might know where the blueprints are.", objectives = "" }
WordHunterWoW_QuestEN[34717] = { title = "Operation: Just Arrowhead", description = "It goes without saying that we'll help you kill any of the Warsong out in the open down there.\n\nYou just start the fight, and we'll end it with extreme prejudice.", objectives = "" }
WordHunterWoW_QuestEN[34718] = { title = "The Others", description = "There are yet a few survivors. I saw them pile onto Arbiter Khan during the fighting.\n\nMore importantly, I can hear little Isel's sobs. She's nearby. I hope her mother is still alive.\n\nYour dwarf friend, Hansel, came in to try to rescue us. He thought he could take the Warsong on his own. I'm afraid I don't know what happened to him.", objectives = "" }
WordHunterWoW_QuestEN[34719] = { title = "... and My Hammer", description = "When they captured me, the Warsong took my hammer. Will you help me to recover it?\n\nI ask only because it's a holy relic. It should be taken from these orc dogs for no other reason than to return it to Auchindoun.\n\nPerhaps then, a worthy vindicator of the Light will take it up to smite the enemies of the draenei.", objectives = "" }
WordHunterWoW_QuestEN[34720] = { title = "Operation: Just Arrowhead", description = "It goes without saying that the Warsong in Telaar need to be dealt with. Rangari Ogir and his forces on the overlook will help you kill any of the orcs that are out in the open.\n\nYou just start the fight, and they'll end it with extreme prejudice.", objectives = "" }
WordHunterWoW_QuestEN[34721] = { title = "Seek Out the Seer", description = "We've been watching you, {name}.\n\nSeer Malune, keeper of memories, has requested an audience with you, adventurer.\n\nShe has long foretold the coming of a great hero to destroy the lurking shadow. We believe you are that hero.\n\nCome to Duskfall Island, not far southeast of here, and fulfill your destiny.", objectives = "" }
WordHunterWoW_QuestEN[34729] = { title = "Blood Oath of Na'Shra", description = "You have done me a great service. This blade is as much yours as it is mine.\n\nI offer you this blood oath: I shall serve your cause and lend my knowledge of blades and mining to your forces.\n\nWill you accept it?", objectives = "" }
WordHunterWoW_QuestEN[34731] = { title = "Oath of Shadow Hunter Rala", description = "", objectives = "" }
WordHunterWoW_QuestEN[34732] = { title = "Mulverick's Offer of Service", description = "", objectives = "" }
WordHunterWoW_QuestEN[34733] = { title = "Services of Dagg", description = "", objectives = "" }
WordHunterWoW_QuestEN[34736] = { title = "We Be Needin' Supplies", description = "Commander, our forces are not prepared for frost fightin'. I took da liberty and sent some of our shadow hunters north to establish a supply base. \n\nYa might want to be headin' up dere and see what they be up to. Look for a hollow between the Crackling Plains and the Savage Crag.", objectives = "" }
WordHunterWoW_QuestEN[34737] = { title = "Masters of Shadow", description = "The bad orcs tried to catch me, but I snuck away. I'm good at hiding.\n\nAll of the bad orcs are bad, but I've remembered the names of the meanest ones, just in case anybody came to save me.\n\n<Luuka takes a deep breath.>\n\nUngra, Gurran, and... umm... oh! Ankova.\n\nWill you protect me from them?", objectives = "" }
WordHunterWoW_QuestEN[34739] = { title = "The Shadowmoon Clan", description = "We will protect the wounded prisoners and make sure Kargath doesn't get through the rubble. You go ahead and clear the cave, {name}.", objectives = "" }
WordHunterWoW_QuestEN[34740] = { title = "Yrel", description = "Forgive me if I'm a bit flustered - I've never killed anyone before.\n\nMy name is Yrel, and I am a student of Karabor.\n\nYou say you have an ARMY with you? The Light must truly be watching over me today.\n\nI will follow you, then. Lead the way, {name}.", objectives = "" }
WordHunterWoW_QuestEN[34741] = { title = "Keli'dan the Breaker", description = "One of Ner'zhul's lieutenants remains, up ahead. The exit to the cave isn't much farther past him.\n\nI will go back and tell Khadgar that the cave is clear. We will rendezvous once you've taken care of Keli'dan!", objectives = "" }
WordHunterWoW_QuestEN[34746] = { title = "Shields Down!", description = "Did you hear that? They got the shield up. There'll be no getting into Telaar now.\n\nYou must get that shield down. The only way to do it is to destroy the Arkonite crystal.\n\nDon't worry about me. You're going to kill two birds with one stone; Packleader Kargora is the one who stole your blueprints.", objectives = "" }
WordHunterWoW_QuestEN[34747] = { title = "The Honor of a Blademaster", description = "", objectives = "" }
WordHunterWoW_QuestEN[34751] = { title = "Clear!", description = "You gotta help me fix this robot. I'm friggin' hungry!\n\nI built the Pleasure-Bot 8000 to locate Draenor truffles, and what does it do? It swims to this stupid island and shorts its power fluctuator.\n\nI got it hooked up to these batteries, but it ain't enough juice to jump it.\n\nBe a doll and get me the zapper sacs from the electric eels in the lake, would ya? They oughta be enough.", objectives = "" }
WordHunterWoW_QuestEN[34756] = { title = "A Charming Deception", description = "Reshad is more than he appears; a mottled old crow with his beak in a book, certainly, but we need him.\n\nShadows gather beneath the lonely spire, in Veil Terokk. Reshad must make it there safely.\n\nAlong the path you'll find charms primed with illusion spells. You need only touch them to take on Reshad's image.\n\nAdherent assassins are on the prowl for an old outcast with scrolls on his back. They will fall upon you.\n\nOh, but won't they be surprised when the illusion fades?! Kee-hee-hee!", objectives = "" }
WordHunterWoW_QuestEN[34758] = { title = "Looking For Help", description = "We have an accessible fishing spot here, but no bait seems to work!  We need to find a local fisherman with some knowledge of the area to help us out.  Head southeast and see if you can find anyone on the shoreline.", objectives = "" }
WordHunterWoW_QuestEN[34761] = { title = "Clear!", description = "Oh, the gnomanity!\n\nThe Pleasure-Bot 8000 broke before it could bring me a single Draenor truffle. It swam here and shorted its power fluctuator.\n\nAGAIN!\n\nI have power going to it, but it isn't enough to override the fluctuator.\n\nCould you get me the sacs from the electric eels in the lake? I think that would be just the ticket!", objectives = "" }
WordHunterWoW_QuestEN[34765] = { title = "The Den of Skog", description = "So this gronn infestation ain't gonna solve itself. You're gonna have to show them who's boss, Horde style!\n\nWith this many gronnlings around there is bound to be a full grown, big mama of a gronn. Find him... it... her... or whatever, and take it out, and the rest of those gronnlings might lose interest in our little operation here.", objectives = "" }
WordHunterWoW_QuestEN[34766] = { title = "Logistical Nightmare", description = "Commander, I am afraid I have... troubling... news.\n\nThese saberon followed our encampment from Gorgrond, and have been stealing our supplies, ransacking our ledgers, and slaughtering our peons!\n\nI hate to ask of your time to deal with the matter, but all of our men are stationed guarding the camp from any further raids. We desperately need those supplies so we may enact your will!", objectives = "" }
WordHunterWoW_QuestEN[34769] = { title = "A Choice to Make", description = "We're just about ready to go here. All that's needed now is for you to make your choice.\n\nTake a look at the blueprints on the drafting table.\n\nAre we going to construct a corral or a tankworks?", objectives = "" }
WordHunterWoW_QuestEN[34770] = { title = "The Honor of a Blademaster", description = "", objectives = "" }
WordHunterWoW_QuestEN[34773] = { title = "Why Is The Brew Gone?", description = "Commander, we have a bit of a... uh... problem.\n\nThis group o' saberon followed us from Gorgrond, and they've been stealin' our footmen's swords an' slaughtering our peasants!\n\nI hate to ask fer your time, but all of yer men are guardin' the camp from any further raids. Plus...\n\n<Quartermaster O'Riley lowers her voice to a whisper.>\n\nThey took our beer!", objectives = "" }
WordHunterWoW_QuestEN[34774] = { title = "Blingtron 5000", description = "", objectives = "" }
WordHunterWoW_QuestEN[34775] = { title = "Mission Probable", description = "Despite his recent captures, Olin Umberhide seems to be a tauren of some skill in combat. He certainly has learned how to get an enemy's attention.\n\nI have a mission available that might prove ideal for his skill sets.\n\nWhen you are ready, simply issue the order via the command table in front of me and we will dispatch him immediately.", objectives = "" }
WordHunterWoW_QuestEN[34776] = { title = "Gatekeepers of Auchindoun", description = "I was taken captive by the Iron Horde when they raided our caravan en route to Auchindoun.\n\nI escaped, but these spirits won't let me through to join my fellow Sunsworn until someone defeats them in combat!\n\nPlease, will you help me defeat them?", objectives = "" }
WordHunterWoW_QuestEN[34777] = { title = "Gatekeepers of Auchindoun", description = "Auchindoun is under attack, stranger, and I intend to help defend it.\n\nThe only problem is the only armor I could find was my grandfather's old set, and it isn't nearly enough to defeat the spirits blocking the path toward Auchindoun.\n\nWould you defeat them and let me through the gate with you? I will find a way to repay you!", objectives = "" }
WordHunterWoW_QuestEN[34778] = { title = "Migrant Workers", description = "{name}, more recruits arrive at your garrison every hour. We will soon run out of food.\n\nI have made contact with Exarch Akama in hopes of securing rations from Elodor, the breadbasket of this valley. He has agreed, provided we supply labor for the harvest. Everyone wins.\n\nIf you agree with my plan, speak with Foreman Zipfizzle here in the courtyard - he has gathered together available laborers. Akama and I will escort them and meet you at Elodor, far to the east!", objectives = "" }
WordHunterWoW_QuestEN[34779] = { title = "Circle the Wagon", description = "One of our wagons fell behind, and disappeared somewhere in the woods to the northwest. Vindicator Maraad and several of your workers are stranded out there.\n\nFind them and bring them back!", objectives = "" }
WordHunterWoW_QuestEN[34780] = { title = "Invisible Ramparts", description = "Exarch Akama is too cautious, but we shouldn't ignore a threat from the Shadowmoon clan. It is good you are here!\n\nSince we arrived on Draenor I have dedicated myself to recreating the technology we left behind. This large structure here is a defense ward. It should counter a Shadowmoon advance - provided we power it up.\n\nI have prepared resonance crystals at my workshop to the south. Carry one crystal at a time to the three pylons that surround the ward, then activate the control panel nearby!", objectives = "" }
WordHunterWoW_QuestEN[34781] = { title = "Defenstrations", description = "No sooner does power rush to the crystal outside than you hear distant war cries and shouts of alarm. Elodor is being attacked!\n\nIf you want your laborers to come home in one piece, you'd best help with the defense of the town. Defeat the invasion and then return to the control console to reset the defenses.", objectives = "" }
WordHunterWoW_QuestEN[34782] = { title = "The Exarch Council", description = "Good work at the gates! The Shadowmoon orcs have been seeking prisoners for some reason. Their aggression helps our cause.\n\nCome with me. I would like to introduce you to the Exarch Council, \"The Hand of the Prophet.\" I have been trying to convince the Exarchs to support our cause and go on the offensive against the Iron Horde, but they are - as always - too cautious and slow to act.\n\nCome with me, I will introduce you to Exarch Othaar up the hill. Perhaps meeting an Alliance hero can sway the council.", objectives = "" }
WordHunterWoW_QuestEN[34783] = { title = "Naielle, The Rangari", description = "I am calling the Exarch Council to order to hear your petition. None of us doubt that this \"Iron Horde\" is a threat, but few can agree on what we should do about it. It is up to you and Vindicator Maraad to gather the Exarchs together.\n\nExarch Naielle is the leader of the Rangari, the \"Eyes of the Prophet.\" They are our scouts who silently stalk the farthest corners of Draenor. Seek her out in the Rangari Enclave northwest of here.", objectives = "" }
WordHunterWoW_QuestEN[34784] = { title = "Fun with Fungus", description = "It is our mission as rangari to explore and understand this world. Around you is the Umberfen. Many draenei lost their lives when we first discovered this place. The volatile spores burst whenever anyone approaches.\n\nBut we watched... and we learned.\n\nAround the swamp you'll notice \"Shimmershrooms,\" distinguished by their orange glowcaps. Their dust will make you invisible to the volatile spores. Grab the spores - gently! - and bring them to me.\n\nWe will forge this savage world into a weapon.", objectives = "" }
WordHunterWoW_QuestEN[34785] = { title = "Hataaru, the Artificer", description = "I will also need you to call upon Exarch Hataaru. I understand you were helping him with our defenses at the gate.\n\nHataaru is our Chief Artificer - he understands our technology better than any other and has been working tirelessly to recreate the glory of the civilization we left behind.\n\nHe has moved to his workstation outside of the Elodor Dig, our crystal mines located just to the Southeast. Look for him at the mine entrance.", objectives = "" }
WordHunterWoW_QuestEN[34786] = { title = "Engorged Goren", description = "You must be the {class} that so impressed Exarch Hataaru. Can you help?\n\nThe Elodor Dig just behind me is overrun by strange stone creatures. These so-called goren actually devour minerals, metabolize them, and grow crystalline structures from their arms and back. Like most of the wildlife on this world, they completely baffle us.\n\nPlease slay as many as you can and gather their crystal scales for me. You'll be protecting our earthworkers and aiding our research at the same time.", objectives = "" }
WordHunterWoW_QuestEN[34787] = { title = "Exarch Maladaar", description = "The council is almost assembled: Othaar, myself, Hataaru and Naielle are ready. Only Exarch Maladaar remains. He has not been himself since he returned from his capture at the hands of the Iron Horde... but Vindicator Maraad was able to track him down.\n\nFind Maladaar at the Fey Landing, just south of the town center.", objectives = "" }
WordHunterWoW_QuestEN[34788] = { title = "Friend of the Exarchs", description = "Only three members remain of the Exarch Council, but we are all deeply indebted to you. The vote is unanimous: Your Alliance will have our full support on Draenor.\n\nWe are also going to place a draenei representative under your direct command. Three potential candidates are here in the courtyard. Speak to them and choose who you want - we will dispatch him or her immediately to your garrison!", objectives = "" }
WordHunterWoW_QuestEN[34789] = { title = "Speaker for the Dead", description = "This was a betrayal from within. There's no other explanation for it. None of the Exarchs trust each other now - especially me. But Othaar and Akama can damn their laws. We've got to rout out the traitor and the only way to do it is to speak to the corpse!\n\nJoin me just outside the Altar of Sha'tar atop the eastern cliffs. Soulbinder Nyami and I will perform an exorcism to save Hataaru's immortal soul... and maybe learn who did this to him.\n\nDo you trust me, {name}?", objectives = "" }
WordHunterWoW_QuestEN[34790] = { title = "The Sting", description = "The exarchs seem to trust you, {class}. Are you venturing into the Umbrafen?\n\nThe Sporebats in this area are usually docile, but something's got them all riled up. When they attack, their stingers wrap around exposed limbs. I've seen them tear through reinforced leather like it was paper. How do they work, I wonder?\n\nCould you bring me a pristine sporebat stinger? I'd love to study it.", objectives = "" }
WordHunterWoW_QuestEN[34791] = { title = "Warning the Exarchs", description = "You set the book ablaze, but not before noting its contents. The demonic tome was dedicated to enchanting weapons with fel energy. It looked as though the goal was to ensnare the victim's soul.\n\nThe Exarchs must be warned that traitors are among them! The Council should be meeting now just up the hill to the east.", objectives = "" }
WordHunterWoW_QuestEN[34792] = { title = "The Traitor's True Name", description = "We must give the traitor no place to hide. I have a focusing lens that will illuminate cloaked fel energy. If it were placed on a high point, it could act like a beacon, lighting up anyone in town who reeks of the fel taint.\n\nThere is a prayer circle atop the Exarch's Rise to the north that will serve our purpose. Plant the focusing lens, {name}. If you reveal anything, deal with it. Then meet me below.", objectives = "" }
WordHunterWoW_QuestEN[34794] = { title = "Taking the Fight to Nagrand", description = "Boss-mon, good to see ya.\n\nDurotan recommended dat we be gettin' a foothold in Nagrand, so I taken the liberty of dispatchin' some of da boys.\n\nThrall's already reportin' that the outside be nearly complete. He been askin' me to let ya know they be ready for ya.\n\nA windrider be waitin' to catch ya up with the latest caravan shipment whenever you be ready, sir.", objectives = "" }
WordHunterWoW_QuestEN[34795] = { title = "The Might of the Warsong", description = "<The officer is in a great deal of pain. It's clear that he's not long for this world.>\n\nThe Warsong. Surprise attack.\n\nHeaded into... the Burning Blade....\n\n<He takes a moment, before continuing.>\n\nThey took the... blueprints....\n\n<These are his last words.>", objectives = "" }
WordHunterWoW_QuestEN[34801] = { title = "A Pilgrimage Gone Awry", description = "I am a humble pilgrim, I swear. Please don't hurt me!\n\nMy sister and I were traveling to Auchindoun to pay our respects to my grandmother when we hit an overturned rock and lost control of our caravan. I managed to survive, but my sister...\n\n<Nadur cries.>\n\nPlease, you have to help me. I'm desperate. If you could bring me some prowler blood, snapdragon flowers, and a riverhopper eye, I can fashion a potion to bring her back. I just know it....", objectives = "" }
WordHunterWoW_QuestEN[34802] = { title = "A Pilgrimage Gone Awry", description = "My sister and I were traveling to Auchindoun to pay our respects to my grandmother when we hit an overturned rock and lost control of our caravan. I managed to survive, but my sister...\n\n<Nadur cries.>\n\nPlease, I need your help. If you could bring me some prowler blood, snapdragon flowers, and a riverhopper eye, I can fashion a potion to bring her back... I just know I can...", objectives = "" }
WordHunterWoW_QuestEN[34803] = { title = "Send Them Running", description = "Your scouts have located the saberon's alpha male just outside our gates!\n\nCommander, I believe that dispatching this target will send any of these remaining vermin running back to their caves.\n\nI do not wish to ask more of you, but you are the only one capable of this task, sir.", objectives = "" }
WordHunterWoW_QuestEN[34804] = { title = "Not In Your House", description = "Sir, we have located the saberon's alpha male just outside our gates!\n\nWe believe that slaying him will send any remaining saberon running with their tails between their legs, but the beast is positively massive!\n\nI do not wish to call upon you once more, but you are the only one capable of this task.", objectives = "" }
WordHunterWoW_QuestEN[34805] = { title = "Echo Hunters", description = "I am no sorcerer, but I've picked up a few spells in my time - enough for me to pass unseen by the naked eye.\n\nUnfortunately, the vampire bats in these woods don't use their eyes. They will hear my shuffling robes and Percy's incessant clucking a mile away.\n\nClear them away from the path, would you?", objectives = "" }
WordHunterWoW_QuestEN[34806] = { title = "Prune the Podlings", description = "The blood soaked body of Ryan is slumped up against the cave wall. Tiny teeth marks cover his body.\n\nThe podlings clearly are a threat to you and your garrison.\n\nIt's time to do a little pruning.", objectives = "" }
WordHunterWoW_QuestEN[34808] = { title = "More Lazy Peons", description = "We have a rare opportunity to strike at the heart of the Warsong. But, we need your wisdom and leadership.\n\nThe most important decision will be your choice between building a corral or a tankworks. This choice will setup our approach to the fight against the Warsong.\n\nThazz'ril will head up our building efforts. Will you give him a hand?\n\nIt looks like he's having trouble motivating his peons to work.", objectives = "" }
WordHunterWoW_QuestEN[34809] = { title = "A Lesson in Mineralogy", description = "<Gazmolf gestures at the large machine nearby.>\n\nI built this machine to break down elementium minerals into base elements. You see, it's not just what's buried within the ground that can be valuable; but also the ground itself!\n\nTake, for example, the earth elementals below us; inside every earth elemental is an earthen core, dense in precious metal!.\n\nThose elementals are going to make us rich! Collect several earthen cores, place them in the Gold-O-Matic 9000, and I'll give you a cut!", objectives = "" }
WordHunterWoW_QuestEN[34810] = { title = "Gazmolf Futzwangler and the Highmaul Crusade", description = "I'm here in Nagrand recruiting for the Steamwheedle Preservation Society. We're the archaeological branch of the Steamwheedle Cartel.\n\nWe're here to collect all of the artifacts, relics, antiquities and oddities that Nagrand has to offer! Currently, we're hiring surveyors, excavators, adventurers... you name it!\n\nIf you're interested in getting your hands dirty, talk to Gazmolf Futzwangler over at Stonecrag Gorge. He's the goblin in charge of this expedition!", objectives = "" }
WordHunterWoW_QuestEN[34811] = { title = "Good Help is Hard to Find", description = "The excavation team is on strike!\n\nForeman Thazwix and his cronies think they can squeeze the Steamwheedle Preservation Society for some extra dough by refusing to work.\n\nWhat I need is a scab, a strikebreaker; someone to put some pressure on them by doing the job they refuse to do!\n\nGo down into the gorge, dig up some antiquities for me, and I'll pay you what I would have payed those lazy numbskulls!", objectives = "" }
WordHunterWoW_QuestEN[34814] = { title = "Making Acquaintances", description = "It's nice to see someone else taking a vested interest in the arcane arts, you know. It's all too rare these days if you ask me!\n\nUnfortunately, I must meet Cordana to handle an important matter, but we're in luck! One of my good friends in the Kirin Tor has agreed to help you connect your arcane sanctum to the ley line network.\n\nHe's waiting at my tower. Let's leave immediately and introduce you to one another.", objectives = "" }
WordHunterWoW_QuestEN[34815] = { title = "Making Acquaintances", description = "It's nice to see someone else taking a vested interest in the arcane arts, you know. It's all too rare these days if you ask me.\n\nUnfortunately, I must meet Cordana to handle an important matter, but we're in luck! One of my good friends in the Kirin Tor has agreed to help you connect your arcane sanctum to the ley line network.\n\nShe's waiting at my tower. Let's leave immediately and introduce you to one another.", objectives = "" }
WordHunterWoW_QuestEN[34818] = { title = "They Call Him Lantresor of the Blade", description = "The garrison blueprints were taken to the Burning Blade village when the Warsong sacked your caravan. I can't construct this building without those plans.\n\nThere's been talk of a young blademaster who's been exiled from the clan for many years. They call him Lantresor of the Blade.\n\nOur scouts recently saw him return to Hallvalor to challenge the blademaster leadership. Instead, they clapped him in chains.\n\nMaybe he's still alive. Maybe he'll help you recover the blueprints?", objectives = "" }
WordHunterWoW_QuestEN[34819] = { title = "Fruitful Ventures", description = "Oh no! They must be vegetarians.\n\nWhat these elekk need is fruit and lots of it. There are cherries all over the place around here under the trees.\n\nYou wouldn't mind grabbing me some, would ya?", objectives = "" }
WordHunterWoW_QuestEN[34820] = { title = "Lost Lumberjacks", description = "Shelly and her crew haven't returned from Gloomshade Grove.\n\nIt's been days... I hope everything is okay.", objectives = "" }
WordHunterWoW_QuestEN[34822] = { title = "What We Need", description = "I heard you guys hijacked and wrecked a ship on your way out of Tanaan.\n\nIt's like my daddy always said: One man's wreck is another goblin's workshop.\n\nYou should head down to the coast west of the garrison and see if you can't find any materials we might salvage. Oh, and uh... should probably watch yourself. I hear there are ogre raiders in the area.", objectives = "" }
WordHunterWoW_QuestEN[34823] = { title = "The Ogron Live?", description = "Commander, our Frostwolf allies reportin' dat the Bladespire ogres have an outpost to our west led by an ogron.\n\nI heard tales of da ogron but never seen one. Dey be brutes, creatures from a time that was best left forgotten. Dey say most were slain during the forming of the original horde. What dey lack in wisdom they make up for in violence, force, and greed.\n\nI counsel dispatchin' dis creature as soon as possible.", objectives = "" }
WordHunterWoW_QuestEN[34824] = { title = "What We Got", description = "Every fortress needs three things.\n\nOne: peons! Find Skaggit and have him get our peons back to work.\n\nTwo: building materials. I had the peons set up a cache for you where they will store resources they create while you are away. You should check it out.\n\nAnd three: raw experienced muscle! Constructing buildings in a garrison can take some time but I think we can speed up your first building by hiring Skaggit's recently promoted Senior Peon II. Find him and tell him I sent ya.", objectives = "" }
WordHunterWoW_QuestEN[34826] = { title = "The Friend of My Enemy", description = "Hallvalor is the ancestral home of the Burning Blade clan. Since they're such fast friends, the Warsong have allowed the blademasters to remain in Nagrand.\n\nWe are fierce, but we won't win if the Burning Blade attack us. It would be wise to strike first.", objectives = "" }
WordHunterWoW_QuestEN[34827] = { title = "Last of the Talonpriests", description = "Talonpriests live among us in secret, guarding the rites of the Talon King's return.\n\nThe Adherent proclamation you acquired in Skettis revealed two of them living in the Shadowglade to the north. Orcs have moved into the region, and the Adherent's beam weapon left Veil Akraz a smoking crater.\n\nAs you can see, my people are beset by enemies on all sides.\n\nTalonpriest Ishaal survived and is in hiding. Drink this elixir near his hut to peer into the shadows and make contact with him.", objectives = "" }
WordHunterWoW_QuestEN[34828] = { title = "Ishaal's Orb", description = "The Adherents came for me, but I was already hiding. I watched from the shadows as they ransacked my hut.\n\nThen I watched the Shattered Hand orcs arrive and butcher them like dinner fowl. Seems everyone is after us these days.\n\nOne of those orc thugs made off with my scrying orb. I will be needing it back if I am to be of any use to Iskar.", objectives = "" }
WordHunterWoW_QuestEN[34829] = { title = "New Neighbors", description = "The Shattered Hand clan is made up of orcs who can call no other clan home. They are sadistic warriors who maim their bodies, perhaps in a show of solidarity or perhaps because they simply enjoy the pain.\n\nIt does not matter. What matters is that they are expanding their territory, butchering anyone in their path.\n\nThey must be dealt with.", objectives = "" }
WordHunterWoW_QuestEN[34830] = { title = "Behind the Veil", description = "Soon after the orcs swept in, Veil Akraz was laid to waste by a beam of light from Skyreach.\n\n<Ishaal's eyes glass over as he peers into his orb.>\n\nIt seems they missed their true target. Zellek is still there, hiding in the realm of shadow.\n\nAnd... someone else as well. The orc assassin who used my orb.\n\nTake this. Drink it in Veil Akraz and find Zellek.\n\nOh, and be careful. It's a little more potent than the last one. You'll see...", objectives = "" }
WordHunterWoW_QuestEN[34836] = { title = "Lunarblossom", description = "How I long to hold Kat'la.\n\nNo star or moon can compare to her beauty.\n\nAlas, I am but a simple boar farmer.\n\nIf only I could find time to sneak away from this pathetic excuse for a job and pick some lunarblossoms for Kat'la.\n\nI wouldn't dare confess my love to her without a gift.", objectives = "" }
WordHunterWoW_QuestEN[34837] = { title = "Going to the Gordunni", description = "We have a good supply of jovite in the arsenal now but there just isn't enough of the material in the mine to keep us in stock for long. Down south of here there's a mountain that's just full of the stuff but there's one problem; Ogres!\n\nThe Gordunni live on top of that mountain and they have begun trading the jovite to the Iron Horde.\n\nWe need to go down there and secure the minerals for ourselves.\n\nI'll pack some supplies and meet you near their fortress down south.", objectives = "" }
WordHunterWoW_QuestEN[34838] = { title = "Ikky's Egg", description = "<Miraculously, this single egg has eluded the ravagers.\n\nA small tag has been lovingly tied around the base of the egg. It reads \"Ikky.\">", objectives = "" }
WordHunterWoW_QuestEN[34840] = { title = "Dropping Bombs", description = "The Gordunni have only a single path to their fortress and it is well-defended from a large attack.\n\nThankfully they wont be expecting just the two of us to be attempting to break in.\n\nThis is a great opportunity to take out their defenses and get some target practice for our artillery gunners back at the arsenal.\n\nTake these smoke grenades and use it to call in an artillery strike on their catapults as we head up.", objectives = "" }
WordHunterWoW_QuestEN[34844] = { title = "We Require More Resources", description = "So what we got here is a good start, but you are looking for something that can support ARMIES!\n\nTruth is, we ain't building anything without the materials to build it, and our supplies from Azeroth are limited.\n\nI got some ideas on how to get you started but you are going to have to keep your eyes open for more materials when out in the field. Lots of useful stuff out there we can change into usable material.", objectives = "" }
WordHunterWoW_QuestEN[34846] = { title = "Fish Fight", description = "We have an accessible fishing spot here, but no bait seems to work!  We need to find a local fisherman with some knowledge of the area to help us out.  Think you are up to the task?", objectives = "" }
WordHunterWoW_QuestEN[34847] = { title = "Forbidden Love", description = "My son, Kral'za, is beyond stubborn. \n\nAfter we split from the Shadowmoon Clan he refused to let go of his relationship with a young Shadowmoon orc.\n\nI forbid him to see her anymore. He ran off earlier today and has not returned. \n\nI don't trust Dol'mak. Like the other Shadowmoon orcs she continues to dabble in the void.", objectives = "" }
WordHunterWoW_QuestEN[34849] = { title = "The Blade Itself", description = "When they clapped me in irons, the Burning Blade instructor, Luhk the Keen-Eyed, took my blade. He's an honorable orc, even if his training techniques are counter-productive.\n\nI want my blade back, {class}. Then, I'll break myself free.", objectives = "" }
WordHunterWoW_QuestEN[34850] = { title = "Not Without My Honor", description = "The blade is not the only important item a blademaster carries.\n\nOnce he has passed his final tests in the Masters' Caverns, the blademaster is given the honor of wearing the Burning Blade's banner.\n\nWhen my petition to reclaim my rightful place with the clan fell upon deaf and craven ears, I was stripped of that honor.\n\nNo doubt, my banner has been stored away somewhere in Hallvalor. They'll give it to some other aspiring blademaster if they don't burn it first.", objectives = "" }
WordHunterWoW_QuestEN[34855] = { title = "Punching Through", description = "To secure the fortress we need to kill Witch Lord Morkurk, but I don't think we should go straight after him.\n\nHis three lieutenants - Vorgorsh, Zulmork, and Cromaug - are all powerful mages, and all of them are fiercely loyal to Morkurk.\n\nI suspect that if we engage the Witch Lord that they will rush to his aid. Let's take them out so that cannot happen.", objectives = "" }
WordHunterWoW_QuestEN[34858] = { title = "Prized Repossessions", description = "The Gordunni were given copies of my blades as a gift from the Iron Horde. But what do they use them for? Toothpicks!\n\nSure the blades are low grade copies but it's still MY design and I can't stand to think of them in those ogre hands for a moment longer!\n\nSir, While we are in here can you do me a favor and get those blades out of their hands!", objectives = "" }
WordHunterWoW_QuestEN[34860] = { title = "Supply Recovery", description = "We seem to have arrived at just the right time!\n\nThe Gordunni have been enchanting armaments for the Iron Horde and it looks like they haven't picked up the latest shipment.\n\nWe could put that gear to far better use! Lets go hunt down their shipping containers. I brought some signal flares that we can use to call in an air pick-up when we've secured the shipment.", objectives = "" }
WordHunterWoW_QuestEN[34861] = { title = "We Need An Army", description = "So the new warchief decided to send you Warmaster Zog to handle local operations. Zog!\n\nI heard that guy was notorious for organizing the Alliance AND the Horde to face off against the silithid at the Gates of Ahn'Qiraj.\n\nHe was a general back then.\n\nAnyway, if you go let him know about the barracks being done I'm sure he'll have some thoughts on how to put it to good use.\n\nYou can find Zog up at the town hall.", objectives = "" }
WordHunterWoW_QuestEN[34866] = { title = "Meet Me in the Cavern", description = "It's time, {class}. Time for you to get your blueprints.\n\nTime for us to face the masters.", objectives = "" }
WordHunterWoW_QuestEN[34867] = { title = "The Secrets of Gorgrond", description = "Commander, I will leave my forces to secure this pass, but I will not sit idle while our enemy prepares for another attack.\n\nI want to take the fight to the heart of the Iron Horde at Blackrock, and to do that we are going to need to go where few orcs dare tread.\n\nGorgrond.\n\nIt is a savage place, filled with giants and monsters of every sort.\n\nWill you dare these wilds with me so that we might strike at the foundries of the Iron Horde?", objectives = "" }
WordHunterWoW_QuestEN[34868] = { title = "Challenge of the Masters", description = "The time has come to challenge the Burning Blade masters.\n\nGo to the back of the cavern. There you will find the challenge ring and the masters watching over it from above.\n\nPull the blade from the middle of the ring to issue your challenge. My clan values honor above all else and will respect your claim to trial by combat.\n\nAs reward, you will be allowed to walk away with your blueprints and your life. Or, you will be dead.", objectives = "" }
WordHunterWoW_QuestEN[34869] = { title = "Tastes Like Chicken", description = "You got a moment, bub? I've got an elekk-sized problem.\n\nSomeone, um, sold me... yeah, sold me these two, but they're sick. I've tried everything, but nothing I do makes any difference!\n\nI think they must be starving. I heard that elekk like raw windroc. Gross if you ask me.\n\nAnyway, while you're out doing your thing, you mind picking me up some bird meat?", objectives = "" }
WordHunterWoW_QuestEN[34870] = { title = "The Lord of the Gordunni", description = "Witch Lord Morkurk is the leader of the Gordunni. He's the one that set up the Iron Horde trade and, even worse, my former boss gave him one of my best maces!\n\nWe got to get my mace back! I mean... we need to kill him to secure the jovite for your arsenal!\n\nMorkurk is an accomplished mage so you better be prepared. Here, take the rocket pack and use it if you need to dodge an attack quickly or something.\n\nAlso, if you happen to find my mace I'd like to get it back.", objectives = "" }
WordHunterWoW_QuestEN[34874] = { title = "Next Steps", description = "You are positively on fire!\n\nWe have everything I need to create the scroll. Your arcane sanctum will be brimming with arcane energy in no time.\n\nI will teleport to Vol'jin's Pride to combine the reagents and marshal your forces. Meet me there when you can.", objectives = "" }
WordHunterWoW_QuestEN[34875] = { title = "Next Steps", description = "We did it! We have all of the reagents for the scroll. Your arcane sanctum will be the talk of Draenor before long.\n\nI'll go back to Fort Wrynn to finish it and gather your men. Meet me there.", objectives = "" }
WordHunterWoW_QuestEN[34876] = { title = "Loola's Lost Love", description = "Oh it was horrible.\n\nMy husband and I were fishing in the marsh, I fell asleep and when I woke up he had been turned into a toad!\n\nI'm sure it was one of those Shadowmoon orcs I hear so much about.\n\nHe jumped into the muddy waters before I could catch him.\n\nWill you help me find my lost love, {class}?", objectives = "" }
WordHunterWoW_QuestEN[34877] = { title = "Removing the Reinforcements", description = "My own investigations have uncovered a permanent arcane portal from here to Highmaul itself.\n\nIt is guarded but shouldn't be too hard to disrupt once you've gotten some breathing room.", objectives = "" }
WordHunterWoW_QuestEN[34878] = { title = "The Foot of the Fortress", description = "We've enkindled your forces and the scroll is ready.\n\nIt's time for phase two - stealing a nexus crystal from a heavily fortified ogre compound.\n\nWe'll save the scroll to bring in reinforcements in our confrontation with the Gordunni Witch Lord. Let's meet at the base of the Gordal Foothills and take what is more or less rightfully yours!", objectives = "" }
WordHunterWoW_QuestEN[34879] = { title = "Dropping In", description = "Witch Lord Morkurk is no fool.\n\nHe has catapults set up throughout the foothills leading into their compound.\n\nNo matter, I have a way to handle them.\n\nTake out the ogres guarding the siege weapons and mark them once they're clear. I'm readying a vortex spell that will handle things from there.\n\nWe'll meet just outside their gate afterwards.", objectives = "" }
WordHunterWoW_QuestEN[34881] = { title = "Earth, Wind and Fire...and Water", description = "The Elemental Plateau has become unstable, and so the cycle of rebirth must begin.\n\nIt is a natural part of our life cycle that impurities are accumulated in the elemental body over time.\n\nWhen enough contamination has taken place, an elemental will become unstable and in some cases volatile.\n\nA necessary part of rebirth is pure, living essence which can be found atop the Elemental Plateau, as well as in the body of an elemental spirit.\n\nReturn to me with the essence and we shall begin the rebirth.", objectives = "" }
WordHunterWoW_QuestEN[34882] = { title = "Blades in the Dark", description = "Those orcs got hold of Ishaal's orb, did they? That would explain the dangerous-looking fellow who crossed into this realm shortly before you.\n\nNot everyone handles the transition as... gracefully as you did. The oaf is still grappling with his own mind, stumbling about and muttering nonsense.\n\nSoon he will be drawn to the orb again, which would presumably lead him to Veil Terokk.\n\nBetter to take him out now while he's still befuddled.", objectives = "" }
WordHunterWoW_QuestEN[34883] = { title = "A Feast of Shadows", description = "Many arakkoa died in Veil Akraz. From the outside, all seems still. Empty.\n\nBut in this place between worlds, death never goes unnoticed.\n\nStray life essence seeps through from the other side; a feast for the beings who prowl here.\n\nSlay the shadow creatures here, and gather from their corpses the fine dust they produce. I will need much of it to perform the rites of the Talon King.", objectives = "" }
WordHunterWoW_QuestEN[34884] = { title = "The Kaliri Whisperer", description = "An important contact lives in the nearby Shadowglade. He is meek, but trains kaliri of monstrous size which are quite dangerous.\n\nHe once claimed they could knock a rylak out of the sky, but I'll believe that when I see it.\n\nSkizzik is holding a valuable treasure for me. Seek him out and get him back to Veil Terokk if you can. At the very least, recover the gavel I entrusted to him.", objectives = "" }
WordHunterWoW_QuestEN[34885] = { title = "Mother of Thorns", description = "<Beneath Skizzik's outstretched hand, letters are scrawled into the dirt:\n\nt h o r n\n\nm o t h e r\n\nRavagers brought in by the Shattered Hand have taken over the aviary and are breeding fast. If left alone, they could be swarming the entire area - including Veil Terokk - in a matter of days.>", objectives = "" }
WordHunterWoW_QuestEN[34886] = { title = "Baby Bird", description = "<Ikky cheeps again, then begins gnawing on his foot.\n\nLooking out across the nearby hillside, you spy tiny ravager grubs inching along the grass.>", objectives = "" }
WordHunterWoW_QuestEN[34887] = { title = "While We're in the Neighborhood", description = "Ah, the hubris of ogres.\n\nIt always backfires.\n\nMorkurk has been using enchanted bracelets to empower his minions with arcane strength.\n\nWe can disenchant these bracelets into reagents that will no doubt be useful to your arcane sanctum. What do you think about collecting some while we're here?", objectives = "" }
WordHunterWoW_QuestEN[34888] = { title = "Vicious Viziers", description = "We're after Witch Lord Morkurk, but we shouldn't charge straight at him.\n\nHis three lieutenants - Vorgorsh, Zulmork, and Cromaug - are the only other capable mages left of the Gordunni, and are fiercely loyal to Morkurk.\n\nI suspect that if we engage the Witch Lord that they will rush to his aid. Let's take them out first.", objectives = "" }
WordHunterWoW_QuestEN[34889] = { title = "Orbs of Power", description = "There's a minor fire we'll need to put out before we can enact my plan.\n\nMorkurk has placed powerful wards throughout Gordal Fortress that will prevent any sort of mass summoning - awfully detrimental to our scroll of mass teleportation.\n\nThankfully, no ogre would ever consider that a single enemy or two would have the gall to breach their walls.", objectives = "" }
WordHunterWoW_QuestEN[34890] = { title = "The Final Step", description = "It's time to fight fire with fire.\n\nWe have Morkurk cornered. His protections gone. Use the scroll once you engage Morkurk...\n\n...and enjoy the fireworks.", objectives = "" }
WordHunterWoW_QuestEN[34891] = { title = "Elemental Attunement", description = "Many shaman have sought the favor of the Throne of Elements.\n\nForming an elemental bond with the furies allows a shaman to not only know the will of the elements on Draenor, but also tap into a great font of elemental power.\n\nIf you are to discover the truth behind Gordawg's disappearance, you will need to succeed where others have failed and undertake the Ritual of Binding.\n\nFirst, you must prepare yourself. Seek out the elemental pillars upon the plateau and attune your spirit with the elements.", objectives = "" }
WordHunterWoW_QuestEN[34893] = { title = "Guardians of the Plateau", description = "The Elemental Plateau is sanctuary to the elemental spirits of Nagrand.\n\nThe greatest among the elementals on the plateau are the guardians; mighty elemental spirits that stand watch over their domain.\n\nThe guardians are pure and mighty spirits but a disturbance in the natural balance has caused them to grow unstable, corrupting the lesser elementals around them.\n\nIn order to restore balance to the plateau, the guardians must be destroyed. Only then will the cycle of rebirth begin.", objectives = "" }
WordHunterWoW_QuestEN[34894] = { title = "A Rare Bloom", description = "Many years ago I had a life-mate, Dahaka. We were only bound a short time before she was taken from me.\n\nI have lived long, but I have never known greater pain than that day. I was young and my grief was great; the earth quaked beneath my rage. I laid her to rest upon this cliff.\n\nIt is here where I too will rest, but first a favor.\n\nA rare bloom grows in a cave within the fiery, molten earth of the plateau. It was her favorite.\n\nI would lay the flower upon her grave one last time before I die.", objectives = "" }
WordHunterWoW_QuestEN[34897] = { title = "Rangari Roundup", description = "You have a keen eye, {class}.\n\nThere are Rangari like myself hidden throughout the Nightmarsh.\n\nI need reports from each of them to ensure the area is safe.\n\nPerhaps you can help me?", objectives = "" }
WordHunterWoW_QuestEN[34898] = { title = "Ikky", description = "", objectives = "" }
WordHunterWoW_QuestEN[34899] = { title = "A Choice to Make", description = "We're ready to start building. All that we need is for you to make a choice.\n\nThe blueprints are on the drafting table. Take a look.\n\nThen, let me know if we're going to construct a corral or a tankworks.", objectives = "" }
WordHunterWoW_QuestEN[34900] = { title = "New Babies", description = "That's better, but there's still something wrong. I'm getting desperate here, {name}.\n\nCan I call ya, {name}? Great.\n\nLook, I think I have it now. I know what's wrong.\n\nThey miss their babies.\n\nYeah! When they first came here, the, uh... the bastard hunters that... abandoned them said they left the babies behind.\n\nIf we're going to save them from a life of misery, if we're going to save those babies, <under his breath> and turn a tidy profit, we've got to get them some new babies!", objectives = "" }
WordHunterWoW_QuestEN[34905] = { title = "Placeholder Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[34908] = { title = "The Foot of the Fortress", description = "Your forces are at the ready and the scroll is prepared.\n\nIt's time for phase two - stealing a nexus crystal from a fortified ogre compound.\n\nWe'll save the scroll to bring in reinforcements in our confrontation with the Gordunni Witch Lord. Let's meet at the base of the Gordal Foothills to head into the fortress proper.", objectives = "" }
WordHunterWoW_QuestEN[34909] = { title = "While We're in the Neighborhood", description = "Ogres from the empire are known for being cold and calculating.\n\nWe are fortunate that their calculations are rarely spot on.\n\nMorkurk has been using enchanted bracelets to empower his minions with arcane strength.\n\nSince we're going to have to dispatch them anyways, we might as well get some reagents out of it.", objectives = "" }
WordHunterWoW_QuestEN[34910] = { title = "Vicious Viziers", description = "We can't just skate in, kill Witch Lord Morkurk, and leave.\n\nHis three lieutenants - Vorgorsh, Zulmork, and Cromaug - are all fiercely loyal to Morkurk, and are all respectable mages in their own right.\n\nI suspect that if we attempt to engage the Witch Lord immediately that they will rush to his aid and overwhelm us. We need to take out his lieutenants first.", objectives = "" }
WordHunterWoW_QuestEN[34911] = { title = "Orbs of Power", description = "Minor issue, I'm afraid.\n\nMorkurk has placed powerful wards throughout Gordal Fortress that will prevent any sort of mass summoning - not wonderful considering our plan.\n\nThankfully, no ogre would ever consider that a single enemy or two would attack, so we should be able to slip through their fortress relatively easily.", objectives = "" }
WordHunterWoW_QuestEN[34912] = { title = "The Final Step", description = "We have Morkurk cornered. He's all ours now. Use the scroll once you engage Morkurk...\n\n...and enjoy the blizzard of your forces raining down on his head.", objectives = "" }
WordHunterWoW_QuestEN[34913] = { title = "Dropping In", description = "Witch Lord Morkurk, the leader of the fortress, has catapults set up along the road into their compound.\n\nThat won't be a problem for us.\n\nTake out the ogres around the catapults and mark them for me. This vortex spell I have prepared will handle the rest.\n\nWe'll meet at the gate to the fortress once the catapults are gone.", objectives = "" }
WordHunterWoW_QuestEN[34914] = { title = "Target of Opportunity: Telaar", description = "We've received reports that the draenei enclave at Telaar has fallen to the Warsong.\n\nI sent a small group of shadow hunters to check on the situation.\n\nKajassa is their leader. Will you meet her there?", objectives = "" }
WordHunterWoW_QuestEN[34915] = { title = "I Help Ya Kill Dem", description = "Warsong come in an' kill de draenei rangers. No lettin' dem have dis place.\n\nYou an' me, Commanda. We gonna kill dem all.\n\nYou be distractin' dem an' I usin' me Loa ta finish dem off. You see.", objectives = "" }
WordHunterWoW_QuestEN[34916] = { title = "The Blessing of Samedi", description = "Three of mah shadow huntas come here wit' me. De Warsong kill dem.\n\nWe need ta help dey souls move on. Jus' in case ya find dem first, use dis on dere bodies.\n\nIt send dere souls ta Samedi, Loa of de Grave.", objectives = "" }
WordHunterWoW_QuestEN[34917] = { title = "Shields Up!", description = "The Warsong packleader is trying to raise Telaar's shield. If Kargora does that, the Warsong will have an impervious base.\n\nSo far, they've only managed to initiate the shield. This has the undesirable side effect of protecting the packleader and her shaman at the main crystal.\n\nActivate the crystals on the perimeter of Telaar. That will force the shield to fully deploy.\n\nOnce you do that, Kargora will be exposed.", objectives = "" }
WordHunterWoW_QuestEN[34918] = { title = "Shields Down!", description = "De time has come, commanda. Packleader Kargora an' de Arkonite Shield no longa protected.\n\nWe need ta kill her an' destroy de shield crystal.", objectives = "" }
WordHunterWoW_QuestEN[34921] = { title = "Cult of the Ravenspeakers", description = "These outcasts are not the only cursed arakkoa holding their ground in Arak.\n\nA curious cult has formed in worship of Ka'alu, my consort and the keeper of my brood. They are considered to be quite... odd.\n\nRegardless, the outcasts will need their help. Without the wings of the ravens, Iskar can never take his fight to the spires.\n\nTake this feather and place it in the offering basket south of here. The so-called \"Ravenspeakers\" will surely take notice.", objectives = "" }
WordHunterWoW_QuestEN[34922] = { title = "Words of the Raven Mother", description = "We came here to perform the ritual of calling to bring the return of the Raven Mother. We had distributed parts of the scroll to everyone and had just begun when we were attacked by the Bloodmane. Now most of the flock has been killed and fragments lay scattered across our homeland.\n\nThe ritual was a failure but we will not allow these mongrels to break our faith. We must continue our prayers here but we would be grateful if you can recover the scroll fragments for us.", objectives = "" }
WordHunterWoW_QuestEN[34923] = { title = "The Bloodmane", description = "We had just arrived and begun the service of the headless fowl when the Bloodmane attacked out of nowhere.\n\nClearly, this means that the Raven Mother wishes to test the worthiness of her children. Fear not, we are steadfast and will fervently continue our prayers regardless of what may come!\n\n<Sekara leans in and whispers to you.>\n\nAlthough, if you can get rid of the Bloodmane and their leader that would be a blessing as well.", objectives = "" }
WordHunterWoW_QuestEN[34924] = { title = "The Egg Thieves", description = "The Bloodclaw are sadistic creatures. They have attacked the Ravenskar before and have stolen the eggs of the sacred ravens.\n\nWhile you are within the Bloodclaw lands keep an eye out for the eggs.\n\nI'll be waiting for you at the nest with as many baskets for them as I can gather.", objectives = "" }
WordHunterWoW_QuestEN[34925] = { title = "Polishing the Iron Throne", description = "These stinking Blackrock cowards think they're humiliating me.\n\nThey're just making me angrier.\n\nOverseer Gotrigg, in the hut over there, carries my shackle key. If I'm going to get out of there, I'm going to need that key. Then... vengeance can begin.", objectives = "" }
WordHunterWoW_QuestEN[34932] = { title = "Guise of the Deceiver", description = "In a cave not far from here, there lives an old woman named Challe.\n\nI knew Challe many years ago when I was young; though as I have become old and grey, she has kept her youth and beauty.\n\nChalle was jealous of my love for Dahaka and I have long suspected that Challe had a part in her death. However, without evidence I could not bring justice against her.\n\nMeet with Challe and tell her that I am dying. Tell her that I wish to know the truth of Dahaka's fate before I leave this world.", objectives = "" }
WordHunterWoW_QuestEN[34938] = { title = "Ralshiara's Demise", description = "It was said in the Journal of the Rising Sun that eating in the mornings cannot be done without harming a few eggs.\n\nThe Bloodmane matron, Ralshiara, feasts upon sacred raven eggs for her snacks. How dare she! She must die for her sins!\n\nTake the path south over the mountains to reach the accursed home of the Bloodmane.\n\nTake this trinket, it fell to us from the heavens as a sign of the Raven Mother's favor and with it you might have a chance.", objectives = "" }
WordHunterWoW_QuestEN[34939] = { title = "Declawing The Bloodmane", description = "It is written in the Scroll of Sermons to \"Bite the claw that strikes you.\"\n\nTake the path south from here that leads over the mountain to the Bloodmane valley in the west. There you will find those of their tribe who can use a primitive form of magic. Slay them and remove their paws.\n\nOnce you have obtained a few bring them back to me in the nest so that they may be offered to the Raven Mother!", objectives = "" }
WordHunterWoW_QuestEN[34941] = { title = "The Debt We Share", description = "These mortal shells that we call bodies are not ours to keep. The body is a gift of earth that must one day be returned from whence it came.\n\nThe time has come for this body to return to the elements.\n\nKnow that you have lifted the weight from an old heart, {name}. As I pass on from this realm, I do so without regret. I have fought on behalf of my people and my land, I have served the elements, and I have loved.\n\nIt would honor me if you would stay during these final moments, {class}.", objectives = "" }
WordHunterWoW_QuestEN[34942] = { title = "Back from Beyond", description = "We must begin preparations for the Talon King's return.\n\nFrom within this realm, I can travel quickly to Veil Terokk.\n\nYou, however, should be returned to the other side. You are powerful, and will attract unwanted attention.", objectives = "" }
WordHunterWoW_QuestEN[34943] = { title = "An Old Friend", description = "Since the beginning, a shaman has been called to serve the Throne of Elements as its keeper. It is a lifelong calling and a new keeper is only called after the last has passed on.\n\nGar'rok has been our loyal keeper for many years, cleansing the Elemental Plateau during countless cycles of rebirth.\n\nOur keeper is dying, and soon another will be called in his place. When he passes, he should not be alone. Go to him, {name}.\n\nEase his pain.", objectives = "" }
WordHunterWoW_QuestEN[34947] = { title = "Shredder Manual", description = "Hey! I hear there's a curious object nearby. Scouts say it's some kind of shredder manual.\n\nGo check it out for me, will ya? I wonder if it has to do with this new prototype I've been hearin' about...", objectives = "" }
WordHunterWoW_QuestEN[34948] = { title = "Shredder Manual", description = "I've been hearing rumors of this new prototype shredder the Iron Horde's engineers have been working on.\n\nI think we ought to investigate. A shadow hunter spotted some sort of shredder manual, and it might have something to do with that prototype.", objectives = "" }
WordHunterWoW_QuestEN[34949] = { title = "Joining the Ranks", description = "", objectives = "" }
WordHunterWoW_QuestEN[34950] = { title = "Dreadpiston", description = "Nearby, a group of Iron Horde took over a key strategic position with surprising alacrity.\n\nThey used a machine they call Dreadpiston to terrible effect in the siege, and I believe we need to destroy that machine before moving against the Iron Horde in Tuurem.", objectives = "" }
WordHunterWoW_QuestEN[34951] = { title = "They Call Him Lantresor of the Blade", description = "The Burning Blade clan at Hallvalor is supplying the Warsong with weapons and warriors. We cannot let this continue.\n\nThere's a young blademaster who's been exiled from the Burning Blade for many years. They call him Lantresor of the Blade.\n\nMy rangari recently saw him return to Hallvalor to challenge the blademaster leadership. Instead, they clapped him in chains.\n\nMaybe he's still alive. Maybe he'll help you deal with the Burning Blade.", objectives = "" }
WordHunterWoW_QuestEN[34952] = { title = "The Friend o' My Enemy", description = "Hallvalor is the ancestral home o' the Burning Blade clan. Since they be such fast friends, the Warsong allow the blademasters an' their shaman to remain in Nagrand when all o' the other clans are forced out.\n\nBlah, blah, blah.\n\nI say, if they're the friend o' my enemy, then they're my enemy, and that's all I need to know!", objectives = "" }
WordHunterWoW_QuestEN[34953] = { title = "Blood of the Burning Blade", description = "Hallvalor is the ancestral home of my clan, the Burning Blade. When the new warlord and his family came to power, I was exiled for being a half-breed.\n\nI want justice.\n\nI suspect you won't mind killing along the way. Not that you'll have any choice.", objectives = "" }
WordHunterWoW_QuestEN[34954] = { title = "The Blade Itself", description = "When they clapped me in irons, the Burning Blade instructor, Luhk the Keen-Eyed, took my blade. He's an honorable orc, even if his training techniques are counter-productive.\n\nI want my blade back, {class}.", objectives = "" }
WordHunterWoW_QuestEN[34955] = { title = "Not Without My Honor", description = "The blade is not the only important item a blademaster carries.\n\nOnce he has passed his final tests in the Masters' Caverns, the blademaster is given the honor of wearing the Burning Blade's banner.\n\nWhen my petition to reclaim my rightful place with the clan fell upon deaf and craven ears, I was stripped of that honor.\n\nNo doubt, my banner has been stored away somewhere in Hallvalor. They'll give it to some other aspiring blademaster if they don't burn it first.", objectives = "" }
WordHunterWoW_QuestEN[34956] = { title = "Meet Me in the Cavern", description = "It's time, {class}. Time to face the masters.", objectives = "" }
WordHunterWoW_QuestEN[34957] = { title = "Challenge of the Masters", description = "The time has come to challenge the Burning Blade masters.\n\nGo to the back of the cavern. There you will find the challenge ring and the masters watching over it from above.\n\nPull the blade from the middle of the ring to issue your challenge. My clan values honor above all else and will respect your claim to trial by combat.\n\nAs reward, you will be allowed to walk away with your life. Or, you will be dead.", objectives = "" }
WordHunterWoW_QuestEN[34958] = { title = "The Shadow of the Worldbreaker", description = "Looks like we'll soon have another obstacle in our way: that ridiculously large tank that they have pointed at the Dark Portal. The Iron Worldbreaker, I think they call it.\n\nIf I had some documentation on how it might work, then I might be able to figure out how to shut it down. Maybe some o' those machinists and laborers have some documentation on how it works?", objectives = "" }
WordHunterWoW_QuestEN[34959] = { title = "Dreadpiston", description = "The Iron Horde overtook a peaceful draenei outpost without mercy.\n\nThey used a machine they call Dreadpiston to level the town in minutes.\n\nDestroy it.", objectives = "" }
WordHunterWoW_QuestEN[34960] = { title = "The Land Provides", description = "The icevines of the Shivering Trench have developed a powerful resistance to cold temperatures. Integrating them into the construction materials of the garrison should prove useful.", objectives = "" }
WordHunterWoW_QuestEN[34962] = { title = "Khadgar's Plan", description = "We have the Iron Horde backed into a corner now, thanks to you.\n\nIt is almost time to enter the city of Shattrath and repel them.\n\nFirst, we must meet Khadgar and some new allies.", objectives = "" }
WordHunterWoW_QuestEN[34963] = { title = "Khadgar's Plan", description = "Shattrath must not fall into the hands of the Iron Horde. It is time again for me to get my hands bloody.\n\nWe will tell Khadgar we are ready to enter the city and take back what is rightfully ours.", objectives = "" }
WordHunterWoW_QuestEN[34964] = { title = "The Farseer Awaits", description = "Your presence has been requested at the Throne of Elements, {name}.\n\nFarseer Drek'Thar heard the call of the furies upon the wind and made the journey to commune with the elements.\n\nThe Farseer has sent word that you are to join him at the Throne of Elements.\n\nGo and see what the elements would have of you.", objectives = "" }
WordHunterWoW_QuestEN[34965] = { title = "Called to the Throne", description = "It was not long after I arrived in Nagrand that the voice of Kalandrios called out to me upon the wind.\n\nIt is a great honor to be called to the Throne of Elements, but my heart was heavy sensing the purpose.\n\nThere is dark malaise in the air, it can be felt all around us. It surrounds all life here...enveloping...smothering...\n\nCome, it is time we commune with the furies and lend them our aid. An invisible shadow has been cast upon this valley and it may be up to us to remove it.", objectives = "" }
WordHunterWoW_QuestEN[34971] = { title = "The Only Way to Travel", description = "Call me cautious but I kept a few flares just in case we needed to evac.\n\nI'm glad that wasn't needed but we could still use the ride back to the arsenal.\n\nAre you ready, sir?", objectives = "" }
WordHunterWoW_QuestEN[34972] = { title = "Armor Up", description = "", objectives = "" }
WordHunterWoW_QuestEN[34976] = { title = "Dropping Bombs", description = "The Gordunni have only a single path to their fortress and it is well-defended from a large attack.\n\nThankfully they wont be expecting just the two of us to be attempting to break in.\n\nThis is a great opportunity to take out their defenses and get some target practice for our gunners back at the artillery tower.\n\nTake these smoke grenades and use it to call in an artillery strike on their catapults as we head up.", objectives = "" }
WordHunterWoW_QuestEN[34977] = { title = "Supply Recovery", description = "We seem to have arrived at just the right time!\n\nThe Gordunni have been enchanting armaments for the Iron Horde and it looks like they haven't picked up the latest shipment.\n\nWe could put that gear to far better use in our artillery tower! Lets go hunt down their shipping containers. I brought some signal flares that we can use to call in an air pick-up when we've secured the shipment.", objectives = "" }
WordHunterWoW_QuestEN[34978] = { title = "Prized Repossessions", description = "The Gordunni have plagued the people of Shattrath ever since the city was founded. Over time they amassed quite a hoard of weapons they captured from our defenders in raids.\n\nGetting these weapons in the hands of our soldiers would be practical and I personally would like to get them out of the hands of the ogres.\n\nWhile we are in here can you do me a favor and gather up any of those weapons you come across.", objectives = "" }
WordHunterWoW_QuestEN[34979] = { title = "Punching Through", description = "To secure the fortress we need to kill Witch Lord Morkurk, but I don't think we should go straight after him.\n\nHis three lieutenants - Vorgorsh, Zulmork, and Cromaug - are all powerful mages, and all of them are fiercely loyal to Morkurk.\n\nI suspect that if we engage the Witch Lord that they will rush to his aid. Let's take them out so that cannot happen.", objectives = "" }
WordHunterWoW_QuestEN[34980] = { title = "The Lord of the Gordunni", description = "Witch Lord Morkurk is the leader of the Gordunni. We need to kill him to secure the jovite for use in our artillery tower.\n\nMorkurk is an accomplished mage so you better be prepared. Here, take the rocket pack and use it if you need to avoid any of his deadly magic.\n\nArchenon poros!", objectives = "" }
WordHunterWoW_QuestEN[34981] = { title = "The Only Way to Travel", description = "Call me cautious but I kept a few flares just in case we needed to quickly escape.\n\nI'm glad that wasn't needed but we could still use the ride back to the artillery tower.\n\nAre you ready sir?", objectives = "" }
WordHunterWoW_QuestEN[34982] = { title = "Armor Up", description = "", objectives = "" }
WordHunterWoW_QuestEN[34987] = { title = "The Gunpowder Plot", description = "Ey, pal! We got an issue, here.\n\nMe ol' pal Thaelin's rigged together this here plunger out of spare Blackrock parts - engineerin' whiz that he is - but we're gonna need some gunpowder if we really want ta' do any damage.", objectives = "" }
WordHunterWoW_QuestEN[34991] = { title = "To the... Rescue?", description = "The Parchment of Dust reads: \"Put the featherless against one another so that our claws remain unsullied!\" How wise the high Ravenspeaker is to foresee this day.\n\nThere is a great beast on the hillside to the west by the name of Stonescale. It has abducted one of the flock and despite our many attempts we have been unable to defeat it. \n\nGo, prove yourself by slaying the beast and rescuing Tillik! Fulfill your destiny in the name of the Raven Mother!", objectives = "" }
WordHunterWoW_QuestEN[34993] = { title = "Joining the Ranks", description = "", objectives = "" }
WordHunterWoW_QuestEN[34994] = { title = "Forever Young", description = "All this sitting around is horrible for business.\n\nI have to find a way to recoup some of my lost profits.\n\nThose Draenei females are obsessed with the way their horns look.\n\nI overheard one of them talking about a root that grows in Blademoon Bloom that supposedly reduces horn shedding or something.\n\nI bet I could sell that root to them for a pretty nice profit.\n\nI'll give you a cut if you help me get a supply going.", objectives = "" }
WordHunterWoW_QuestEN[34995] = { title = "Botani Beatdown", description = "Gidwin is doing much better. Thank you, {name}.\n\nI can't believe the draenei have lived alongside those horrible monsters for so long.\n\nMaybe we should show these beasts what happens when you mess with an Azerothian.", objectives = "" }
WordHunterWoW_QuestEN[34996] = { title = "Rotting Riverbeasts", description = "The botani are infecting the local riverbeasts with some kind of strange flesh-eating plant.\n\nI fear this infection could spread to our people.\n\nIf you see any infested riverbeasts, kill the blooming plants that inhabit their bodies... before they kill you.", objectives = "" }
WordHunterWoW_QuestEN[34997] = { title = "Slumberbloom", description = "Huh?... Oh my, I appear to have fallen asleep again.\n\nThese slumberblooms are nothing but trouble. One second I'm fighting botani and the next I'm dreaming I'm an elekk dancing with riverbeasts.\n\n*Yawn* We really should do something about all these slumberbloo *Yawn* ... ZZZZzzzzzzzz\n\n<You gather a small handful of pebbles laying by the sleeping draenei.>", objectives = "" }
WordHunterWoW_QuestEN[34998] = { title = "Talon Watch", description = "By now you must be wondering about all of this curse business. What could distort a majestic arakkoa into... well, into this?\n\n<Reshad drags a crooked hand through the mottled feathers about his face.>\n\nA raven is prepped and waiting to fly you to Talon Watch. There shall your eyes be opened to the origin of this curse.\n\nPresent the Eye of Anzu to Talon Guard Kurekk. He will guide you from there.", objectives = "" }
WordHunterWoW_QuestEN[34999] = { title = "Hatred Undying", description = "The blood of the dead god, Sethe, lingers in the pools here. And with it, his hatred of Rukhmar and Anzu.\n\nSo strong was this hate that it animates the blood even now, eons after he was slain by his fellow gods.\n\nI need the congealed blood that holds those spiteful creatures together.\n\nThere is nothing the Adherents fear more than the power of this curse - what if we could brandish it against them?", objectives = "" }
WordHunterWoW_QuestEN[35000] = { title = "Banished From the Sky", description = "The Adherents have been casting their enemies into the hollow for generations.\n\nThe pools carry Sethe's dying curse, crippling arakkoa with visions of darkness and intense pain. The mind reels, the body writhes, and the wings wither.\n\nMost arakkoa die or go insane. Only the strongest can resist - seek them out and use the Eye of Anzu to help them to their senses.\n\nBeware, for the worshippers of Sethe also prey on these survivors to fill their ranks.", objectives = "" }
WordHunterWoW_QuestEN[35001] = { title = "Gaze of the Raven God", description = "The Sethekk are breeding vile wind serpents from Sethe's blood and bones. With these creatures, they will tear apart the sky.\n\nThe nests are protected by powerful magic, but Anzu's gaze should penetrate them with ease.\n\nLet us visit the nests and destroy them!", objectives = "" }
WordHunterWoW_QuestEN[35002] = { title = "Sons of Sethe", description = "Many years have passed since anyone has been in contact with Anzu. He faded away, as Terokk did, to take refuge in the shadows.\n\nIf we are to coax him back, we should make an offering.\n\nSethe took the sky from us all - it seems fitting to take the wings of his children.", objectives = "" }
WordHunterWoW_QuestEN[35003] = { title = "Ritual Severance", description = "I could not defeat this curse, and long ago resigned myself to rest in darkness.\n\nBut the Sethekk are performing dark rituals to draw me back, slowly binding me to Sethe's will. Should they succeed, Sethe would have me draw a dark cloak across the horizon, and bathe the world in his blood.\n\nDisrupt their rituals, so that I may return with my own free will. Then, together, we shall bring an end to Sethe's return.", objectives = "" }
WordHunterWoW_QuestEN[35004] = { title = "Servants of a Dead God", description = "Even in death, Sethe exerts influence. The Sethekk cult was born of this influence: led by a false king in service of the dead god.\n\nSilence their prophets, for they seek a future of black seas and blighted skies.\n\nDefeat their chosen champions, for they have pledged themselves to a lie.", objectives = "" }
WordHunterWoW_QuestEN[35005] = { title = "Prepare for Battle", description = "There's nowhere to hide up here. We need to keep moving, and to do that, we need to pass right through the heart of the Iron Horde.\n\nIt's time to turn this unarmed group of prisoners into an army.", objectives = "" }
WordHunterWoW_QuestEN[35006] = { title = "Poison Paralysis", description = "There are others from the caravan that have gone missing.\n\nMy guess is they have been taken into Blademoon Bloom by the botani.\n\nYou have to rescue them, {name}. You are our only hope.\n\nHere, take some of this elixir I just made, chances are you will need it.", objectives = "" }
WordHunterWoW_QuestEN[35007] = { title = "Rendezvous with the Ritualists", description = "Our dear brother Sekara went to the Ravenskar with some of the flock to enact the great ritual of purification.\n\nNo one has been sent back to the nest for supplies in the past day; caught up in prayers I suppose.\n\nI would go check on him but I need to make sure the scribe didn't mess up her transcription of my latest sermon. Could you do it? I'll be there in... well, who knows...", objectives = "" }
WordHunterWoW_QuestEN[35009] = { title = "Call of the Raven Mother", description = "All is now in its place to begin the ritual of calling that will bring the Raven Mother back to the nest.\n\nYou have fulfilled all of the tests we have put before you so it is only fitting that you join with us and participate in the ritual.\n\nSoon the Raven Mother herself will appear before us! Oh my feathers are tingling in excitement!\n\nSpeak to me again when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[35010] = { title = "The High Ravenspeaker", description = "Yes, I knew you were worthy!\n\nThe Writ of Faith says that great doubt will come in time of crisis but one must put their trust in the Raven Mother and all will be as it should!\n\nCome, come, we must go to the High Ravenspeaker!", objectives = "" }
WordHunterWoW_QuestEN[35011] = { title = "The False Talon King", description = "Ikiss was once a respected sage among the Adherents, but his search for the truth of Terokk's fall led to his own banishment.\n\nIkiss became obsessed with Terokk, even claiming to be the old hero reborn. He commands the Sethekk, promising untold power in a new age of darkness.\n\nKnow this: Ikiss is no Talon King. Slay the delusional fool, and search him for anything useful. He is known to collect powerful trinkets.", objectives = "" }
WordHunterWoW_QuestEN[35012] = { title = "Sethe, the Dead God", description = "The time has come to put an end to Sethe. I killed him before, and with your help I shall do it again.\n\nReady yourself for a fight - the cultists will not stand idly by while we stamp out their god.", objectives = "" }
WordHunterWoW_QuestEN[35013] = { title = "Lithic's Gift", description = "<Kurekk squints at the bangle, rotating it slowly in his claws.>\n\nThere is an inscription on the inside.\n\n\"To my father, may Rukhmar illuminate your path. With love, Lithic.\"\n\nIt cannot be... This is Terokk's bangle! It was a gift from his daughter, he wore it for years until...\n\nWell, we had better return it.\n\nTerokk built a memorial to Lithic not far from Talon Watch. It should rest there.", objectives = "" }
WordHunterWoW_QuestEN[35014] = { title = "Blademoon Bloom", description = "We are out of options.\n\nI'm going into the bloom to find out what's going on. I'll meet you inside.\n\nGoodluck, {class}.", objectives = "" }
WordHunterWoW_QuestEN[35015] = { title = "Gestating Genesaur", description = "This is bad. A genesaur is starting to sprout right here in the bloom.\n\nThis is the first reported case of a genesaur being born in draenor in over three hundred years.\n\nNo wonder the botani have been acting so crazy. They are bringing back bodies to fertilize that monstrosity.\n\nWe have to kill it before it gets any larger. Once fully grown there is no stopping that beast.", objectives = "" }
WordHunterWoW_QuestEN[35016] = { title = "Basic Skulltaking", description = "My hunters are all dead, you will be my hunting pack now.\n\nFind their bodies and take their skulls.  I will choose which to honor and which to cast aside.  It is our way.\n\nI will go further and see what other skulls may be found here.", objectives = "" }
WordHunterWoW_QuestEN[35017] = { title = "Skulltaker's Revenge", description = "The others... gone or wandered into the haze.  It called to me as well but I am too strong.  I chose to kill until they crushed my body.  I haven't killed enough of them yet {name}, not enough!  Go.  Kill more of them and tell my hunt leader that I don't go alone into the dark.", objectives = "" }
WordHunterWoW_QuestEN[35019] = { title = "Prepare for Battle", description = "There's nowhere to hide up here. We need to keep moving, and to do that, we need to pass right through the heart of the Iron Horde.\n\nIt's time to turn this unarmed group of prisoners into an army.", objectives = "" }
WordHunterWoW_QuestEN[35021] = { title = "Mysterious Pod", description = "This pod is similar to the ones growing on or near the bodies around here, except this one is pulsating weirdly.  Grulkor might know more about this.", objectives = "" }
WordHunterWoW_QuestEN[35022] = { title = "Lighting The Darkness", description = "The spirits of my ancestors have always been drawn to the mountain of Oshu'gun. Now, I too feel this pull deep within my soul...but something is not right.\n\nThe presence that beckons us has grown dark and ominous. It consumes the souls of the dead, the souls of my ancestors, {name}.\n\nSomething must be done.\n\nTake hold of the spirit torch and light the ceremonial pyres in the Ancestral Grounds.\n\nThe flame of the spirit torch upon the pyres will calm the restless spirits being drawn into the void.", objectives = "" }
WordHunterWoW_QuestEN[35023] = { title = "Echoes of the Past", description = "When a spirit is consumed by the void, an echo of the soul is all that is left behind.\n\nNeither in the physical or spiritual sense of the word would these echoes be considered 'alive.' The echo is merely a twisted reverberation of the anguish left behind by the soul as it is consumed.\n\nIf left unchecked, the echoes will lash out against the living and stir the spirits of the dead from their graves.\n\nIn order to restore peace to the Ancestral Grounds, these echoes must be put to rest.", objectives = "" }
WordHunterWoW_QuestEN[35024] = { title = "Golmash Hellscream", description = "Those who die in brutal combat often enter the spirit world in unrest. So it was with Golmash, father of Grommash Hellscream.\n\nCrushed within the jaws of a hulking gronn, Golmash still found the strength to bury his axe Gorehowl deep into the eye of the monster. When they fell, it was the gronn who died first.\n\nSuch is the heroic death that every Warsong dreams of, yet few attain. But Golmash's mighty spirit lingers restlessly, stirring the other spirits into unrest.\n\nPut his mighty soul to rest, {name}.", objectives = "" }
WordHunterWoW_QuestEN[35025] = { title = "We Have Company", description = "Outsider, I've spotted Iron Horde soldiers nearby.\n\nIt is bold, even for them, to venture into such deadly territory.\n\nIf you do not deal with their presence, they will surely be a threat to your camp.", objectives = "" }
WordHunterWoW_QuestEN[35026] = { title = "On the Mend", description = "Nisha will heal.\n\nThis ordeal has taken a toll on her. She needs water and rest.\n\nI will bring her to my camp and make her comfortable.\n\nWill you meet us there with some fresh water?", objectives = "" }
WordHunterWoW_QuestEN[35027] = { title = "Clearing the Way", description = "The dead ones were the strong ones it seems. The weak ones wander about killing invaders to this marsh.\n\nIt feels... wrong... to kill them, but they are worthless and get in our way. Kill these shambling fools so we can move further into the marsh easily.", objectives = "" }
WordHunterWoW_QuestEN[35029] = { title = "The Secret of the Fungus", description = "It smells here and there are whispers.\n\nI feel there is a connection between the plants and beasts here. Special mushrooms seem to focus the beasts' attention.\n\nGo and get some of these for me. I... need... them.", objectives = "" }
WordHunterWoW_QuestEN[35030] = { title = "A Grim Harvest", description = "The larger monsters are the key to my destiny, I can feel it. The pods growing on them are even bigger than the one you brought me earlier.  Get me a few of these, they will be... helpful... soon.", objectives = "" }
WordHunterWoW_QuestEN[35031] = { title = "A Heartfelt Search", description = "I can feel a powerful presence in the marsh {name}.  I feel drawn to it.  We must go and take what is there.  Go on ahead, I must finish consuming these mushrooms.", objectives = "" }
WordHunterWoW_QuestEN[35032] = { title = "Into Anguish", description = "Rulkan's gift to you, the Fragment of Anguish, will allow you to pass into the fortress unhindered. Go up these stairs to the doorway, then use the fragment to enter the compound.\n\nOnce you are inside, you will find three altars powering the magical barrier around their stronghold.\n\nDestroy these runes, and Yrel and I will be able to join you in finding Ner'zhul.", objectives = "" }
WordHunterWoW_QuestEN[35033] = { title = "Welcome to Gorgrond", description = "Gorgrond is one of the most untamed landscapes in all of Draenor.\n\nOnly the most skilled of rangari venture this deep into the wilds.\n\nIt is their camp we are heading for. If you wish to travel ahead, it can be found down this path and to the right.\n\nMaraad and I shall follow after you momentarily. We still have some logistics to work out before we leave the landing.", objectives = "" }
WordHunterWoW_QuestEN[35035] = { title = "Seedbearers of Bad News", description = "When these seedbearers are slain their seeds survive. From them spring new seedbearers, not over years, but hours.\n\nLeaving their remains here would soon cause your camp to be overrun.\n\nBurn them, outsider, if you wish your camp to endure.", objectives = "" }
WordHunterWoW_QuestEN[35036] = { title = "Is This One of Yours?", description = "I found this one skulking nearby. He claims to be an ally of yours.\n\nIs this true? Or does he cook slowly over my fire?", objectives = "" }
WordHunterWoW_QuestEN[35037] = { title = "Bad at Breaking", description = "Screams and growls echo from the canyon below - even more than usual.\n\nI don't dare leave Nisha here alone yet.\n\nWill you investigate those noises, {name}?", objectives = "" }
WordHunterWoW_QuestEN[35038] = { title = "What the Bony Xuk?", description = "Good to see your bones are still intact, {name}. Xuk's too.\n\nWhen you set off into the heart of the canyon, Xuk came to offer my services. Xuk not letting you take all of the skulls!\n\nXuk will share with you powerful spirit magics my clan has passed down for many generations. While Xuk make preparations, you must gather the reagents.\n\nFirst, we'll need crystals from husks of goren corpses. You can find their bodies in the canyon.", objectives = "" }
WordHunterWoW_QuestEN[35040] = { title = "Heart of the Fen", description = "If only the trees here weren't screaming at me I could concentrate better. Never mind, they are only trees.\n\nThis spot is used up but now I can feel a much stronger presence deeper in the marsh.  I will go there now and take what is rightfully mine!\n\nThen I will share it... with everyone...", objectives = "" }
WordHunterWoW_QuestEN[35041] = { title = "Xuk It!", description = "It is done.\n\nWith this enchantment, not only can you roam amongst the goren freely, but you can move as they do.\n\nYour travels through Gorgrond are now made simple. You have safe access to places otherwise impossible to reach.\n\nXuk's ancestors have made it so.", objectives = "" }
WordHunterWoW_QuestEN[35045] = { title = "In Ared's Memory", description = "My master has gone on to the Light, but I will continue his work.\n\n<Miall looks to Ared >\n\nShanai ortar, Ared.\n\nI will have his body sent to Auchindoun. For now, show me this artillery tower of yours.", objectives = "" }
WordHunterWoW_QuestEN[35050] = { title = "Rescue Rangari", description = "Many of our rangari have not been accounted for. It would seem the followers of Iyu have taken captives.\n\nWe will continue to search the area for survivors.\n\nIn the meantime, follow the Wildwood Wash west toward Highpass and look for any signs of our rangari comrades.\n\nOur people are stout and capable survivors. You may find more than you expect. Have them stay near the road and we will follow as soon as this... dwarf creature... has fixed his mechanical vessel.", objectives = "" }
WordHunterWoW_QuestEN[35055] = { title = "Lost Mole Machines", description = "Few people know the Blackrock clan better than Dark Iron dwarves.\n\nSo after Tanaan, we sent a bunch of mole machines to Gorgrond to build a listenin' post to keep an eye on them.\n\nMe own mole machine got way off course an' I got separated. It didn't take long to figure out all the other mole machines got off course as well.\n\nAccordin' to the readin's in me tank, a mole machine surfaced somewhere way to the west of here.\n\nMind scoutin' ahead while we get this tank operational?", objectives = "" }
WordHunterWoW_QuestEN[35058] = { title = "The Mysterious Flask", description = "The liquid swirling around inside the flask clearly has strong alchemical properties, but its nature is beyond your training.\n\nYou have heard that one of the Stonefang refugees at your garrison has some knowledge of the alchemy of Draenor. Perhaps he could tell you more?", objectives = "" }
WordHunterWoW_QuestEN[35059] = { title = "Along the Riverside", description = "Vindicator Yrel has taken most of our forces north. She's establishing a forward base along the Skysong River.\n\nShe'll want to know that we're almost ready to move against Grommashar.\n\nI'm sure she can also use your help dealing with the Warsong orcs at Lok-rath.", objectives = "" }
WordHunterWoW_QuestEN[35060] = { title = "Terms of Surrender", description = "Believe it or not, I have good news: we've already taken Lok-rath.\n\n<The vindicator beams with pride.>\n\nOur soldiers have captured most of the Warsong, including their leader, Uruk Foecleaver.\n\nI saved the honor of accepting his surrender for you. They're waiting for you inside, commander.", objectives = "" }
WordHunterWoW_QuestEN[35061] = { title = "The Pride of Lok-rath", description = "You think the Warsong are so easily defeated?\n\n<There's a rasping sound, like rope on metal.>\n\nI'm already tired of you Alliance, and you've just invaded my homeland.\n\n<The sound becomes more pronounced as Uruk Foecleaver looks you straight in the eye.>\n\nThere will be no surrender. The Warsong bow to no one!", objectives = "" }
WordHunterWoW_QuestEN[35062] = { title = "Lok-rath is Secured", description = "With their leader dead, the remaining Warsong will be easier to finish.\n\nAs soon as that's done, I'll pull our soldiers out of Lok-rath and head for Grommashar.\n\nIf you're heading back to Telaari Station, would you please inform D'kaan?", objectives = "" }
WordHunterWoW_QuestEN[35063] = { title = "We Need An Outpost", description = "Commander, we've gathered enough materials to build an outpost that will support our mission against the Iron Horde.\n\nHow shall we proceed?\n\nA lumber yard would be valuable for gathering resources in the dense overgrowth to the south, and in confronting the plant monstrosities that defend it.\n\nOn the other hand, a sparring arena would provide us the brutish forces we'd need to push through the magnaron wastelands to the north.\n\nWhen you're ready, make your choice on the table.", objectives = "" }
WordHunterWoW_QuestEN[35065] = { title = "A Harvester Has Come", description = "This is what happens when one stands in the path of a genesaur. And where a genesaur walks, the botani follow.\n\nI saw one entering our shelter cave along the northern side of the camp.\n\nIt is commanding the podlings to gather the corpses of our fallen brethren and must be stopped.\n\nI must tend to our wounded, and gather supplies for our departure.\n\nIf you are serious about being a hero, venture into the cave and slay this botani.", objectives = "" }
WordHunterWoW_QuestEN[35066] = { title = "Fire Ammonite", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Frostfire Ridge for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", objectives = "" }
WordHunterWoW_QuestEN[35067] = { title = "Silence the War Machines", description = "The Iron Horde supplied Lok-rath with war machines from Ironfist Harbor. It won't take long for them to level Yrel's Watch.\n\nSomeone has to silence those war machines!", objectives = "" }
WordHunterWoW_QuestEN[35068] = { title = "If They Won't Surrender...", description = "This is the backbone of the army we intend to send against Garrosh Hellscream and Grommashar.\n\nIf they won't surrender, we have no choice but to eliminate the Warsong.", objectives = "" }
WordHunterWoW_QuestEN[35069] = { title = "Terror of Nagrand", description = "<The body of a fallen soldier lies here. Blood and gore trail back from the corpse to the entrance of the cave just to the north.>\n\n<Judging by the howls and the carnage surrounding the den, something truly terrifying must be in there.>", objectives = "" }
WordHunterWoW_QuestEN[35070] = { title = "Shut 'er Down", description = "Burrowing native creatures known as \"goren\" have tunneled into our crystal mines. Judging from our experience at the gates, I suspect my own experimental resonance crystal is whipping the native wildlife into a frenzy.\n\nEnter the Elodor Dig to the north and disable the malfunctioning resonance crystal!\n\nBe careful - my earthworkers report that the mine is crawling with those beasts.", objectives = "" }
WordHunterWoW_QuestEN[35071] = { title = "Jawless Skulker", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Gorgrond for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", objectives = "" }
WordHunterWoW_QuestEN[35072] = { title = "Fat Sleeper", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Nagrand for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", objectives = "" }
WordHunterWoW_QuestEN[35073] = { title = "Blind Lake Sturgeon", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Shadowmoon Valley for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", objectives = "" }
WordHunterWoW_QuestEN[35074] = { title = "Blackwater Whiptail", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Talador for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", objectives = "" }
WordHunterWoW_QuestEN[35075] = { title = "Abyssal Gulper Eel", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Spires of Arak for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", objectives = "" }
WordHunterWoW_QuestEN[35077] = { title = "Defungination", description = "Have you seen the fungus out there in the water? It's growing faster than a baby ravasaur from Un'goro, and if we don't get it under control, the Gearworks is gonna be ruined like our last village.\n\nUncle Krixel used to tell me to burn away the red fungus because that's what makes it grow so fast.\n\nYou could help us out by taking a flame blaster and clearing out some of those spores down in the shallows.", objectives = "" }
WordHunterWoW_QuestEN[35079] = { title = "Spore-be-Gone", description = "We got an emergency!\n\nA bunch of spore drifters have infested the shore and tore up our Spore-B-Gone turrets.\n\nWe're caught with our armor off here! If we don't get those turrets back online then those spores are going to float right in to town and then we'll have another Pinchwhistle Point on our hands!\n\nWe need to get out there and manually activate them.\n\nWell? Are you in?", objectives = "" }
WordHunterWoW_QuestEN[35080] = { title = "The Mother Lode", description = "Hey we got ourselves a crisis here! Our zeppelin \"The Mother Lode\" crashed onto the south mountain range.\n\nIt was supposed to only be on an observation mission, what could have happened?\n\nWe got to get down there quick and I'm going to need your help on this.\n\nAre you with me?", objectives = "" }
WordHunterWoW_QuestEN[35081] = { title = "Clearing Out Before Cleaning Up", description = "Here's the situation.\n\nWe need to get this salvage operation moving ASAP, but the ship went down right in the middle of the wasp nests.\n\nThe ugly bugs are all over the place, and I can't call my team in here to start work until they're taken care of.\n\nGo kill as many of 'em as you can and I'll cut you in on some of the haul.", objectives = "" }
WordHunterWoW_QuestEN[35082] = { title = "Getting the Crew Back Together", description = "Oh wow, the debris is all over the mountainside! The survivors won't make it if we don't do something quick. They need healing NOW!\n\nHere, take my bandages and go patch them up.", objectives = "" }
WordHunterWoW_QuestEN[35083] = { title = "Disrupt the Rituals", description = "No longer do the Warsong seek to be one with the elements; instead they abuse their power by using it to channel the darkness of the void.\n\nI will not tolerate these rituals to continue. Locate the ritual totems the Warsong use to channel the void and destroy them.\n\nThe gift of the elements was not given to the orcs only to be defiled and used as a plaything.", objectives = "" }
WordHunterWoW_QuestEN[35084] = { title = "Silence the Call", description = "The Warsong clan, in their lust for dominance, have turned to the darkness of the void for power. Dark shamanism is a loathsome, dangerous practice that abuses the elemental gift I have bestowed upon them.\n\nThere is one among the Warsong that calls out the loudest to the void, an elder shaman named Kuhlrath. Slay him and the rest of his dark shaman.\n\nI will not allow the Warsong to abuse the elements and desecrate tradition.", objectives = "" }
WordHunterWoW_QuestEN[35085] = { title = "Through the Nether", description = "The rituals have been disrupted, yet the nether beacons still glow with power....\n\nThis can only mean that the beacons are powered from within the Twisting Nether itself!\n\nThe connection to the void must be severed! There is but one way to accomplish this; you must slay the void creature that maintains the connection with our world.\n\nLay your hands upon a beacon and travel into the Twisting Nether. When you have arrived on the other side, locate a Shamanstone and use it to contact me.", objectives = "" }
WordHunterWoW_QuestEN[35086] = { title = "The Void March", description = "Hidden behind the veil of the Twisting Nether, the abominations of the void march upon Oshu'gun. The great void growing deep within the mountain has drawn them like moths to a flame.\n\nWave upon wave, the creatures of the void march upon the mountain and sacrifice themselves to Invalidus. The void lord Invalidus cannot be allowed to feast upon the other void creatures, else it will become too powerful to stop.", objectives = "" }
WordHunterWoW_QuestEN[35087] = { title = "The Nether Approaches", description = "By connecting with the Twisting Nether, the Warsong shaman have created a ripple effect that they could not have anticipated.\n\nLook around and you will see countless portals beginning to open, signs that the Twisting Nether seeks to connect to Draenor.\n\nShould these portals successfully open, the path will be clear for all manner of demons and void creatures to rampage across this valley.", objectives = "" }
WordHunterWoW_QuestEN[35088] = { title = "The Shadow of the Void", description = "The moment has come to take on the void lord. Invalidus grows more powerful by the minute, so you must move with haste if you are to defeat the monster.\n\nAt each of the Warsong ritual locations there is a void crystal; these crystals are used to channel the energy of the void from within the Twisting Nether.\n\nDisturb the crystal, and Invalidus will sense your presence below.\n\nBe ready, as soon as the crystal is disturbed, Invalidus will waste no time hunting you down.", objectives = "" }
WordHunterWoW_QuestEN[35089] = { title = "Skimming Off the Top", description = "That flying machine is our ticket out of here but its fuel tank is bone dry!\n\nWe're right next to the oil fields but with the infected out there we don't have time to run a line up here so we need to improvise.\n\nThe oil creatures moving next to the pumps out there are full of a highly potent mixture that I can drop right into the tank. Grab some of that oil for me and we'll be one step closer to getting out of here.", objectives = "" }
WordHunterWoW_QuestEN[35090] = { title = "The Right Parts for the Job", description = "Uncle Krixel's a tough one but he won't be going anywhere on foot with his leg broken.\n\nHe has a flying machine he brought from Azeroth that can fly us out of here. Problem is, the engine's busted.\n\nI'll need some parts to fix the thing. My car's wasted but those broken shredders just outside of town should have what we need. We don't have time to break them down by hand so just use this rocket launcher and blow 'em apart. Anything that survives the blast should be strong enough to use on the engine.", objectives = "" }
WordHunterWoW_QuestEN[35091] = { title = "Sporicide", description = "It's revolting, absolutely disgusting, infuriating even!\n\nI'm talking about seeing those spore creatures walking around Pinchwhistle Point.\n\nWhile I'm working on the machine here how about you go out and kill off some of those spore creatures? I'll feel a bit better knowing there are less of those things moving around.", objectives = "" }
WordHunterWoW_QuestEN[35093] = { title = "The Dark Side of the Moon", description = "Yrel and I have located Warlord Ner'zhul. He is meeting with Grommash Hellscream atop the highest altar overlooking Anguish Fortress.\n\nMeet us there. We must stop him.", objectives = "" }
WordHunterWoW_QuestEN[35095] = { title = "Along the Riverside", description = "Durotan has taken most of our forces west. He's establishing a forward base along the Skysong River.\n\nHe'll want to know that we're almost ready to move against Grommashar.\n\nI'm sure he'll also appreciate your help dealing with the Warsong orcs at Lok-rath.", objectives = "" }
WordHunterWoW_QuestEN[35096] = { title = "Terms of Surrender", description = "I have good news, commander: we've already taken Lok-rath.\n\n<The warchief grins.>\n\nThe Horde's soldiers have captured most of the Warsong, including their leader, Uruk Foecleaver.\n\nI saved the honor of accepting his surrender for you. They're waiting for you inside, commander.", objectives = "" }
WordHunterWoW_QuestEN[35097] = { title = "The Pride of Lok-rath", description = "You think the Warsong are so easily defeated?\n\n<There's a rasping sound, like rope on metal.>\n\nI'm already tired of you Horde, and you've just invaded my homeland.\n\n<The sound becomes more pronounced as Uruk Foecleaver looks you straight in the eye.>\n\nThere will be no surrender. The Warsong bow to no one!", objectives = "" }
WordHunterWoW_QuestEN[35098] = { title = "Lok-rath is Secured", description = "With their leader dead, the remaining Warsong will be easy pickings.\n\nAs soon as that's done, I'll pull our soldiers out of Lok-rath and head for Grommashar.\n\nIf you're heading back to Wor'var, inform Thrall that we'll be ready soon.", objectives = "" }
WordHunterWoW_QuestEN[35099] = { title = "Silence the War Machines", description = "The Iron Horde supplied Lok-rath with war machines from Ironfist Harbor. It won't take long for them to level Riverside Post.\n\nSomeone has to silence those war machines!", objectives = "" }
WordHunterWoW_QuestEN[35100] = { title = "If They Won't Surrender...", description = "This is the backbone of the army we intend to send against Garrosh Hellscream and Grommashar.\n\nIf they won't surrender, we have no choice but to eliminate the Warsong.", objectives = "" }
WordHunterWoW_QuestEN[35101] = { title = "Terror of Nagrand", description = "<The body of a fallen soldier lies here. Blood and gore trail back from the corpse to the entrance of the cave just to the north.>\n\n<Judging by the howls and the carnage surrounding the den, something truly terrifying must be in there.>", objectives = "" }
WordHunterWoW_QuestEN[35102] = { title = "Unleashed Steel", description = "Thank you... boss.\n\nI won't let you down! I didn't even try to sneak one of those low quality blades here that one of your peons placed right next to the cage. Which by the way was a pretty terrible idea and that thing should be moved before you get anyone less honorable in here.\n\nEnough talk, lets check this place out!", objectives = "" }
WordHunterWoW_QuestEN[35103] = { title = "The Alchemist", description = "I know a little about alchemy from my cousin Kadar. She is the alchemist at Stonefang Outpost. If you wish to learn more, she is the one with whom to speak.\n\nI only hope she has survived the attack.", objectives = "" }
WordHunterWoW_QuestEN[35104] = { title = "The Apprentice", description = "Kadar's last words... Is there someone still inside the hut?", objectives = "" }
WordHunterWoW_QuestEN[35106] = { title = "Avenge and Reclaim", description = "I will avenge my master and retrieve her life's work. Honor demands it. My heart yearns for it. If I die trying, so be it. The murderer will pay.", objectives = "" }
WordHunterWoW_QuestEN[35128] = { title = "Fair Warning", description = "The ogron here are far from brilliant, but they are more intelligent than the gronn. They're large, and even stronger than they look.\n\nTheir leader, Borogahn, is especially formidable. Despite several fights, I have not yet managed to kill him.\n\nHeed my words, friend. Take caution as you explore their lair.\n\nNisha is ready to move. Ask her to take you to the mouth of the cave, and I'm sure she would be happy to.", objectives = "" }
WordHunterWoW_QuestEN[35129] = { title = "Leave Every Soldier Behind", description = "Hmmm.\n\nThe ogron possess something of value to the Iron Horde. I'm sure they're unaware, likely just bored and in  need of something to torture.\n\nI'd be inclined to just let them be, it's a fate they deserve. But we can't afford not to follow up on this clue. With any luck, it will help us stop the Iron Horde from turning Gorgrond's most fearsome creatures into weapons.\n\nTry to find this Corporal Thukmar and his notes. We'll meet you there.", objectives = "" }
WordHunterWoW_QuestEN[35136] = { title = "Chains of Iron", description = "The artifact we seek is within our grasp.\n\nBe prepared for a fight. If they truly have learned how to control gronn, this may be more difficult than I anticipated.\n\nI will join you in this battle as soon as you arrive.", objectives = "" }
WordHunterWoW_QuestEN[35137] = { title = "The Sparring Arena", description = "We owe you our freedom, and more. I have spoken to the others, we are willing to return with you to your garrison and teach those pitiful creatures you call \"soldiers\" how to properly fight.\n\nWe will also do our best to impart our knowledge to you, Commander. Should you have need of us when in the wilds of Gorgrond, simply call us.\n\nYou may wish to warn Rangari Jonaa of our coming.", objectives = "" }
WordHunterWoW_QuestEN[35139] = { title = "Eye in the Sky", description = "The notes you recovered tell of a device capable of subjugating even a magnaron.\n\nAncient legends speak of such artifacts, crafted by the worldbuilders to keep these creatures in check. I had discounted them as silly stories, but if they are true...\n\n{name}, Draenor is doomed.\n\nNo army will be able to stop them if they harness this power. We must stop them or die trying.\n\nHere, I shall bind our sight to Nisha and hope she can locate this artifact.", objectives = "" }
WordHunterWoW_QuestEN[35140] = { title = "THAELIN!", description = "That little...!\n\n<Yrel tries to maintain her composure.>\n\nThaelin Darkanvil sent us a shipment. It was supposed to be engineering parts.\n\nInstead, when we just opened one of the crates, out popped a baby goren. Do you know how destructive those things are?\n\nAnd, of course, the one baby immediately set about letting all the other ones loose.\n\nWant to help me get some revenge?", objectives = "" }
WordHunterWoW_QuestEN[35141] = { title = "Carrier Has Arrived", description = "We're going to get some payback on that little stinker.\n\nPut the baby goren into one of those carriers and then make a special delivery to Thaelin.", objectives = "" }
WordHunterWoW_QuestEN[35143] = { title = "Blood of the Burning Blade", description = "Hallvalor is the ancestral home of my clan, the Burning Blade. When the new warlord and his family came to power, I was exiled for being a half-breed.\n\nI want justice.\n\nI suspect you won't mind killing along the way. Not that you'll have any choice.", objectives = "" }
WordHunterWoW_QuestEN[35144] = { title = "Dark Binding", description = "Even as we speak, the pale within Shadowfall Canyon are enslaving the elements to their will. Many elemental spirits have already been enthralled, and more will follow.\n\nThe pale must be stopped and the elementals they enslave set free.\n\nJourney into Shadowfall Canyon and set free those elemental spirits which are not fully enthralled by the pale. As for the elementals already enslaved by the pale, the only mercy we can give them now is to release their bonds through death.", objectives = "" }
WordHunterWoW_QuestEN[35145] = { title = "The Pale Threat", description = "The Pale are wretched creatures that hide beneath the ground, ever plotting against those who dwell upon the surface. They stalk the Underpale, a twisted and dark cavern beneath Oshu'gun.\n\nIf we are to succeed in stopping Cho'gall we must fight our way through their ranks beneath the earth.\n\nMake your way into the cavern, slay the vile creatures within and take out the Pale leader... the one known as Greyseer.", objectives = "" }
WordHunterWoW_QuestEN[35146] = { title = "The Good Doctor", description = "Our expedition biologist has been kidnapped by podlings!\n\nWe came to Nagrand to explore, to slay the mightiest of beasts, and test our mettle alongside the great Hemet Nesingwary.\n\nAs soon as we arrived, Hemet's hunting prowess was needed to combat the Warsong. Rather than sit around twiddling our thumbs, we decided to continue the expedition!\n\nWe were exploring Spiteleaf Thicket when podlings ambushed us! In the chaos, Dr. Hadley Ricard was taken captive.\n\nPlease, we can't just leave him there!", objectives = "" }
WordHunterWoW_QuestEN[35148] = { title = "Trouble at the Overwatch", description = "Ya know, we sent a couple o' scouts ta check out those big, smelly, 'civilized' ogres at Mar'gok's Overwatch.\n\nHaven't heard from 'em in a bit. Matter o' fact, not since I saved yer bacon up at Telaar.\n\nHave some time ta ride over there and check up on 'em, boyo?", objectives = "" }
WordHunterWoW_QuestEN[35150] = { title = "Trouble at the Overwatch", description = "Yesterday, I sent two of my best scouts to spy on the ogres at Mar'gok's Overwatch.\n\nI haven't heard back from them.\n\n{name}, would you do me the honor of checking on them? I'm sure it's nothing; the Overwatch is a large fortification.\n\nI'd feel better knowing they're okay.", objectives = "" }
WordHunterWoW_QuestEN[35151] = { title = "Your Base, Your Choice", description = "You have already constructed an impressive garrison in Frostfire. I believe I should defer this next choice to you.\n\nOne region of Gorgrond is rich in resources. A lumber mill could help us make the most of them.\n\nAnother region harbors hardened gladiators. A sparring arena would help persuade them to fight for our cause.\n\nEither path will strengthen us as we seek to find and weaken the Iron Horde.\n\nWhich do you choose, Commander?", objectives = "" }
WordHunterWoW_QuestEN[35152] = { title = "The Sparring Arena", description = "We owe you our freedom, and more. I have spoken to the others, we are willing to return with you to your garrison and teach those pitiful creatures you call \"soldiers\" how to properly fight.\n\nWe will also do our best to impart our knowledge to you, Commander. Should you have need of us when in the wilds of Gorgrond, simply call us.\n\nYou may wish to warn Limbflayer of our coming.", objectives = "" }
WordHunterWoW_QuestEN[35154] = { title = "Things Are Not Goren Our Way", description = "The abandoned mine shaft has been overrun with goren!  They seem to be responding to commands from a big one further down in the mine.  If you can take him out, the rest will probably retreat.\n\nOnce you have those goren cleared out, we can get that mine up and working!", objectives = "" }
WordHunterWoW_QuestEN[35155] = { title = "Obliterating Ogres", description = "We got more of those magic tossing ogres here which is never a good thing.\n\nThese new ogres are especially bossy and have increased work being done here.\n\nDo you know what stops ogres from working hard? Dying.\n\nKill some ogres here and get this camp back to its normal boring self.", objectives = "" }
WordHunterWoW_QuestEN[35156] = { title = "Removing the Paper Trail", description = "This box is filled with writings and diagrams that oddly resemble research into the nullification of magic.  It would be best to ruin these efforts by destroying any research found.", objectives = "" }
WordHunterWoW_QuestEN[35157] = { title = "Obtaining Ogre Offensive Orders", description = "The upper bluff must be really important to the ogres. Two fancy looking ogre mages came down from there and starting ordering all the others around.\n\nGo get those orders and meet up with my scout Dalgorsh on the upper bluff. They will be more useful to him up there.", objectives = "" }
WordHunterWoW_QuestEN[35158] = { title = "Reglakk's Research", description = "Okay so these orders say Reglakk is in charge of something called Breaker research, which makes super powerful ogres. I don't know about you but that sounds bad.\n\nI'm pretty hurt, do you think you can go up there alone and make Reglakk rethink his research?", objectives = "" }
WordHunterWoW_QuestEN[35159] = { title = "Removing the Reinforcements", description = "Its not good {name}, these smart ogres have got a portal working up there and they are bringing in more ogres from somewhere else.\n\nIt looks like it takes a lot of effort to keep it open though. If you take it down I'm guessing they will be delayed quite a while.", objectives = "" }
WordHunterWoW_QuestEN[35166] = { title = "Ship Salvage", description = "Commander, we are running low on supplies.\n\nMaybe we can salvage materials from that ship you arrived on?\n\nAt the rate folks are coming through the portal we are going to be out of everything by sundown... or moondown?\n\nI'm still getting used to this place.", objectives = "" }
WordHunterWoW_QuestEN[35167] = { title = "Lost in Nagrand", description = "Hey, mister, could you help me?\n\nThere's this girl I know. Her name's Olgra. Her and her parents went back to Wor'var yesterday. Only, they never got there and no one's seen them.\n\nIf you're heading back out, would you look for her?\n\nShe's kinda my girlfriend.", objectives = "" }
WordHunterWoW_QuestEN[35168] = { title = "Your First Blacksmithing Work Order", description = "Now that the forge is complete, we can start producing truesteel ingots for you. When you have the ingredients, please speak with my assistant to start the first work order.", objectives = "" }
WordHunterWoW_QuestEN[35169] = { title = "And Justice for Thrall", description = "The time has come, commander. You've dealt with all of the Warsong's allies and holdings.\n\nOur troops are massing at the gates of Grommashar. The rangari have reliable intel that Garrosh is holed up inside the Warsong fortress.\n\nAll of our efforts have led to this moment. Let's take out Garrosh.", objectives = "" }
WordHunterWoW_QuestEN[35170] = { title = "Consumed by Vengeance", description = "They... they came out of nowhere. From that direction.\n\n<The young girl points vaguely west through her tears.>\n\nThey were on their nasty wolves.\n\nPlease, commander, my family's honor is at stake. Will you get vengeance for me?", objectives = "" }
WordHunterWoW_QuestEN[35171] = { title = "And Justice for Thrall", description = "The time has come, commander. You've dealt with all of the Warsong's allies and holdings.\n\nOur troops are massing at the gates of Grommashar. The shadow hunters have reliable intel that Garrosh is holed up inside the Warsong fortress.\n\nAll of our efforts have led to this moment. Let's put an end to this once and for all.", objectives = "" }
WordHunterWoW_QuestEN[35172] = { title = "Your Second Blacksmithing Work Order", description = "Place another work order with my assistant. Once it is complete, we will leave it out here for you to collect.", objectives = "" }
WordHunterWoW_QuestEN[35174] = { title = "Pale Moonlight", description = "We are getting strange reports of an orc attack on a nearby draenei settlement called Eventide Landing.\n\nI'm hearing these particular orcs are unlike any we have encountered before.\n\nThey seem... sickly, and are pale in color.\n\nThe locals could use our help, commander. This seems like the perfect opportunity to test our garrison's capabilities.", objectives = "" }
WordHunterWoW_QuestEN[35176] = { title = "Keeping it Together", description = "So much work to do... I don't even know where to start.\n\nMaking sure this garrison is operational is not an easy task.\n\nShelly still hasn't reported back to me, my assistant Brightstone and her crew are who knows where, ugh... I'm so caught up I haven't even had time to check our cache for resources.\n\nIf I were a mage, do you think I could use mirror images to do all of this at once?", objectives = "" }
WordHunterWoW_QuestEN[35185] = { title = "Garrison Campaign: The Sargerei", description = "Greetings, {name}.\n\nArchmage Khadgar wishes you to hear an important message.\n\nThe draenei suffered a great betrayal when one of their leaders, Exarch Othaar, revealed himself to be working with the Legion.\n\nIn the hills above Shadowmoon Valley, Othaar, who now goes by the name Socrethar, gathers new recruits to his cause.\n\nArchmage Modera is in charge of this covert operation, which we need your help carrying out.\n\nMeet her in the field, and she will give you the details.", objectives = "" }
WordHunterWoW_QuestEN[35186] = { title = "Garrison Campaign: The Sargerei", description = "Greetings, {name}.\n\nArchmage Khadgar wishes you to hear an important message.\n\nThe draenei suffered a great betrayal when one of their leaders, Exarch Othaar, revealed himself to be working with the Legion.\n\nIn the hills above Shadowmoon Valley, Othaar, who now goes by the name Socrethar, gathers new recruits to his cause.\n\nArchmage Modera is in charge of this covert operation, which we need your help carrying out.\n\nMeet her in the field, and she will give you the details.", objectives = "" }
WordHunterWoW_QuestEN[35187] = { title = "Infiltrating the Sargerei", description = "One of my men has already infiltrated the Sargerei's ranks, but I need you to help him.\n\nIn order to protect his cover, you will need to disguise yourself as one of the enemy.\n\nKill Sargerei until you collect a cowl, robe, and slippers to create a disguise.\n\nAfter donning the disguise, introduce yourself to Soulbinder Zamaya as a new student, then tell Anchorite Laanda that 'the rain falls on Shadowmoon.'\n\nThe secret phrase will identify yourself as an ally.", objectives = "" }
WordHunterWoW_QuestEN[35188] = { title = "Pesky Podlings", description = "Ah, initiate. Are you ready for your first task?\n\nThe woods to the south are filled with pesky podlings. The filthy things dig up our farms, steal supplies, and prey on unwitting trainees.\n\nThey are disgusting, horrible creatures which need to be eliminated.\n\n<Zamaya gives you a skeptical look.>\n\nI will require their spears as proof that you finished this task.", objectives = "" }
WordHunterWoW_QuestEN[35189] = { title = "The Word of Socrethar", description = "The Sargerei follow Socrethar zealously. From what I can gather, he is a persuasive and compelling leader.\n\nMany of the initiates carry books of his writings.\n\nI need you to read these works and report back to me. If we can understand the Sargerei's motivations, perhaps we can undermine them.\n\nI last saw these books near the lake, on a table near the fountain, and in the house near the gardens.", objectives = "" }
WordHunterWoW_QuestEN[35190] = { title = "An Ancient Threat", description = "To the northwest, an Ancient has settled into a forest glade.\n\nI need someone to take care of this nuisance.\n\nThis should be a simple matter, even for an initiate like you.", objectives = "" }
WordHunterWoW_QuestEN[35191] = { title = "Shattering the Enemy", description = "While you carry out the pretense of obeying Zamaya's orders, we're going to sabotage the Sargerei under their very noses.\n\nAll around this village, you can find Felstorm Crystals. The enemy uses these objects to magnify their power.\n\nDestroy these crystals, and we'll slow their operations.", objectives = "" }
WordHunterWoW_QuestEN[35194] = { title = "Facing Demons", description = "Time is running out, {name}. The Sargerei have opened a summoning portal on the hill to the west.\n\nI believe they are going to use this portal to bring an army of demons here, to Shadowmoon Valley.\n\nWe must stop them before this happens, no matter what the cost. Use this arcane bomb to destroy the portal.\n\nWe may blow our cover, but stopping the portal is more important right now.", objectives = "" }
WordHunterWoW_QuestEN[35195] = { title = "Socrethar's Fury", description = "<Upon opening the scroll, you find a message from Anchorite Laanda.>\n\nI write this message hastily. I've been discovered. I'm being taken in front of Socrethar.\n\nYou must carry on our mission. I've learned that Soulbinder Zamaya holds a detailed plan of Socrethar's next attack.\n\nShe still trusts you, so you should be able to enter the main building. Please, find those plans, {name}!", objectives = "" }
WordHunterWoW_QuestEN[35196] = { title = "Forging Ahead", description = "<Anchorite Laanda's voice is barely a whisper.>\n\nYou must report back... to Khadgar.\n\nSocrethar means to take Shattrath. He will... continue to recruit followers... to his side...\n\nThank you for... helping me... in my final hour...\n\nLeave me... I would like to rest...", objectives = "" }
WordHunterWoW_QuestEN[35197] = { title = "Forging Ahead", description = "<Anchorite Laanda's voice is barely a whisper.>\n\nYou must report back... to Khadgar.\n\nSocrethar means to take Shattrath. He will... continue to recruit followers... to his side...\n\nThank you for... helping me... in my final hour...\n\nLeave me... I would like to rest...", objectives = "" }
WordHunterWoW_QuestEN[35202] = { title = "Shells for Xuk", description = "The magics Xuk is weaving will let you perform great acts, but preparations must be made before the spirits will bless us with their power.\n\nXuk needs many shells from the pesky goren. To gather them, Xuk will share a secret.\n\nApproach their tunnel craters and the goren will pour out. This way, you kill many at once.", objectives = "" }
WordHunterWoW_QuestEN[35204] = { title = "Pollen Power", description = "The botani use monstrous insect-like creatures to pollinate their bloom.\n\nThe pollen they carry has a number of powerful properties that would be of use to your garrison forces.\n\nIf you bring me a reserve of this pollen I should be able to convert it to something of value.", objectives = "" }
WordHunterWoW_QuestEN[35205] = { title = "Burn the Bodies", description = "You don't understand. Anythin' these plant people don't infest they fatten up and then turn inta mulch.\n\nI say we take out their food source.\n\nThese botani got a few corpses lying around that I saw. Might be a good idea to burn those bodies.\n\nLet's find out if they can infest ash.", objectives = "" }
WordHunterWoW_QuestEN[35206] = { title = "Bushwhacker", description = "We are continuing the search for Thaelin's people, but these botani, they are a larger threat than we ever realized.\n\nTo infest their victims... monstrous.\n\nPlease, commander, if you find yourself in Evermorn Springs to our west, slay as many of those creatures as you can.\n\nStop them from committing such acts of horror. Bring them to justice.", objectives = "" }
WordHunterWoW_QuestEN[35207] = { title = "Coalpart's Revenge", description = "I'm so full I can't swing an axe even if I had one.\n\nTell ya what, we got a mutual interest here. I need yer help to get a little vengeance on the big botani at the back of this bloom. In return, I'll point ya in the right direction fer gettin' a secret weapon the botani keep.", objectives = "" }
WordHunterWoW_QuestEN[35208] = { title = "Dark Iron Down", description = "While you were away our rangari here found more clues leadin' to some of me other friends.\n\nBurrian Coalpart and Scorchbrow.\n\nProblem is, their trail heads right for Evermorn Springs to the west.\n\nPlease Commander, will ya get in there and save them from mulching?", objectives = "" }
WordHunterWoW_QuestEN[35209] = { title = "The Life Spring", description = "So we came here cause we needed a weapon we saw the botani using.\n\nHansel grabbed the artifact an' Scorchbrow an' I were supposed to grab the special water the thing runs on.\n\nWe didn't know that water so full of life forms an elemental.\n\nIf ya mosey up to the cauldron at the base of that fancy lookin' ancient artifact in Evermorn Springs, you'll be findin' this beast. If ya can kill it and get its water, we can use it when we get the rest of the artifact.", objectives = "" }
WordHunterWoW_QuestEN[35210] = { title = "A Great Escape", description = "A goren tunnel!\n\nOnce the cap is cleared, it's certain to lead outside of this Light-forsaken pit.", objectives = "" }
WordHunterWoW_QuestEN[35211] = { title = "Preventing the Worst", description = "Have you seen all the fungus on the buildings in Pinchwhistle Point? It's only a matter of time 'til it releases enough spores to infest the whole coastline!\n\nThe remaining infected that are in Pinchwhistle Point will be too far gone for us to save later on, so let's do the right thing and put them out of their misery and prevent an even worse outbreak.\n\nI made some firebombs that will burn the fungus down, but I'll need you to place them while I set up the detonator.\n\nAre you up for it?", objectives = "" }
WordHunterWoW_QuestEN[35212] = { title = "Deeproot", description = "Since yer all set up to take on trees and bushes now, I need ta ask for a favor.\n\nI came to Gorgrond in search of an expedition of me fellow Dark Irons that were headed this way. Sadly I lost 'em.\n\nI am goin' south to look for them. Thing is, south is nothing but botani, podlings, giant trees, and other mean, angry plants.\n\nYer lumber camp resources would be mighty appreciated. If ya help me look for me friends I swear we'll help ya in any way we can.", objectives = "" }
WordHunterWoW_QuestEN[35213] = { title = "The Razorbloom", description = "Kaalya thinks she picked up a trail. Seems a bunch of dwarves went north to Razorbloom by the signs.\n\nProblem is that place is filled with plant people. I ain't much use against plant people.\n\nAre you willing to investigate?", objectives = "" }
WordHunterWoW_QuestEN[35214] = { title = "The Infested", description = "D'kaan did not say it, but there were more rangari taken by the botani than the ones you found.\n\nHe believes they were slain. I fear worse.\n\nYou might dare to venture into the Razorbloom. If you do, you may discover what the botani do to their... \"prisoners.\"\n\nGive these poor souls a proper release.", objectives = "" }
WordHunterWoW_QuestEN[35215] = { title = "The Voice of Iyu", description = "Journal Entry 25 -\n\nThe botani got themselves a leader who calls himself... er... herself... er... itself the Voice of Iyu.\n\nSeems the botani see the genesaur as gods and only the most bossy of the botani get to speak on behalf of the genesaur.\n\nWhen we tried askin' it about the artifact we found back at the base it got all angry and sent off Lera and Nori and I ain't seen either of them since.\n\nI got a bad feelin' about this thing.", objectives = "" }
WordHunterWoW_QuestEN[35216] = { title = "Super Seeds", description = "These seeds have been shielded with care by the botani.\n\nGreat power can be felt surging out of these tiny vessels of life.\n\nThese may prove useful.", objectives = "" }
WordHunterWoW_QuestEN[35218] = { title = "Iron Horde Orders", description = "Spirit spotted some orders at the Iron Horde camp on the nearby bluff. You must have missed them when you were there. Could you look into it?", objectives = "" }
WordHunterWoW_QuestEN[35225] = { title = "A Heavy Helping Hand", description = "Burrian gave us the coordinates of the Dark Iron base. They named it Moira's Reach.\n\nBut half way through buildin' it the base got infested with goren.\n\nIf you head south you should come to the structure. Just look for a big ol' cannon.\n\nWe will follow as soon as we get this bloody tank untangled.", objectives = "" }
WordHunterWoW_QuestEN[35226] = { title = "Old Friends, New Enemies", description = "I cannot believe Orgrim would continue to do Blackhand's bidding after all the destruction he has wrought.\n\nWe must confront him. Join me at the village along Orunai Coast and we will confront my oldest friend.", objectives = "" }
WordHunterWoW_QuestEN[35227] = { title = "Ogre Diplomacy", description = "Ogres are ogres. Spirits or not, the Ango'rosh are not different.\n\nEven with their ritual books, they won't relinquish their power to you until you prove yourself.\n\nI've fought ogres my entire life, and there's only one way to earn that.\n\nKilling them outright.\n\nThe more Ango'rosh spirits and their pets as you take out while you're there, the more respect you'll command among them.", objectives = "" }
WordHunterWoW_QuestEN[35229] = { title = "Down the Goren Hole", description = "These beasts came at us so fast we didn't have time to mount a proper defense. They went right for the metal and chewed through any wall we had.\n\nIf we don't kill some of them soon they'll bring the whole fortress down on us.", objectives = "" }
WordHunterWoW_QuestEN[35231] = { title = "Spiritual Matters", description = "The spirits of the dead have long been drawn to Oshu'gun.\n\nAs long as I can remember, the woods have been filled with ancestral spirits making a ghostly pilgrimage to the heart of the mountain.\n\nHowever, I fear that what is transpiring here is not the normal spirit walk I have seen before.\n\nMake your way to the Ancestral Grounds and commune with the spirits there for guidance on this matter.", objectives = "" }
WordHunterWoW_QuestEN[35232] = { title = "The Call of Oshu'gun", description = "The elements have spoken and a vision has been revealed, {name}.\n\nTogether we shall travel to the great mountain Oshu'gun and put an end to the dark disturbance there.\n\nIf what you saw in the vision is to be believed, then great danger awaits us.\n\nI will meet you in the Spirit Woods at the foot of Oshu'gun. When you are ready to depart, speak with Gixmo Moneycash and he will fly you there.", objectives = "" }
WordHunterWoW_QuestEN[35233] = { title = "Just In Case", description = "When we set up shop the first thing we built was the cannon. Seemed like a good place fer it.\n\nWe started buildin' the base up around it when them chompin' acid spittin' varmints came crawlin' out of the ground.\n\nThe upside though is the cannon is built, just not loaded.\n\nWe have to go down to the bottom floor of this thing anyway so may as well grab some Doomshot if you see any on your way down.\n\nBetter to load the cannon and not need it than to need it and not have it loaded.", objectives = "" }
WordHunterWoW_QuestEN[35234] = { title = "Will of the Genesaur", description = "When the goren attacked we threw everything we had at them but they just kept comin'.\n\nSo some of the lads went and stole a fancy artifact from the botani.\n\nProblem was we couldn't get it to work. Now the artifact is sitting at the bottom of the bastion. To get to it you got to go all the way to the back of the tunnels past all them goren and find the wee tunnel that takes you farther underground.\n\nIf you retrieve it, it is yours.", objectives = "" }
WordHunterWoW_QuestEN[35235] = { title = "Iyu", description = "Did ya hear that?\n\nSounds like that genesaur wants its 'will' back. I told ya this place is nuthin' but bad luck.\n\nI'll git that shot ya gave me loaded properly and see if I can't weaken that thing up. You better get up there and deal with it though...", objectives = "" }
WordHunterWoW_QuestEN[35238] = { title = "New Owner", description = "", objectives = "" }
WordHunterWoW_QuestEN[35239] = { title = "New Owner", description = "", objectives = "" }
WordHunterWoW_QuestEN[35240] = { title = "Bled Dry", description = "<The draenei spits out his last words.>\n\nThey kept us in cages. They... drain our blood, for... rituals...\n\n<He coughs violently.>\n\n...many left --\n\n    -- my... people...\n\n<The draenei dies.>", objectives = "" }
WordHunterWoW_QuestEN[35241] = { title = "Vengeance for the Fallen", description = "Too many of my people have fallen at the hands of the Bleeding Hollow. Their cruelty cannot be forgiven.\n\n<The grieving orc looks up at you.>\n\nMake them pay.", objectives = "" }
WordHunterWoW_QuestEN[35242] = { title = "Vengeance for the Fallen", description = "Too many of my people have fallen at the hands of the Bleeding Hollow. Their cruelty cannot be forgiven.\n\n<The grieving draenei looks up at you.>\n\nMake them pay.", objectives = "" }
WordHunterWoW_QuestEN[35243] = { title = "The Dark Lady's Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[35245] = { title = "A Sentimental Relic", description = "My father's bangle sat here for ages before that imposter Ikiss stole it away.\n\nI thank you for returning it, but I have no need for keepsakes. Take it, with my blessing.\n\nIf there are still Talonpriests loyal to the true Talon King, please bring it to them.", objectives = "" }
WordHunterWoW_QuestEN[35247] = { title = "Zero Xuks Given", description = "The spirits have spoken to me. They believe the magnaron, Gro the Uncreator, will join our fight and lead his underlings against the Iron Horde.\n\nThis is an honor beyond any bestowed upon a Laughing Skull, at least in my time.\n\nI will commune with the magnaron, and together we shall destroy the Iron Horde.", objectives = "" }
WordHunterWoW_QuestEN[35248] = { title = "A Harsh Reminder", description = "Welcome to the front lines, outsider, where the wastelands and the jungle collide.\n\nWhen their forces forget about the ferocity of the Laughing Skull, this is where we come to make them remember.\n\nBy fierce and merciless destruction we survive. This is the way of Gorgrond.\n\nJoin in! Let us see if you can withstand the brutality of our land.", objectives = "" }
WordHunterWoW_QuestEN[35249] = { title = "Powering the Defenses", description = "It's good to see a Horde champion joining the fight.\n\nAuchindoun's defenses are faltering quickly. The few Auchenai soulpriests not on the front are working fervently to maintain them.\n\nSoulbinder Tuulani went inside the nearby Tomb of Lights to retrieve a backup power pylon and hasn't returned. If you can find her and get her and the pylon back here safely it would help greatly.", objectives = "" }
WordHunterWoW_QuestEN[35254] = { title = "Retribution for the Light", description = "There are agents of darkness everywhere, fighting tooth and nail to envelop the world. The Light relies on us to balance the scale.\n\nYou have the power needed to destroy Teron'gor's demonic minions once and for all. Send them to the Twisting Nether in pieces!", objectives = "" }
WordHunterWoW_QuestEN[35255] = { title = "Power of the Genesaur", description = "Commander, you now have the Will of the Genesaur along with the genesis water and enough seeds to grow an army. Not to mention the lives of the dwarves you saved.\n\nI would call this mission a success.\n\nI can help the dwarves mop up their operation here and see what we can salvage. In the meantime, you may want to bring the artifact to Maraad back at the outpost.", objectives = "" }
WordHunterWoW_QuestEN[35257] = { title = "Power Unearthed", description = "What power could reduce a village to ashes in the blink of an eye? The Adherents claim it is the will of Rukhmar.\n\nA lie, obviously.\n\nThey did nothing to earn such power - in truth, they stumbled upon it rather unwittingly, in a hole in the ground.\n\nCome and visit me near the excavation site just west of here. We must understand their technology if we are to defeat it.", objectives = "" }
WordHunterWoW_QuestEN[35258] = { title = "Legacy of the Apexis", description = "The Apexis are long gone, but their legacy lies preserved in ancient chambers beneath Arak.\n\nLegions of dormant constructs; crystals flush with solar energy; magical techniques lost to the ages - the Apexis left behind caches of immense power, which the Adherents of Rukhmar have begun to unearth.\n\nBring me the cores of the re-activated constructs patrolling the excavation site. Those crystals are the basis of Apexis technology, and the key to our enemy's devastating power.", objectives = "" }
WordHunterWoW_QuestEN[35259] = { title = "Sol Sisters", description = "When I was still a guard in Skyreach, I was tasked with protecting the sisters Veoryx and Krashyx.\n\nThey were prodigies. At an age when most sun acolytes could barely read, the sisters conjured familiars of pure sunlight to illuminate their textbooks in the small hours.\n\nNow they unravel the secrets of Apexis technology, and their excavation has just breached two ancient chambers.\n\nEnter those chambers and cut down the sisters before they reap the terrible rewards of their discovery.", objectives = "" }
WordHunterWoW_QuestEN[35260] = { title = "Hardly Working", description = "Those who were not incinerated at Veil Akraz are forced to help the Adherents excavate the very weapons aimed at their heads.\n\nAnyone trying to escape is vaporized by the overseer's Apexis turret.\n\nWith these effigies, they won't know anyone has left! Place one near an enslaved worker and observe as it creates a perfect copy. It even cloaks the subject in shadow, so they can slip away safely!", objectives = "" }
WordHunterWoW_QuestEN[35261] = { title = "Shot-Caller", description = "<Solar energy courses through the slumbering constructs, their ancient servos whirring to life all around you. It is too late to shut them down now.\n\nOutside, an arakkoa overseer bellows commands, each answered by the buzz of an Apexis beam carving away at the mountain.\n\nThat turret would make short work of the constructs - if you can command it.>", objectives = "" }
WordHunterWoW_QuestEN[35262] = { title = "Service of Rangari Kaalya", description = "", objectives = "" }
WordHunterWoW_QuestEN[35265] = { title = "The Ritual of Binding", description = "The time has come for you to undertake the Ritual of Binding, {name}.\n\nThis ancient, shamanic rite has been practiced since long before I was born. To be chosen is a great honor.\n\nMany shaman see vivid elemental visions during the rite; experiencing this world through the very elemental bonds that hold it together.\n\nWhen you are ready, speak with Kalandrios to begin the rite.", objectives = "" }
WordHunterWoW_QuestEN[35271] = { title = "The Warsong Threat", description = "<The attack plans are scrawled onto the parchment in thick, black ink and bound in rough leather.>\n\nTo all outrider stations:\n\nThe warlord has commanded that all outriders prepare for a full assault upon the Horde invaders in our land. Plans for the attack have been delivered to several of the remote outrider posts.\n\nBlood and glory shall be ours as we trample the Horde invaders beneath our feet!\n\nThe warlord commands and the Warsong obey! Lok'tar ogar!", objectives = "" }
WordHunterWoW_QuestEN[35272] = { title = "One of Our Own", description = "Da bird-men captured me while I was gettin' da lay a da land.\n\nWe been workin' on an outpost for you just round dis mountain so your will be spreadin' all over da continent.\n\nThings not be goin' well.\n\nI be needin' your assistance, commander. Can you tell dem that I mean no harm so I can be showin' you da outpost?", objectives = "" }
WordHunterWoW_QuestEN[35273] = { title = "Hot Seat", description = "<Apexis constructs are about to emerge from their ancient chambers on a warpath. The arakkoa are sure to send more sol-shapers to support them.\n\nThe interface and the turret hum in soft resonance.>", objectives = "" }
WordHunterWoW_QuestEN[35274] = { title = "One of Our Own", description = "These wretched creatures captured me while I was scouting the area. Now that you're here, commander, we could really use your help back at base.\n\nOh, and any way you could convince your... friends... to let me go?\n\nThey, uh... won't let me leave.", objectives = "" }
WordHunterWoW_QuestEN[35275] = { title = "Inspecting the Troops", description = "Axefall be just a moment's ride from here.\n\nI be markin' da location on your map and meet you dere.", objectives = "" }
WordHunterWoW_QuestEN[35276] = { title = "Inspecting the Troops", description = "Southport lies not far from here to the southwest.\n\nNo time for chit-chat. I will meet you there, commander.", objectives = "" }
WordHunterWoW_QuestEN[35277] = { title = "Orders, Commander?", description = "Commander, our status report is... regrettable.\n\nWe'll be out of supplies in a few days' time, and that's assuming we have any troops left by then. \n\nThere's just enough material left to put up an inn or a trading post.\n\nThe inn would allow us to station fresh troops here, but the trading post would open up potential supply routes with the outcasts nearby.\n\nI've left out Gazlowe's blueprints on the drafting table. We await your will.", objectives = "" }
WordHunterWoW_QuestEN[35285] = { title = "Follow that Hotrod!", description = "Miss Kimzee is one tough nugget but Pinchwhistle Point is too dangerous for her to handle alone. It'll be a catastrophe for morale if our boss gets infected.\n\nI need to get these crewmen back to the Gearworks so I need you to go and make sure she is alright.\n\nHer uncle's place is the tower just on the other side of the oil fields; I think you should look for her around there.", objectives = "" }
WordHunterWoW_QuestEN[35286] = { title = "Orders, Commander?", description = "Commander {name}, it's an honor.\n\nWe're barely holding on, sir. We have a week's supplies at best, assuming we have any troops left to supply in that time.\n\nWe have just enough material left to put up an inn or a trading post.\n\nThe inn would allow us to station reinforcements here, while the trading post would allow supply routes with the outcasts nearby.\n\nWe need your authorization for the project, commander. It's your decision.", objectives = "" }
WordHunterWoW_QuestEN[35292] = { title = "Ang'kra, the Alchemist", description = "", objectives = "" }
WordHunterWoW_QuestEN[35293] = { title = "Old Friends", description = "Admiral Taylor was ordered to establish a garrison inland while we erected yours in Shadowmoon Valley. He settled just a short ways north of here.\n\nThe two of us could go there and borrow some supplies to tide us over before our next shipment.\n\nWhat do you say, commander? I'm sure the admiral will be thrilled to see you again.", objectives = "" }
WordHunterWoW_QuestEN[35295] = { title = "What's Theirs is Ours", description = "I found somethin' else while I was scoutin', boss.\n\nDa Alliance have a garrison just across da way, and der been no movement in or out of da place in a good while.\n\nDis be a golden opportunity to sack da place and bolster your coffers, commander.\n\nWhat do ya say? We do it together.", objectives = "" }
WordHunterWoW_QuestEN[35298] = { title = "Flame On", description = "Alright {name}, we've saved as many as we could but now we need to make sure this disaster doesn't spread any further.\n\nThe firebombs are wired up and ready to go.\n\nKimzee just finished work on the flying machine so we're ready to ride back to the Gearworks as soon as we're finished.\n\nYou've done all the hard work so I think you should get the honors of triggering it.", objectives = "" }
WordHunterWoW_QuestEN[35317] = { title = "The Dark Heart of Oshu'gun", description = "We are not far from the inner chamber, {name}. The truth behind the evil here awaits us.\n\nI can project my spirit into the chamber to guide you, but it will be up to you to defeat the evil that lays within.\n\nMay the wind of Kalandrios guide your arm, the wisdom of Aborius enlighten your faculties, and the flame of Incineratus burn your enemies.\n\nMay the memory of Gordawg be your shield.", objectives = "" }
WordHunterWoW_QuestEN[35322] = { title = "I See Dead People", description = "Everybody here be... dead.\n\nDis architect's spirit not be wantin' to fight us. Even in death he only be wantin' to work. Maybe we can break da haze over him and get to da bottom of dis.\n\nI bet one of da spectral laborers be havin' one of his schematics we can show to him to clear his mind.", objectives = "" }
WordHunterWoW_QuestEN[35329] = { title = "I See Dead People", description = "Th... they're ghosts! All of them!\n\nBryan was one of my best friends. Something is clouding his mind; we need to snap him out of it and get to the bottom of this!\n\nHe was always obsessed with his work. Maybe showing him one of his schematics would help. One of the spectral laborers might have one.", objectives = "" }
WordHunterWoW_QuestEN[35330] = { title = "The Ritual of Binding", description = "It is time for you to undergo the Ritual of Binding, {name}. I will wait here as you speak with Kalandrios to begin the rite.\n\nDuring the ritual, you will experience the vision of the elements. Return to me when the ritual is complete, and we will speak more.", objectives = "" }
WordHunterWoW_QuestEN[35331] = { title = "Called to the Throne", description = "I was far from here in Talador when the voice called out to me.\n\nI looked around but found myself alone. Again, I heard the voice as if it were a breeze in my mind.\n\n\"You are needed at the throne,\" it whispered.\n\nThe voice called itself Kalandrios, and it guided me to this place.\n\nI had never been here before, nor had I yet beheld these furies with my eyes; yet this feels strangely familiar to me as if it happened long ago in a forgotten dream.\n\nWe should greet the furies and hear them out.", objectives = "" }
WordHunterWoW_QuestEN[35332] = { title = "Nobundo Sends Word", description = "Your presence has been requested at the Throne of Elements, {name}.\n\nVindicator Nobundo has heard the call of the furies upon the wind and made the journey to commune with the elements.\n\nI know not what the intentions of the furies are, but they are revered as noble and powerful spirits by the orcs.", objectives = "" }
WordHunterWoW_QuestEN[35333] = { title = "Elemental Attunement", description = "Even now, as we speak, the voice of Kalandrios continues to whisper to my mind.\n\n\"The Hero of Azeroth must attune to the elements of the plateau.\"\n\nUpon the Elemental Plateau are four great pillars carved of living rock. Lay your hands upon the stone pillars and your soul will be attuned with the elements.\n\nI will continue to commune with the great furies and attempt to further understand their will while you journey to the plateau.", objectives = "" }
WordHunterWoW_QuestEN[35337] = { title = "That Pounding Sound", description = "Commander. The rangari and I were just discussing the merits of various 'hunting' approaches.\n\nI assured her that the SI:7 are well-equipped to deal with any situation, even ones out in the wild.\n\nShe seems to think that we don't know what we're doing when it comes to bringing down game in 'her land.'\n\nWe're not going to let her get away with saying that, right? Let's take down some clefthoof.", objectives = "" }
WordHunterWoW_QuestEN[35338] = { title = "Shooting the Breeze", description = "Kia and I are having a spirited debate over who kills more efficiently: SI:7 or rangari.\n\nCare to get in on the wager, commander?\n\nI've been focusing on talbuk because of their fierce majesty. They truly encapsulate the grandeur of Nagrand as any native of Draenor knows.", objectives = "" }
WordHunterWoW_QuestEN[35339] = { title = "A Parting Favor", description = "I don't know what happened. My crew and I must have been the first to fall.\n\nMy wife, the innkeeper, is in the same stupor you found me in. I can feel it... and there are others with her.\n\nPlease, give the townsfolk peace and show their essences to my wife. That should bring her back from that cold abyss.", objectives = "" }
WordHunterWoW_QuestEN[35341] = { title = "Defection of Gronnstalker Rokash", description = "You have done me a great service. This blade is as much yours as it is mine.\n\nI offer you this blood oath: I shall serve your cause and lend my knowledge of blades and mining to your forces.\n\nWill you accept it?", objectives = "" }
WordHunterWoW_QuestEN[35342] = { title = "The Mysterious Flask", description = "The liquid swirling around inside the flask clearly has strong alchemical properties, but its nature is beyond your training.\n\nYou have heard that one of the Eventide villagers at your garrison has some knowledge of the alchemy of Draenor. Perhaps he could tell you more?", objectives = "" }
WordHunterWoW_QuestEN[35343] = { title = "The Young Alchemist", description = "I learned a little about alchemy from my aunt. If you want to know more, though, you should speak with my cousin Abatha. She was apprenticing under my aunt before she passed away.\n\nAbatha lives near the Verdant Mire with her father and sister.", objectives = "" }
WordHunterWoW_QuestEN[35344] = { title = "The Missing Father", description = "I would be happy to help with your alchemical inquiries, but right now I am worried about my father.\n\nIt's been quite some time since he went hunting down by the river, but he still hasn't returned home. I need to watch Lumiel. Will you please find him?", objectives = "" }
WordHunterWoW_QuestEN[35345] = { title = "Shocking Assistance", description = "It's been a struggle to support the family since my wife died, and I got too ambitious when I got a contract for shockscales.\n\nAlas, there is no way I will hunt enough eels to fulfill it in time now.", objectives = "" }
WordHunterWoW_QuestEN[35346] = { title = "Abatha, the Alchemist", description = "", objectives = "" }
WordHunterWoW_QuestEN[35350] = { title = "Queen of the Clefthoof", description = "Laara told me that they have Banthar here! Or rather, that she's still alive back now. Did what I just said make any sense?\n\nThis is our chance, commander. We can defeat a younger, more powerful version of Banthar and really stick it to these rangari.\n\nWe'll show Laara how a true professional works.", objectives = "" }
WordHunterWoW_QuestEN[35353] = { title = "A Piece of the Puzzle", description = "I... I remember now. Watch Commander Branson told us to stay in the inn... he said we would be safe here.\n\nThen...\n\nThen that THING broke through and slaughtered everyone!\n\nThe last thing I remember seeing was it descending into the larder.", objectives = "" }
WordHunterWoW_QuestEN[35356] = { title = "Someone's Missing Arrow", description = "<An arrow of rangari make is sticking out of the side of this talbuk. Perhaps Rangari Laara will be interested in your find.>", objectives = "" }
WordHunterWoW_QuestEN[35357] = { title = "King of the Breezestriders", description = "Let me guess, you found it in a talbuk's flank?\n\n<Laara seems lost in thought for a moment.>\n\nThat arrow was intended for Tall Buck, king of the Breezestriders. Another talbuk - the one you killed - jumped in the way as I was taking my shot.\n\nI suggest you go after the king. When I was hunting him, he seemed fond of the pond at Lonely Falls to the south.", objectives = "" }
WordHunterWoW_QuestEN[35372] = { title = "The Call of Oshu'gun", description = "The elements have spoken and a vision has been revealed, {name}.\n\nTogether we shall travel to the great mountain Oshu'gun and put an end to the dark disturbance there.\n\nIf what you saw in the vision is to be believed, then great danger awaits us.\n\nI will meet you in the Spirit Woods at the foot of Oshu'gun. When you are ready to depart, speak with Gixmo Moneycash and he will fly you to there.", objectives = "" }
WordHunterWoW_QuestEN[35374] = { title = "That Pounding Sound", description = "Commander. The frostwolf and I were just discussing the merits of various 'hunting' approaches.\n\nI assured her that the shadow hunters are well-equipped to deal with any situation, even ones out in the wild.\n\nShe seems to think that we don't know what we're doing when it comes to bringing down game in 'her land.'\n\nWe're not going to let her get away with saying that, right? Let's take down some clefthoof.", objectives = "" }
WordHunterWoW_QuestEN[35375] = { title = "Queen of the Clefthoof", description = "Ogka told me that they have Banthar here! Or rather, that she's still alive back now. Did what I just said make any sense?\n\nThis is our chance, commander. We can defeat a younger, more powerful version of Banthar and really stick it to these frostwolves.\n\nWe'll show Ogka how a true professional works.", objectives = "" }
WordHunterWoW_QuestEN[35376] = { title = "Shooting the Breeze", description = "Taz and I are having a spirited debate over who kills more efficiently: shadow hunters or frostwolves.\n\nCare to get in on the wager, commander?\n\nI've been focusing on talbuk because of their fierce majesty. They truly encapsulate the grandeur of Nagrand as any native of Draenor knows.", objectives = "" }
WordHunterWoW_QuestEN[35377] = { title = "Someone's Missing Axe", description = "<A throwing axe of frostwolf make is sticking out of the side of this talbuk. Perhaps Stalker Ogka will be interested in your find.>", objectives = "" }
WordHunterWoW_QuestEN[35378] = { title = "King of the Breezestriders", description = "Let me guess, you found it in a talbuk's flank?\n\n<Ogka seems lost in thought for a moment.>\n\nThat axe was intended for Tall Buck, king of the Breezestriders. Another talbuk - the one you killed - jumped in the way as I was taking my shot.\n\nI suggest you go after the king. When I was hunting him, he seemed fond of the pond at Lonely Falls to the south.", objectives = "" }
WordHunterWoW_QuestEN[35380] = { title = "Second in Command", description = "Wait... I remember something else.\n\nSir Edward... he was shouting... looking for someone.\n\nI... I can't remember who. There were so many screams...", objectives = "" }
WordHunterWoW_QuestEN[35386] = { title = "The Warsong Threat", description = "<The attack plans are scrawled onto the parchment in thick, black ink and bound in rough leather.>\n\nTo all outrider stations:\n\nThe warlord has commanded that all outriders prepare for a full assault upon the Alliance invaders in our land. Plans for the attack have been delivered to several of the remote outrider posts.\n\nBlood and glory shall be ours as we trample the Alliance invaders beneath our feet!\n\nThe warlord commands and the Warsong obey! Lok'tar ogar!", objectives = "" }
WordHunterWoW_QuestEN[35393] = { title = "Spiritual Matters", description = "The spirits of the dead have long been drawn to the mountain of Oshu'gun.\n\nAs long as I can remember, the woods have been filled with ancestral spirits making a ghostly pilgrimage to the heart of the mountain. I fear that the souls drawn to Oshu'gun are being consumed by the growing void within the mountain.\n\nMake your way to the Ancestral Grounds and commune with the spirits there for guidance.", objectives = "" }
WordHunterWoW_QuestEN[35395] = { title = "The Fate of Gordawg", description = "Looming monstrously between us and the inner chamber is the great fury we have sought to return to the Throne of Elements.\n\nGordawg stands before us enthralled; a slave to Cho'gall. My heart is heavy with grief to see such a great creature mindless and enslaved by evil.\n\nThere is no going back, in order to push forward you must go through Gordawg.\n\nIt pains me, but Gordawg must be slain.\n\nSlay Gordawg and return the fury's heart to the Throne of Elements where it belongs.", objectives = "" }
WordHunterWoW_QuestEN[35396] = { title = "The Dark Heart of Oshu'gun", description = "Amongst the timeworn wreckage of the Genedar is the entrance to the vessel's inner chamber. The void energy appears to be most concentrated in that place.\n\nYou must enter the inner chamber and face whatever evil lurks within. I fear whatever fate may have befallen the great naaru K'ure in that place, but regardless the evil there must be purged.\n\nMay the Light be with you, {name}.", objectives = "" }
WordHunterWoW_QuestEN[35397] = { title = "The Pale Threat", description = "If we are to succeed in stopping Cho'gall from destroying the naaru, we will need to fight our way through the Underpale; a dark, winding cavern infested with the Pale.\n\nThe Pale are fallen orcs that despise all that is good and holy. The longer they are left to their devices beneath the ground, the further their dark plots progress.\n\nMake your way into the Underpale, slay the vile creatures within and take out their leader, Greyseer.", objectives = "" }
WordHunterWoW_QuestEN[35398] = { title = "Dark Binding", description = "Even as we speak, the pale are enslaving an army of elementals in Shadowfall Canyon. Many have already been enslaved and if we do not lend our aid, more will follow.\n\nGo to Shadowfall Canyon and set free the elemental spirits which are not yet fully enthralled by the pale. As for those already enslaved, the only mercy we can give them now is a swift death.", objectives = "" }
WordHunterWoW_QuestEN[35399] = { title = "Mossy Fate", description = "Your wolf queen will not let me out of her sight.\n\nThe children of the magnaron may have destroyed my village but it was the children of the genesaur who took my people.\n\nThe botani and their minions drag our people to the Razorbloom, and if we see them again, it is not as they were in life.\n\nYou have already helped the Skulls, so I ask your help again.\n\nEnter the Razorbloom and search for my people that were recently taken.\n\nPerhaps they may even be alive.", objectives = "" }
WordHunterWoW_QuestEN[35400] = { title = "The Infested", description = "I understand Kaz's desire to rescue her people, but her plan is reckless and she is not telling us everything.\n\nI came along to make sure she wasn't devising a plan against us and now I see this... this... horror.\n\nWhat did the botani do to these orcs?\n\nThese infested souls need to be put to rest. Give them peace.", objectives = "" }
WordHunterWoW_QuestEN[35402] = { title = "The Voice of Iyu", description = "The botani and their wretched minions take and take and take.\n\nThey want food, they take our land. They want an army, they take our people.\n\nIt is important to strike fear into the shrubby hearts of these plant people.\n\nLook for their leader, the Voice of Iyu. It is a botani who speaks on behalf of their genesaur master.\n\nKill their precious leader in the safety of his precious bloom.", objectives = "" }
WordHunterWoW_QuestEN[35406] = { title = "Super Seeds", description = "These seeds have been shielded with care by the botani.\n\nGreat power can be felt surging out of these tiny vessels of life.\n\nThese may prove useful.", objectives = "" }
WordHunterWoW_QuestEN[35407] = { title = "Punishable by Death", description = "Traitors, the lot!\n\nYou're looking at the last bastion of forces still loyal to Admiral Taylor and the Alliance.\n\nI'll be damned if the defectors get away clean.\n\nYou look like you're ready. Show them how we deal with their kind during times of war.", objectives = "" }
WordHunterWoW_QuestEN[35408] = { title = "Prime the Cannons", description = "The armory is lost to the traitors. All we have left are these few cannons with no ammunition.\n\nSoldier, I need you to recover cannonballs so we can get these things running.\n\nActually, one more cannon wouldn't hurt, either.", objectives = "" }
WordHunterWoW_QuestEN[35416] = { title = "Power of the Genesaur", description = "Commander, you now have the Will of the Genesaur along with the genesis water and enough seeds to grow an army. Not to mention the Laughing Skulls you helped save.\n\nI would call this mission a success.\n\nI will investigate this fortress further and see if there are more materials we might glean from it.\n\nIn the meantime, you may want to bring these artifacts you have obtained to Durotan back at the outpost. I will catch up once we have finished here.", objectives = "" }
WordHunterWoW_QuestEN[35429] = { title = "Pollen Power", description = "Those of us who grew up in Gorgrond have long learned a few secrets of the botani that can be used to grow our own plants.\n\nThere is no such thing as a hungry Laughing Skull for this reason.\n\nThe ravagers are the key.\n\nOutside of Evermorn Springs you will find ravagers of every type. Slay them and bring me the pollen they carry, and I can cultivate it to be of use to your garrison.", objectives = "" }
WordHunterWoW_QuestEN[35430] = { title = "Cutter", description = "You found many Laughing Skulls. All friends, all loved, all dead. But you did not find my precious Cutter.\n\nThey must have taken him to Evermorn Springs.\n\nFind him, and rescue him.\n\nHe is a good boy, and deserves a better death than infesting.\n\nI am going to round up some ravagers and take the place by air. Look for me in Evermorn if you find Cutter before I do.", objectives = "" }
WordHunterWoW_QuestEN[35432] = { title = "Bushwhacker", description = "Kaz is using us, I am sure of it. She is a Laughing Skull and must NOT be trusted.\n\nFor now, I am willing to play along until we can learn more. \n\nKaz is going to ask for you to travel to Evermorn Springs. When there, I recommend you slay any botani you encounter.\n\nCulling the numbers of these horrific casters will hopefully save future orcs from such a infested fate.\n\nI will stay with Kaz and keep a close eye on her.", objectives = "" }
WordHunterWoW_QuestEN[35433] = { title = "Cut Them Down", description = "They steal children? Children?!\n\nHad you not rescued Kaz's child, he would be reduced to mulch just like the others.\n\nYou should send them a message they will understand. Cut down their great dew casters. Rip them apart.\n\nLet them know that it is not okay to take our children.", objectives = "" }
WordHunterWoW_QuestEN[35434] = { title = "The Life Spring", description = "It sounds like these... \"dwarves\"... you found managed to steal a powerful botani artifact.\n\nBut the fools didn't know they need a special water to power it.\n\nTo the north is a well along the Evermorn Rise.\n\nThere you will find a guardian, a creature of water we have named Utrophis.\n\nSlay it and take its essence and you will be one step closer to claiming the power of the botani and their genesaur.", objectives = "" }
WordHunterWoW_QuestEN[35444] = { title = "The Southern Wilds", description = "First the Iron Horde, then the Shadowmoon orcs, and now there's trouble brewing to the south!\n\nMy brother is a feyrider to the south, at the Draakorium.\n\nHe says that creatures from the swamp are venturing onto our lands. What is this world coming to?\n\nAnyway, you look like a seasoned adventurer. If you are heading that way, would you mind checking in over there?", objectives = "" }
WordHunterWoW_QuestEN[35450] = { title = "The Southern Wilds", description = "I've heard disturbing news from our friends at The Draakorium, to the south.\n\nThe town lies near a swamp, and recently, dangerous creatures have been venturing near its borders.\n\nYou seem like a seasoned adventurer. If you are heading that way, would you mind checking in with our people there?\n\nI would feel much better if I knew they were safe.", objectives = "" }
WordHunterWoW_QuestEN[35459] = { title = "The Southern Wilds", description = "Posted by: Prelate Reenu\n\nNoble friends of the Alliance, the draenei of The Draakorium greet you peacefully.\n\nThe Draakorium is being attacked by enemies from the nearby swamps.\n\nAn Azerothian caravan passed through recently, and may have ventured into dangerous territory.\n\nAny capable adventurer who can assist us with this problem will be rewarded handsomely.", objectives = "" }
WordHunterWoW_QuestEN[35460] = { title = "Attack of the Iron Horde", description = "We received reports of the Dark Portal turning red right before the attack. They call themselves the Iron Horde, yet they seem to have no affiliation with the Horde we know.\n\nTheir army is extremely well equipped, and their numbers appear to be unending.\n\nThey have already taken Nethergarde Keep. Our troops on the frontlines could use your help, {class}.", objectives = "" }
WordHunterWoW_QuestEN[35462] = { title = "Under Siege", description = "Those Iron Horde cannons are laying waste to our troops. I'm not sure how much more of this we can handle. Our forces are already spread too thin.\n\nThere has to be a way to stop those war machines.", objectives = "" }
WordHunterWoW_QuestEN[35463] = { title = "Subversive Scouts", description = "We have been unable to execute a vast majority of our battleplans. We are definitely being watched.\n\nThe Iron Horde must have scouts planted throughout the Blasted Lands. Victory is slipping away from us.", objectives = "" }
WordHunterWoW_QuestEN[35464] = { title = "Ending Executions", description = "We arrived as soon as we could... but we are too late. Nethergarde has fallen. The Iron Horde has taken a number of Nethergarde warriors prisoner.\n\nNo doubt they are trying to squeeze vital information out of our troops.\n\nI fear once they are done with their interrogation they will not hesitate to execute their prisoners. Time is running out.", objectives = "" }
WordHunterWoW_QuestEN[35482] = { title = "Admiral Taylor", description = "Admiral Taylor had figured out who was behind all this. He told us to save who we could... he wanted to handle matters himself.\n\nWe never heard from him again, but we have our orders.\n\nPlease... please find him. He went towards the farm.", objectives = "" }
WordHunterWoW_QuestEN[35486] = { title = "Lunatic Lieutenants", description = "It is time we learned more about our new enemy.\n\nOur scouts have identified a number of the Iron Horde's lieutenants. Their attack is too organized to be run by tribal knowledge alone. Surely their lieutenants have access to secret battleplans. \n\nYou are the only soldier I can trust with this mission, {name}.", objectives = "" }
WordHunterWoW_QuestEN[35487] = { title = "We Burn the Dead", description = "I saw lots of bodies here. Kaz always said to burn the bodies.\n\nThat way they can't come back as the mean greens.\n\nWe should burn the bodies.", objectives = "" }
WordHunterWoW_QuestEN[35488] = { title = "Death to the Dreadmaul", description = "The stupidity of the Dreadmaul ogres never ceases to amaze me. The Iron Horde is clearly using them to further their own nefarious agenda.\n\nRegardless, we must show the ogres what happens when you confront the Alliance. I think it's time we send the Dreadmaul ogres a message.", objectives = "" }
WordHunterWoW_QuestEN[35492] = { title = "For Nethergarde!", description = "The Iron Horde controls Nethergarde Keep, but they are fools if they think we will not return to claim our land.\n\nMy best troops are more than eager to spill the blood of those savages, but we need a champion like yourself to lead the charge.", objectives = "" }
WordHunterWoW_QuestEN[35494] = { title = "Mementos of the Fallen", description = "There were so many of them. The guards couldn't stop them... nobody could stop them. So many souls stripped of their bodies by those savages.\n\nWe must not forget those that gave their lives to try and defend Nethergarde. Please, if you find any mementos of the fallen, bring them back to me.", objectives = "" }
WordHunterWoW_QuestEN[35495] = { title = "Toothsmash the Annihilator", description = "If the battleplans you brought back are true, the Dreadmaul ogres are as much to blame for this devastation as the Iron Horde. It's time we send those ogres a message.\n\nIt looks like the Iron Horde's main contact is a large ogre in Dreadmaul named Toothsmash. Killing him will put a dent in their battleplans.", objectives = "" }
WordHunterWoW_QuestEN[35496] = { title = "Enohar's Revenge", description = "They... they killed my sister. Those beasts marched right through the front gates and... it was horrible.\n\nThe Dreadmaul ogres stood beside them during the attack. They will all suffer. Here take this poison, place a couple drops in their rat stew. The poison will slowly eat away at their insides. Causing a prolonged and painful death, just like they deserve.\n\nPlease, for my sister.", objectives = "" }
WordHunterWoW_QuestEN[35499] = { title = "Blow up towers", description = "xxxxx", objectives = "" }
WordHunterWoW_QuestEN[35500] = { title = "Gar'mak Bladetwist", description = "With the intelligence you have gathered we have learned this assault is being led by a powerful Iron Horde orc named Gar'mak Bladetwist. He is hunkered down inside Okril'lon Hold.\n\nKilling him will not win this war, but it will surely break down the Iron Horde's communication. This will buy us valuable time while we gather more forces and outline a battleplan to deal with this new threat.", objectives = "" }
WordHunterWoW_QuestEN[35501] = { title = "Doomshot", description = "This ominously large explosive appears to be ammunition for the primary cannon that the Bastion is built around.\n\nThe loading assembly must be on a lower floor, but this ammo did not make it that far.", objectives = "" }
WordHunterWoW_QuestEN[35505] = { title = "Lost Lumberjack", description = "Me friend was in the mole machine wit' me. Good ol' Frenna tried to make the best of it by writin' all o' her observations down in a journal.\n\nPenny here wants me to tell ya where she is. I cannae say for sure, but she was followin' me outta here and I don't think she made it.", objectives = "" }
WordHunterWoW_QuestEN[35506] = { title = "Growing Wood", description = "I found this dwarf, Thuldren, runnin' out of Tangleheart like his boots were on fire.\n\nSays his mole machine showed up here and he barely made it out alive. And another called Frenna might still be inside.\n\nOne useful thing he told me is that the creatures in there have sap that can be used to grow things real fast.\n\nBy the way, I'm gonna go lookin' for Thuldren's mole machine. Find me in Tangleheart when you're done.", objectives = "" }
WordHunterWoW_QuestEN[35507] = { title = "Down the Goren Hole", description = "Dwarves are dumb. Don't they know that if you dig a deep hole you are going to have goren attack?\n\nIf you are going to go into that iron fort you better kill a bunch of goren otherwise they are going to chew the walls enough to cause a cave-in.\n\nI would do it myself but I'm still stuffed from all that fruit the botani made me eat.", objectives = "" }
WordHunterWoW_QuestEN[35508] = { title = "Chapter I: Plant Food", description = "There are strange, glowing objects within Tangleheart, seemingly pollinated by a variety of stinging creature.\n\nThe botani sometimes collect whatever the pods produce. I can't be sure what it is, but it might be dangerous to us.\n\n- Frenna", objectives = "" }
WordHunterWoW_QuestEN[35509] = { title = "Will of the Genesaur", description = "I am pretty sure those dwarves took the artifact in that iron fort there.\n\nAre you going to go get it?", objectives = "" }
WordHunterWoW_QuestEN[35510] = { title = "Iyu", description = "There is a genesaur here!\n\nIt wants its artifact back.\n\nKaz and Draka are fighting it now on the surface but they need you. Draka said I could fire the big gun. So I will stay here and do that.", objectives = "" }
WordHunterWoW_QuestEN[35511] = { title = "Kaz the Shrieker", description = "", objectives = "" }
WordHunterWoW_QuestEN[35524] = { title = "Chapter III: Ritual of the Charred", description = "I have seen a strange ritual performed by ancients. They step into fire, burning the leaves from their branches and charring their bark.\n\nI call it the Ritual of the Charred. If we want to weaken the ancients, we can get rid of them before they become even stronger.\n\n- Frenna", objectives = "" }
WordHunterWoW_QuestEN[35527] = { title = "Chapter II: The Harvest", description = "I have seen a creature working with the ancient saplings, imbuing them with anger and hatred toward creatures unlike them.\n\nPerhaps it is this botani who is responsible for the unusually aggressive nature of ancients here in Tangleheart.\n\nWould killing this botani do us good? I fear I would be no match for it alone.\n\n- Frenna", objectives = "" }
WordHunterWoW_QuestEN[35536] = { title = "Secrets of the Botani", description = "The botani must have stuck that big ogron there to protect something fancy. And what was that stumpy looking creature that it killed?\n\nThe botani are mean, but they have some fun toys. Maybe Kaz might know what it was.\n\nCan we go find Kaz now?\n\nI saw a compost heap up the south hill. If Kaz came looking for me I bet she would start there.", objectives = "" }
WordHunterWoW_QuestEN[35537] = { title = "News from Spires of Arak", description = "Commander, scouts from Spires of Arak have brought back news to the garrison. There's word of a brewin' war between bird-men and the Shattered Hand orcs.\n\nRokhan's askin' for your presence when your work is done here, should ya be willin' sir.", objectives = "" }
WordHunterWoW_QuestEN[35549] = { title = "Honoring a Hero", description = "By the Light...\n\nI can't believe this happened to Taylor and his men when they had a full garrison.\n\nIt's going to take everything we have to keep your outpost safe, commander.\n\nWe should get out of here. We can honor the fallen when we're safe.", objectives = "" }
WordHunterWoW_QuestEN[35550] = { title = "Surviving in a Savage Land", description = "Dey may be Alliance, but Admiral Taylor and his men fought with honor on da battlefield.\n\nDey deserve our respect, warchief be praised.\n\nIf an entire garrison be fallin' to dark magic, our work be cut out for us, eh commander?\n\nWe should be goin' back to base. It safe there.\n\nSafer, anyway.", objectives = "" }
WordHunterWoW_QuestEN[35552] = { title = "Trust No One", description = "Nothing is the same since I returned. There is always whispering - everywhere, whispering. Maraad cannot see it, but there are even traces of fel energy here in Elodor. We have been infiltrated!\n\nI must attend to the Exarch Council, but I need you to investigate. Follow the traces of fel energy that I will illuminate. If there are truly traitors in our midst, they will have to have some sort of hideout. Find it! I will wait for you with the other Exarchs.", objectives = "" }
WordHunterWoW_QuestEN[35554] = { title = "News from Spires of Arak", description = "While you were gone, a rather shady looking human arrived at the outpost asking for you. He said he worked for... Grey was it?... and had some information regarding Spires of Arak that you would be interested in.\n\nHe was heading back to your garrison and asked that I passed along the message, and so I have.\n\nAnd before you go, thank you for all you've done for us here, truly. You and your army have turned the tides of a war that you could have just as easily walked away from. We will not forget.", objectives = "" }
WordHunterWoW_QuestEN[35556] = { title = "The Secrets of Gorgrond", description = "Commander, Yrel and Maraad have a tactical suggestion.\n\nThey recommend a small expedition group be sent into the savage wastelands of Gorgrond far to the north.\n\nReports from their rangari suggest that land may hold ancient secrets or primal knowledge that we might use to exploit weaknesses in the Iron Horde that our enemy would not expect.\n\nIf you wish to go I will have a gryphon prepared for you at once.", objectives = "" }
WordHunterWoW_QuestEN[35557] = { title = "The Secrets of Gorgrond", description = "Commander, Durotan calls for aid in leading a small strike team into Gorgrond to launch a counter attack against the Iron Horde strongholds there.\n\nThe land is home to the Blackrock clan, industrial arm of the Iron Horde.\n\nIt is also home to some of the most savage giants and monsters in all of Draenor.\n\nIf you wish to answer this call to action, Gorgrond can be reached through the eastern side of Frostfire Ridge through Thunder Pass.", objectives = "" }
WordHunterWoW_QuestEN[35596] = { title = "Feline Friends Forever", description = "", objectives = "" }
WordHunterWoW_QuestEN[35611] = { title = "Return to Veil Terokk", description = "<A small note is tied to the kaliri's foot.>\n\n\"Percy should have brought with him a basket of goods, assuming he didn't dump it off somewhere along the way. The contents are a token of my gratitude and an apology for the altercation with your scout.\n\nI must urge you to return to Veil Terokk so we may press forward with our plans.\n\n- Reshad \"", objectives = "" }
WordHunterWoW_QuestEN[35614] = { title = "Artificer Romuul", description = "", objectives = "" }
WordHunterWoW_QuestEN[35617] = { title = "Fiona", description = "", objectives = "" }
WordHunterWoW_QuestEN[35618] = { title = "Gidwin Goldbraids", description = "", objectives = "" }
WordHunterWoW_QuestEN[35619] = { title = "Pinchwhistle Gearworks", description = "Commander, a goblin courier arrived this morning.\n\nHe mentioned that he is from a settlement to the southeast called the Pinchwhistle Gearworks. They have requested our assistance with some sort of ecological disaster.\n\nIf we can earn their trust it'll be worth the effort. Head down there and see what sort of assistance we can provide.\n\nI've already spoken to the flight master and he's set up a special flight to get you out there.", objectives = "" }
WordHunterWoW_QuestEN[35620] = { title = "Pinchwhistle Gearworks", description = "Commander, a courier arrived this morning.\n\nHe said he's from a goblin settlement to the southeast called the Pinchwhistle Gearworks. They've asked for our assistance with some sort of ecological disaster.\n\nWe're spread thin but if we can earn their trust then we might be able to gain a valuable ally.\n\nHead down there and see what sort of assistance we can provide. I've already spoken to the flight master and he's set up a special flight to get you out there.", objectives = "" }
WordHunterWoW_QuestEN[35621] = { title = "Tarenar Sunstrike", description = "", objectives = "" }
WordHunterWoW_QuestEN[35625] = { title = "Shelly Hamby", description = "", objectives = "" }
WordHunterWoW_QuestEN[35631] = { title = "Rulkan", description = "", objectives = "" }
WordHunterWoW_QuestEN[35632] = { title = "A Lesson in Archaeology", description = "As an archaeologist, it's important to make great discoveries and contributions to the field. Why? Because that's how you make a name for yourself!\n\nEven that hack Harrison Jones has a somewhat reputable name. If he can do it, then you can too!\n\nThe Highmaul are hiding something big in that cave of theirs and we need to get in there and take it!\n\nTake this teleportation beacon and make your way to the back of the cave. Once you find the relic, place the beacon and my team will take care of the rest!", objectives = "" }
WordHunterWoW_QuestEN[35633] = { title = "Scout Forensics", description = "My entire squad is gone. Some are dead; that much is obvious. The others though... they must be further in.\n\nGo and search the bodies of my squad that you find, each will carry a small pouch of personal items. I would like to return these to their families.\n\nI will go ahead and meet you inside the marsh.", objectives = "" }
WordHunterWoW_QuestEN[35634] = { title = "Control is King", description = "Apexis technology is fascinating, isn't it? Machines powered by solar energy. Energy which itself has been imbued with magic!\n\nSimply brilliant!\n\nAh, but there's always a catch. And I think you may have found it.\n\nBring the interface device back to Veil Terokk, will you? I'll be along shortly with the Apexis cores.\n\nIf my theory is right, we may be able to turn the Adherents' own weapon against them!", objectives = "" }
WordHunterWoW_QuestEN[35636] = { title = "All Due Respect", description = "A group of Adherents came 'round just before the attack on Skettis. Disguised myself as a mushroom, I did. The fools walked right past me.\n\nMy neighbor up the road was not so lucky.\n\nHe had a fondness for texts, if I recall. Might be valuable information in his hut, if you give Reshad a moment to rummage around.\n\nOh, and bring one of his feathers to the shrine near Veil Terokk, would you? He was such a dear, and I know it's what he'd want.", objectives = "" }
WordHunterWoW_QuestEN[35640] = { title = "Vengeance for the Fallen", description = "I... almost made it out.  Most of us... dead. The others... they are no longer themselves.\n\nThese lurching spore beasts are the cause, dragging us further into the marsh... stop them.", objectives = "" }
WordHunterWoW_QuestEN[35642] = { title = "Mysterious Pod", description = "This pod is similar to the ones growing on or near the bodies around here, except this one is pulsating weirdly.\n\nThis is something Khaano would be interested in.", objectives = "" }
WordHunterWoW_QuestEN[35644] = { title = "Mercy for the Living", description = "You can see that the dead were the lucky ones. Those that live wander about attacking anything not infected with these vile spores.\n\nI cannot bring myself to slay them, but if you could bring mercy to those poor people I would be very grateful.", objectives = "" }
WordHunterWoW_QuestEN[35645] = { title = "The Secret of the Fungus", description = "I'm beginning to sense a strong... connection... between the fungus and the creatures that inhabit it. There are certain mushrooms that are stronger than others.\n\nI believe if I had some samples of these I could use them, track the source of this foul fungus and... deal with it.", objectives = "" }
WordHunterWoW_QuestEN[35647] = { title = "A Grim Harvest", description = "The spores grow thick further into the marsh, but those larger fungus beasts are the key.\n\nYes, kill them and take their spore sacs. I will need them to refine my... search.", objectives = "" }
WordHunterWoW_QuestEN[35650] = { title = "Chapter III: Ritual of the Charred", description = "I have seen a strange ritual performed by ancients. They step into fire, burning the leaves from their branches and charring their bark.\n\nI call it the Ritual of the Charred. If we want to weaken the ancients, we can get rid of them before they become even stronger.\n\n- Frenna", objectives = "" }
WordHunterWoW_QuestEN[35651] = { title = "Chapter II: The Harvest", description = "I have seen a creature working with the ancient saplings, imbuing them with anger and hatred toward creatures unlike them.\n\nPerhaps it is this botani who is responsible for the unusually aggressive nature of ancients here in Tangleheart.\n\nWould killing this botani do us good? I fear I would be no match for it alone.\n\n- Frenna", objectives = "" }
WordHunterWoW_QuestEN[35652] = { title = "Growing Wood", description = "We got the lumber mill good an' built, but we be needin' more wood!\n\nThe Rangari tol' me there's botani usin' some kinda sap to grow ancients fast as you like.\n\nGet yer hands on some o' that sap and I betcha I can put it work.\n\nWhat? Oh, Glyza here? Found 'er crashed here and she knows a thing or two about lumberjackin'. I'll take her back to the outpost later.\n\nI'll meet ya inside Tangleheart if I can find it.", objectives = "" }
WordHunterWoW_QuestEN[35654] = { title = "Chapter I: Plant Food", description = "There are strange, glowing objects within Tangleheart, seemingly pollinated by a variety of stinging creature.\n\nThe botani sometimes collect whatever the pods produce. I can't be sure what it is, but it might be dangerous to us.\n\n- Frenna", objectives = "" }
WordHunterWoW_QuestEN[35656] = { title = "A Heartfelt Search", description = "I can feel a powerful presence in the marsh {name}, it is not far from here.\n\nGo see what is there while I finish my grim feast.  I will catch up...", objectives = "" }
WordHunterWoW_QuestEN[35659] = { title = "Heart of the Fen", description = "The pounding in my head is almost unbearable but I must see this through. With all the spore samples I've taken I know where to go and what to do.\n\nI will find the source and spread... no! Destroy it! I will do what needs to be done!", objectives = "" }
WordHunterWoW_QuestEN[35663] = { title = "A Lesson in Teamwork", description = "One of the most important skills an archaeology team needs is good teamwork. The key to teamwork is knowing when to give and when to take.\n\nThe Highmaul ogres have been excavating mysterious artifacts from the gorge. I want you to team up with the Highmaul ogres in the name of good archaeology!\n\nRemember what I said about giving and taking? The ogres have given us their hard work to excavate the artifacts. Now I want you to take those artifacts from them and bring them here!\n\nIt's teamwork!", objectives = "" }
WordHunterWoW_QuestEN[35664] = { title = "Seedbearers of Bad News", description = "When these seedbearers are slain their seeds survive. From them spring new seedbearers, not over years, but hours.\n\nLeaving their remains here would soon cause the outpost to be overrun.\n\nWe have learned that burning their remains prevents this from happening.", objectives = "" }
WordHunterWoW_QuestEN[35665] = { title = "We Have Company", description = "Commander, I've spotted Iron Horde soldiers nearby.\n\nIt is bold, even for them, to venture into such deadly territory.\n\nIf we do not deal with their presence, they will surely be a threat to your camp.\n\nWhile I scout deeper into the canyons, may I request your help in investigating the camp?", objectives = "" }
WordHunterWoW_QuestEN[35666] = { title = "Rangari in the Red", description = "Gorgrond is a very dangerous place and I've sent scouting squads out to investigate various regions.\n\nI've sent one squad to the marsh called the Crimson Fen and they've not come back yet.  I'd like you to find the missing squad and get a report if possible.", objectives = "" }
WordHunterWoW_QuestEN[35667] = { title = "Skulltakers in Crimson Fen", description = "Grulkor and his group are often not seen for weeks, returning only when they can carry no more trophies and supplies. He has been gone too long this time.\n\nHe mentioned hunting in the Crimson Fen for the first time, see if he still lives.", objectives = "" }
WordHunterWoW_QuestEN[35668] = { title = "Syth's Secret", description = "Our deceased friend here was hiding more than a love of old scrolls and erotic sorcery-fiction. He had something truly valuable.\n\nIf I'm reading his notes correctly, he claims to have found the Eye of Anzu - Terokk's scrying orb from the days after his fall.\n\nWe need that orb! The notes say he stashed it in a ravager den just up the road.", objectives = "" }
WordHunterWoW_QuestEN[35669] = { title = "WANTED: Keeho's Severed Paw", description = "Posted by: Taskmaster Gornek\n\nThe saberon known as Keeho poses a serious threat to Axefall.\n\nHe has taken to slaughtering peons on the night shift and dragging their corpses to his den in the pridelands.\n\nAnyone who can bring me his severed paw as proof of his demise will be rewarded greatly.", objectives = "" }
WordHunterWoW_QuestEN[35670] = { title = "WANTED: Spineslicer's Husk", description = "Posted by: Killga\n\nI will greatly reward anyone who brings me Spineslicer's husk.\n\nI wish to fashion fine ravager armor, but do not have the skills to take down such a beast.\n\nDon't tear too many holes in it.", objectives = "" }
WordHunterWoW_QuestEN[35671] = { title = "A Gathering of Shadows", description = "Veil Terokk is just ahead.\n\nLet us hope the others have made the journey safely.", objectives = "" }
WordHunterWoW_QuestEN[35672] = { title = "WANTED: Venombarb", description = "Posted by: Hutou Featherwind\n\nVenombarb is feared in the skies above Arak, even by the high arakkoa.\n\nShe has made air travel difficult for our riders, preventing vital supplies from reaching Axefall.\n\nI require no proof of her demise, simply ensure her screech never again echoes among the spires.\n\nShe nests above the howling crag to the northeast.", objectives = "" }
WordHunterWoW_QuestEN[35674] = { title = "WANTED: Keeho's Severed Paw", description = "Posted by: Lieutenant Willem\n\nKeeho, a monstrous saberon, has taken to raiding Southport at night. We're losing men left and right.\n\nI offer a hefty bounty to anyone able to track down Kreeho and bring his severed paw to me.", objectives = "" }
WordHunterWoW_QuestEN[35675] = { title = "WANTED: Spineslicer's Husk", description = "Posted by: Quartermaster Jolie\n\nWe're running out of supplies to repair our troops' armor.\n\nI'll pay handsomely for the husk of the mighty ravager Spineslicer. It would provide us with repair materials for weeks.", objectives = "" }
WordHunterWoW_QuestEN[35676] = { title = "WANTED: Venombarb", description = "Posted by: Falrogh\n\nVenombarb taunts me every day. Screeching and killing me buzz.\n\nSomebody, anybody, kill the beast. I don't want proof, I want peace and quiet.", objectives = "" }
WordHunterWoW_QuestEN[35679] = { title = "Garrison Campaign: The Fall of Shattrath", description = "Greetings, {name}. I bring another message from Archmage Khadgar.\n\nWe can no longer ignore Socrethar's presence at Shattrath. He spreads dangerous beliefs, converting more draenei to his \"new order\" with each passing day.\n\nThe time has come for us to confront him.\n\nExarch Maladaar should be expecting you at the Spire of Light in Talador. Good luck, {name}.", objectives = "" }
WordHunterWoW_QuestEN[35680] = { title = "Garrison Campaign: The Fall of Shattrath", description = "Greetings, {name}. I bring another message from Archmage Khadgar.\n\nWe can no longer ignore Socrethar's presence at Shattrath. He spreads dangerous beliefs, converting more draenei to his \"new order\" with each passing day.\n\nThe time has come for us to confront him.\n\nLady Liadrin should be expecting you at the Spire of Light in Talador. Good luck, {name}.", objectives = "" }
WordHunterWoW_QuestEN[35683] = { title = "Reclaiming the City", description = "The Shattrath offensive is going well, but Socrethar refuses to show himself.\n\nDespite our best efforts, we are unable to break into the inner city of Shattrath. The dome's defenses are simply too strong.\n\nHowever, we think we can lure Socrethar out of hiding. Defeat his lieutenants and warriors, and gather their medallions of service.\n\nWhen we show him proof of their demise, his pride will surely force him to face us.", objectives = "" }
WordHunterWoW_QuestEN[35684] = { title = "Reclaiming the City", description = "The Shattrath offensive is going well, but Socrethar refuses to show himself.\n\nAnd despite our best efforts, we are unable to break into the inner city, where he resides.\n\nHowever, we think we can lure Socrethar out of hiding. Defeat his lieutenants and warriors, then gather their medallions of service.\n\nWhen we show him proof of their demise, his pride will surely force him to face us.", objectives = "" }
WordHunterWoW_QuestEN[35685] = { title = "Socrethar's Demise", description = "Meet me down by the entrance to the Shattrath dome.\n\nThere, we will issue our challenge to the Sargerei leader. If he accepts our challenge, it is there that he shall meet his end.\n\nThe creature that calls himself Socrethar was once my brethren. I can only hope that there is still some Light left within him.", objectives = "" }
WordHunterWoW_QuestEN[35686] = { title = "Rage and Wisdom", description = "An endless war wages between the creatures of the eastern wilds and the beasts of the western wasteland.\n\nShould one side overwhelm the other, all of Draenor would fall at the hand of the victor.\n\nI sent Rangari Erdanii to the heart of the battle between these two forces. It is likely that she will need your help, commander.", objectives = "" }
WordHunterWoW_QuestEN[35687] = { title = "Socrethar's Demise", description = "Meet me down by the entrance to the Shattrath dome.\n\nThere, we shall issue our challenge to the Sargerei leader. If he accepts, it is there that he shall meet his end.\n\nI must admit, {name}, I am looking forward to this.", objectives = "" }
WordHunterWoW_QuestEN[35693] = { title = "A Harsh Reminder", description = "Welcome to the front lines, commander, where the wastelands and the jungle collide.\n\nThe battle below rages on, but I believe one side is beginning to overwhelm the other. This cannot be allowed to happen.\n\nThe gronnlings are gaining an upper hand and must be stopped before they pose a threat to Highpass.\n\nI will get closer to the battle while you thin their ranks. Meet me within Affliction Ridge when you are done.", objectives = "" }
WordHunterWoW_QuestEN[35697] = { title = "Peace Offering", description = "We need allies amongst these spires, and quickly. Commander, I believe it would be wise if you sought out aid.\n\nThere is a lone arakkoa outcast southeast of here living near a ravager nest. The ravagers do not attack him - I suspect he has information on the beasts we may be able to use.\n\nI have our last crate of cactus apple surprise ready for you. It is our best shot, sir.", objectives = "" }
WordHunterWoW_QuestEN[35699] = { title = "Peace Offering", description = "We could really use an ally to trade with, commander.\n\nThere's an arakkoa outcast living in the middle of a ravager nest northeast of here... do you think he might ally with us? He must have some sort of secret to keeping those ravagers at bay.\n\nI have one last crate of my Northshire Port. Maybe that will help convince him that we're friendly.", objectives = "" }
WordHunterWoW_QuestEN[35702] = { title = "Chains of Iron", description = "The artifact we seek is within our grasp.\n\nBe prepared for a fight. If they truly have learned how to control gronn, this may be more difficult than I anticipated.\n\nI will join you in this battle as soon as you arrive.", objectives = "" }
WordHunterWoW_QuestEN[35704] = { title = "When All Is Aligned", description = "The ravenspeaker acolytes have been equipped with Apexis interfaces, they just need to get close enough.\n\nCome, let us take to the skies and secure the Terrace of Dawn.\n\nWhen all is aligned, we shall turn the false suns against one another and the spires shall burn like torches!\n\nI look forward to penning your actions into history.", objectives = "" }
WordHunterWoW_QuestEN[35705] = { title = "Best Deals Anywhere", description = "Commander, two goblin smugglers - Mixxy and Trixxy Weldblast - came through here recently and went off towards the bog to the east.\n\nThey had drilling equipment but weren't carrying any weapons, sir.\n\nI'd bet anything that they'll have materials we'd want, and that they could use some protection in return.\n\nCommander, I think seeking them out would be a good idea.", objectives = "" }
WordHunterWoW_QuestEN[35706] = { title = "Sticky Situation", description = "We were hauling batteries to the excavation site and I crashed my freakin' car!\n\nMy sister didn't even look back. I took the turn a little fast, so what? It happens!\n\nPoint is, the batteries went flying everywhere and I'm in no condition to lift them out.\n\nSo what do you say? Wanna help me out?", objectives = "" }
WordHunterWoW_QuestEN[35707] = { title = "Tangleheart", description = "Hey there, peach. We've got the lumber mill good and ready, but we gotta find a way of choppin' wood fast out here.\n\nThe Laughing Skull talked about Tangleheart, where the botani grow things quick as a quark.\n\nI'm headin' there now.", objectives = "" }
WordHunterWoW_QuestEN[35708] = { title = "Tangleheart", description = "The Rangari have been here for a tick, and they hear tell from the Laughing Skull o' a place called Tangleheart.\n\nSeems some really bad ancients come from there, and botani use a kind o' sap to grow them quickly.\n\nI think we could use that for yer outpost. Hey, wood is wood, right?\n\nI'll meet ya there.", objectives = "" }
WordHunterWoW_QuestEN[35713] = { title = "The Tinkertoss Twins", description = "Commander, two gnomish smugglers passed by while you were out - Filbert and Dilbert Tinkertoss. They were headed towards the bog to the east.\n\nThey had all sorts of drilling equipment but didn't seem to have any weapons.\n\nWhat do you think of offering them protection in exchange for some of their materials?\n\nI'll jot down where they were headed in case you decide to go.", objectives = "" }
WordHunterWoW_QuestEN[35716] = { title = "Sticky Situation", description = "A squadron of arakkoa spotted us while we were en route to the excavation site and took out our caravan. My brother made it to safety in the chaos.\n\nLucky son of a tinker.\n\nI can't leave without the batteries for our drill, but they all fell into the bog and I can't even get them to budge.\n\nAny chance you could retrieve them for me?", objectives = "" }
WordHunterWoW_QuestEN[35718] = { title = "Back on Track", description = "You're a lifesaver, I'll tell you what.\n\nSay, how about you go on ahead to the excavation site and let my sister know I'm on my way. I'll get everything neat and tidy and go get a new cart to lug these over.", objectives = "" }
WordHunterWoW_QuestEN[35719] = { title = "Back on Track", description = "Now that the batteries are out of the bog I can radio in some more copters to take them to camp.\n\nI'll stay here until they arrive, but you should go ahead to my brother Dilbert and let him know what happened. He must be worried sick!", objectives = "" }
WordHunterWoW_QuestEN[35730] = { title = "Cauterizing Wounds", description = "You have saved my most precious companion, Nisha. I owe you a great debt.\n\nThe Iron Horde lured me away to separate us. I shall not make the same mistake again.\n\nThey have inflicted grievous wounds, and I fear we must cause her even more pain before the healing process can begin.\n\nPlease use a burning log from the nearby fire to cauterize her wounds.\n\nI will hold her down.", objectives = "" }
WordHunterWoW_QuestEN[35733] = { title = "Rites of the Talonpriests", description = "That gavel was once known as Beakbreaker. In his final, darkest days, Terokk used it to perform grim, damnable acts of sacrifice. \n\nIt is best not to dwell on those days.\n\nTerokk was sealed away deep within the shadows to rest, and perhaps to heal.\n\nMaking contact with him will take a great deal of effort, so in the meantime, allow me to tell you of his more glorious exploits. Before this wretched curse took hold.\n\nPlease, place the gavel upon the effigy.", objectives = "" }
WordHunterWoW_QuestEN[35734] = { title = "The Talon King", description = "<As Reshad begins reciting a tale of Terokk's glory days, your eyes fall to the twin swords at the effigy's belt.\n\nThey had seemed so plain in Skettis, but now they thrum with power, as if reacting to the scrollkeeper's words.>", objectives = "" }
WordHunterWoW_QuestEN[35736] = { title = "Writing in the Snow", description = "This is a worn page from Shadow Hunter Bwu'ja's journal. It appears to be a sketch of the entrance of the Bloodmaul Slave Mines. Rokhan, in your garrison, would be very interested in this.", objectives = "" }
WordHunterWoW_QuestEN[35737] = { title = "Writing in the Snow", description = "This is a worn page from Owynn Graddock's journal. It appears to be a sketch of the entrance of the Bloodmaul Slave Mines. Bodrick Grey, in your garrison, would be very interested in this.", objectives = "" }
WordHunterWoW_QuestEN[35738] = { title = "All Natural", description = "So you have a smuggler's den, huh?\n\nI'd love to trade with ya, toots, I really would, but my laser cannon isn't even functional right now.\n\nI'll tell you what. See all the ancients around here? They got toasted good by the arakkoa's weapon, and they're practically walking piles of charcoal.\n\nBring me some charcoal to power this thing and you've got a deal.", objectives = "" }
WordHunterWoW_QuestEN[35739] = { title = "All Natural", description = "Oh, you have a trading post?\n\nFantastic!\n\nLet's make a deal. You help me power up my laser cannon, and I'll trade some of this... thermo... ultra... obsidiglass with you for some weapons.\n\nThe ancients all around here are practically made of charcoal after the arakkoa weapon hit, you should go get some of that!", objectives = "" }
WordHunterWoW_QuestEN[35744] = { title = "Ending Executions", description = "We arrived as soon as we could... but we be too late. Da Iron Horde has taken our warriors prisoner.\n\nNo doubt they be trying ta squeeze info out of da troops.\n\nI fear once they are done with da interrogation they gonna execute their prisoners. Time be running out.", objectives = "" }
WordHunterWoW_QuestEN[35745] = { title = "Attack of the Iron Horde", description = "We received reports of the Dark Portal turning red right before the attack. They call themselves the Iron Horde.\n\nTheir army is extremely well equipped, and their numbers appear to be unending.\n\nThey have already taken Okril'lon Hold and Nethergarde Keep. Our troops on the frontlines could use your help, {class}.", objectives = "" }
WordHunterWoW_QuestEN[35746] = { title = "Under Siege", description = "Those Iron Horde cannons are laying waste to our troops. I'm not sure how much more of this we can handle. Our forces are already spread too thin.\n\nThere has to be a way to stop those war machines.", objectives = "" }
WordHunterWoW_QuestEN[35747] = { title = "Taking a Trip to the Top of the Tank", description = "We cannot risk the reactivation of the Dark Portal. Now is the time for the deathblow.\n\nThaelin should have figured out how to get that tank working by now. Take him with you, and turn that tank against the Dark Portal itself. We will follow behind you.", objectives = "" }
WordHunterWoW_QuestEN[35748] = { title = "Subversive Scouts", description = "We have been unable to execute a vast majority of our battleplans. We are definitely being watched.\n\nThe Iron Horde must have scouts planted throughout the Blasted Lands. Victory is slipping away from us.", objectives = "" }
WordHunterWoW_QuestEN[35750] = { title = "Lunatic Lieutenants", description = "It is time we learned more about our new enemy.\n\nOur scouts have identified a number of the Iron Horde's lieutenants. Their attack is too organized to be run by tribal knowledge alone. Surely their lieutenants have access to secret battleplans. \n\nYou are the only soldier I can trust with this mission, {name}.", objectives = "" }
WordHunterWoW_QuestEN[35751] = { title = "Attack on Nethergarde", description = "The Iron Horde controls Nethergarde Keep, but they are fools if they think we will let them retain such a strategic position.\n\nMy best troops are more than eager to spill the blood of those savages, but we need a champion like yourself to lead the charge.", objectives = "" }
WordHunterWoW_QuestEN[35760] = { title = "Toothsmash the Annihilator", description = "If the battleplans you brought back are true, the Dreadmaul ogres are as much to blame for this devastation as the Iron Horde. It's time we send those ogres a message.\n\nIt looks like the Iron Horde's main contact is a large ogre in Dreadmaul named Toothsmash. Killing him will put a dent in their battleplans.", objectives = "" }
WordHunterWoW_QuestEN[35761] = { title = "Ransacking Nethergarde", description = "After the Iron Horde took Nethergarde we attacked. While we killed the Iron Horde at Nethergarde they brought more forces through the portal and took Okril'lon Hold. So many souls stripped of their bodies by those savages.\n\nWe must not forget those that gave their lives at Nethergarde. If you find any mementos of the fallen, bring them back to me.", objectives = "" }
WordHunterWoW_QuestEN[35762] = { title = "Death to the Dreadmaul", description = "The stupidity of the Dreadmaul ogres never ceases to amaze me. The Iron Horde is clearly using them to further their own nefarious agenda.\n\nRegardless, we must show the ogres what happens when you confront the true Horde. I think it's time we send the Dreadmaul ogres a message.", objectives = "" }
WordHunterWoW_QuestEN[35763] = { title = "Gar'mak Bladetwist", description = "With the intelligence you have gathered we have learned this assault is being led by a powerful Iron Horde orc named Gar'mak Bladetwist. He is hunkered down inside Okril'lon Hold.\n\nKilling him will not win this war, but it will surely break down the Iron Horde's communication. This will buy us valuable time while we gather more forces and outline a battleplan to deal with this new threat.", objectives = "" }
WordHunterWoW_QuestEN[35764] = { title = "Okrilla's Revenge", description = "The Dreadmaul ogres think they have bested us? They will all suffer. Here take this poison, place a couple drops in their rat stew.\n\nThe poison will slowly eat away at their insides. Causing a prolonged and painful death, just like they deserve.", objectives = "" }
WordHunterWoW_QuestEN[35766] = { title = "I See Dead Arakkoa", description = "I've got a strange problem and I'm hoping you might be able to help. I don't know who else could help, to be honest.\n\nMy workers keep saying they're seeing the ghost of the arakkoa that used to head up this place.\n\nI know, I know, it's crazy but could you take my Ghostogrifier 12000 to her body and check?\n\nIf there's a ghost around here, it'll find it. If there's not, then my workers are trying to slack off on the clock.", objectives = "" }
WordHunterWoW_QuestEN[35782] = { title = "I See Dead Arakkoa", description = "Say, while you're here would you mind helping me out with a major problem?\n\nThe workers keep saying that they're seeing the ghost of the head arakkoa that used to be here.\n\nI don't believe it for a second but could you take my Ghostogrifier 12000 to her body and check?\n\nIf they're not crazy, it'll prove it.", objectives = "" }
WordHunterWoW_QuestEN[35786] = { title = "Bronze Victory", description = "We're deep in enemy territory, staking our claim. Eventually, the locals will come sniffing around.\n\nWe can't show them weakness. Any attack on us must be met fast and furious.", objectives = "" }
WordHunterWoW_QuestEN[35787] = { title = "Silver Victory", description = "A victory is a twin-edged axe. It stakes a claim, but it also foments rebellion and revenge. We must be complete and decisive.", objectives = "" }
WordHunterWoW_QuestEN[35788] = { title = "Gold Victory", description = "The stronger our enemies, the more soundly we must beat them. With so much at stake, we must strive for total victory.", objectives = "" }
WordHunterWoW_QuestEN[35797] = { title = "The Ebon Hunter", description = "The laser should be good to go once we get it set up, there's just one more thing I need.\n\nThere's a spore walker that hunts on the delta just southeast from here. It has an apparatus on its face that can fire a powerful laser - way more powerful than what we have hooked up.\n\nI want it.\n\nWe'll be mining faster than you can imagine once we get that bad boy hooked up!", objectives = "" }
WordHunterWoW_QuestEN[35807] = { title = "Trophy of Glory: Erosian", description = "Defeating Erosian has yielded you a trophy worthy of acclaim.\n\nTake this to Durotan at Beastwatch.", objectives = "" }
WordHunterWoW_QuestEN[35808] = { title = "Trophy of Glory: Erosian", description = "Defeating Erosian has yielded you a trophy worthy of acclaim.\n\nTake this to Maraad at Highpass.", objectives = "" }
WordHunterWoW_QuestEN[35809] = { title = "Trophy of Glory: Dessicus", description = "Defeating Dessicus has yielded you a trophy worthy of acclaim.\n\nTake this to Maraad at Highpass.", objectives = "" }
WordHunterWoW_QuestEN[35810] = { title = "Trophy of Glory: Dessicus", description = "Defeating Dessicus has yielded you a trophy worthy of acclaim.\n\nTake this to Durotan at Beastwatch.", objectives = "" }
WordHunterWoW_QuestEN[35811] = { title = "Trophy of Glory: Crater Lord Igneous", description = "Defeating Crater Lord Igneous has yielded you a trophy worthy of acclaim.\n\nTake this to Durotan at Beastwatch.", objectives = "" }
WordHunterWoW_QuestEN[35812] = { title = "Trophy of Glory: Crater Lord Igneous", description = "Defeating Crater Lord Igneous has yielded you a trophy worthy of acclaim.\n\nTake this to Maraad at Highpass.", objectives = "" }
WordHunterWoW_QuestEN[35813] = { title = "Trophy of Glory: Fungal Praetorian", description = "Defeating the Fungal Praetorian has yielded you a trophy worthy of acclaim.\n\nTake this to Maraad at Highpass.", objectives = "" }
WordHunterWoW_QuestEN[35814] = { title = "Trophy of Glory: Fungal Praetorian", description = "Defeating the Fungal Praetorian has yielded you a trophy worthy of acclaim.\n\nTake this to Durotan at Beastwatch.", objectives = "" }
WordHunterWoW_QuestEN[35815] = { title = "Trophy of Glory: Charl Doomwing", description = "Defeating Charl has yielded you a trophy worthy of acclaim.\n\nTake this to Durotan at Beastwatch.", objectives = "" }
WordHunterWoW_QuestEN[35816] = { title = "Trophy of Glory: Charl Doomwing", description = "Defeating Charl has yielded you a trophy worthy of acclaim.\n\nTake this to Maraad at Highpass.", objectives = "" }
WordHunterWoW_QuestEN[35817] = { title = "Trophy of Glory: Roardan the Sky Terror", description = "Defeating Roardan has yielded you a trophy worthy of acclaim.\n\nTake this to Maraad at Highpass.", objectives = "" }
WordHunterWoW_QuestEN[35818] = { title = "Trophy of Glory: Roardan the Sky Terror", description = "Defeating Roardan has yielded you a trophy worthy of acclaim.\n\nTake this to Durotan at Beastwatch.", objectives = "" }
WordHunterWoW_QuestEN[35819] = { title = "Trophy of Glory: Khargax the Devourer", description = "Defeating Khargax has yielded you a trophy worthy of acclaim.\n\nTake this to Durotan at Beastwatch.", objectives = "" }
WordHunterWoW_QuestEN[35820] = { title = "Trophy of Glory: Khargax the Devourer", description = "Defeating Khargax has yielded you a trophy worthy of showing off at your outpost. \n\nReturn this to Maraad to increase your glory!", objectives = "" }
WordHunterWoW_QuestEN[35828] = { title = "I Drew Aggro...culture", description = "{name}? Boy am I glad to see ya.\n\nI was tryin' ta ditch that genesaur when I stumbled across this rangari camp.\n\nNext thing I know, the ground is creepin' up and spittin' out all sorts of angry plants.\n\nI barely made it out of me tank before that genesaur threw it like it was an empty beer mug.\n\nI'm gonna make my way back to the road an' look fer me tank.\n\nI'll see ya there when yer done.", objectives = "" }
WordHunterWoW_QuestEN[35834] = { title = "Wake of the Genesaur", description = "One moment we see a great metal beast rolling into our camp, the next a genesaur follows it and sends a wave of pure chaotic life at us.\n\nThe manifestations left behind by the genesaur must be culled so we have time to salvage what we can before leaving.\n\nIf you are here to help, then start killing as many of the violent plants that are assailing us as possible.", objectives = "" }
WordHunterWoW_QuestEN[35835] = { title = "The Ebon Hunter", description = "We're ready to set up the laser, but we're going to need more firepower to cut through this stuff.\n\nThe Ebon Hunter stalks the delta just southeast from here. It has an apparatus on its face that can fire a laser way stronger than what we have hooked up.\n\nWe need that.\n\nYou should go get it while we set up the laser.", objectives = "" }
WordHunterWoW_QuestEN[35837] = { title = "Garrison Campaign: Deep Recon", description = "One of my top field operatives, Jeanine Amrell, is stationed deep in Iron Horde territory in northern Nagrand.\n\nShe reports that the warlords of the orcish clans are planning to convene in secret at Mok'gol Watchpost.\n\nThis may be a critical opportunity for us to gain intel on their future plans.\n\nI need you to meet up with agent Amrell immediately. This may be our chance, {name}!", objectives = "" }
WordHunterWoW_QuestEN[35838] = { title = "The Warlord's Council", description = "Upon closer inspection, you notice a piece of leather parchment looped around her neck.\n\nScrawled upon it angrily are the words:\n\n\"WITNESS THE FATE OF THOSE WHO DEFY THE IRON HORDE!\"", objectives = "" }
WordHunterWoW_QuestEN[35839] = { title = "Plans of War", description = "I managed to get my hands on Jeanine's notebook. She identified several key items in the nearby buildings to investigate, but couldn't follow up before her demise.\n\nThe least we can do is follow the lead that she left us.\n\nSearch the camp for the intelligence. I'll keep the orcs distracted.", objectives = "" }
WordHunterWoW_QuestEN[35840] = { title = "Intercepting the Orders", description = "Intelligence is the name of the game, friend. The more we know about Hellscream's plans, the easier it will be to thwart them.\n\nThe Mok'gol orcs often act as Hellscream's couriers, carrying mission orders from this place to his outposts all over Draenor.\n\nKill these riders, and recover any orders that you can find.", objectives = "" }
WordHunterWoW_QuestEN[35841] = { title = "Putting Down the Packleader", description = "Operations at Mok'gol Watchpost are entrusted to a mighty warrior named Packleader Vor'gash.\n\nIf we can take out this fierce leader, we can shut down their communications temporarily.\n\nYou can find Vor'gash patrolling the compound to the northeast.\n\nSlay him.", objectives = "" }
WordHunterWoW_QuestEN[35842] = { title = "Putting Down the Packleader", description = "Da one in charge a Mok'gol Watchpost be Packleader Vor'gash.\n\nWe take him out, we shut dem down.\n\nYa ken find 'im patrolling da compound ta da nor'east.\n\nKill 'im.", objectives = "" }
WordHunterWoW_QuestEN[35843] = { title = "Garrison Campaign: Deep Recon", description = "Ya timin' be good, commanda.\n\nI sent one a ma shadow huntas deep inta da land 'a da enemy.\n\nHe reports dat da warlords be plannin' ta meet in secret at Mok'gol Watchpost.\n\nDis be our chance ta learn what Hellscream be up to.\n\nGo now, and meet wit Zasta. He will tell ya what to do next.", objectives = "" }
WordHunterWoW_QuestEN[35844] = { title = "The Warlord's Council", description = "Upon closer inspection, you notice a piece of leather parchment looped around his neck.\n\nScrawled upon it angrily are the words:\n\n\"WITNESS THE FATE OF THOSE WHO DEFY THE IRON HORDE!\"", objectives = "" }
WordHunterWoW_QuestEN[35845] = { title = "Plans of War", description = "I managed ta recover Zasta's notes. He saw dey Warsong leaders meetin' often in dey nearby buildings. Zasta tinks dere be clues about dey Iron Horde's plans nearby.\n\nDey least we can do is follow dey lead he left us.\n\nSearch dey camp for dey intelligence. I'll keep dey orcs distracted.", objectives = "" }
WordHunterWoW_QuestEN[35846] = { title = "Intercepting the Orders", description = "Intelligence be da name a da game, commanda. Da more we know about Hellscream's plans, da easier it be ta mess dem.\n\nDa Mok'gol orcs be Hellscream's couriers, carrying mission orders from dis place ta his outposts all over Draenor.\n\nKill dese riders, an' recover any orders dat you ken find.", objectives = "" }
WordHunterWoW_QuestEN[35861] = { title = "Garrison Campaign: Darktide Roost", description = "We are getting reports that Iron Horde warships are docking on a small island just south of Shadowmoon Valley.\n\nWe sent in some scouts, but we haven't heard back from them yet. It might be worth investigating.\n\nDungar Longdrink has a gryphon waiting for you when you are ready, commander.", objectives = "" }
WordHunterWoW_QuestEN[35870] = { title = "Basilisk Butcher", description = "Basilisk is one of Nisha's favorite meals. This is where she hunts, and that's likely how those Iron Horde bastards were able to capture her.\n\nWhy would they go to the trouble to subdue her this way? Perhaps together, you and I might learn the answer as we punish them for their transgressions.\n\nFor now, Nisha's going to need some food. While I tend to her, will you do her hunting for her?", objectives = "" }
WordHunterWoW_QuestEN[35876] = { title = "Garrison Campaign: Darktide Roost", description = "We is getting reports dat da Iron Horde warships be dockin' on a small island to da south of da Shadowmoon Valley.\n\nWe be sendin' some scouts, but we haven't heard back yet. We need ta be investigating.\n\nBron Skyhorn has a ryklak waitin' for ya when you be ready, commander.", objectives = "" }
WordHunterWoW_QuestEN[35878] = { title = "Safety Measures", description = "As it turns out, the resonance frequency of the batteries has really upset the local wildlife. I... I think one of the boars looked at me and licked its lips just a moment ago.\n\nI'll make it worth your time if you just... get rid of anything you come across down there. Doesn't matter what it is, just kill it, okay?", objectives = "" }
WordHunterWoW_QuestEN[35879] = { title = "Safety Measures", description = "The batteries I lost in the bog have really ticked off the wild creatures. It's going to be impossible to remove them without fighting through who knows what.\n\nIf you're up for it, why don't you 'take care' of any critters you come across? I don't want some giant beast stalking me back to the excavation site.\n\nI'll make it worth your while.", objectives = "" }
WordHunterWoW_QuestEN[35880] = { title = "Rage and Wisdom", description = "Beasts of the western wasteland fight an endless war with the creatures of the eastern wilds.\n\nIf one side were to overwhelm the other, all of Draenor would be doomed at the hand of the victor.\n\nThe Laughing Skull seek revenge for their destroyed village. I have directed them to aim their vengeance at the nearby creatures, that our outpost here might be preserved.\n\nIf you would, commander, oversee their efforts. I have not yet grown to trust the Laughing Skull.", objectives = "" }
WordHunterWoW_QuestEN[35882] = { title = "The Interest of Bruto", description = "You have done me a great service. This blade is as much yours as it is mine.\n\nI offer you this blood oath: I shall serve your cause and lend my knowledge of blades and mining to your forces.\n\nWill you accept it?", objectives = "" }
WordHunterWoW_QuestEN[35883] = { title = "The Fists of Vaandaam", description = "You have done me a great service. This blade is as much yours as it is mine.\n\nI offer you this blood oath: I shall serve your cause and lend my knowledge of blades and mining to your forces.\n\nWill you accept it?", objectives = "" }
WordHunterWoW_QuestEN[35884] = { title = "The Home Stretch", description = "If they weren't angry before, they sure are now. We won't survive a minute up on top o' this tank!\n\nLet's join up with the rest and get out of here!!", objectives = "" }
WordHunterWoW_QuestEN[35895] = { title = "Terokk's Fall", description = "<Once again, Reshad's voice envelops you.>\n\nTerokk was a powerful and respected king, beloved by his people.\n\nHis sages, however, were not so loyal. Hungry for control of Skyreach, they conspired against him.", objectives = "" }
WordHunterWoW_QuestEN[35896] = { title = "The Avatar of Terokk", description = "My long sleep was disturbed by dreams of the past. I cut down my old enemies again. I watched my daughter die again.\n\nYou were there. I felt your presence in these dreams. And your past was revealed to me as well.\n\nSomeone has woven our fates together. My people are yours to protect, and your enemies are mine to destroy.\n\nThe Shattered Hand are rallied in Bladefist Hold. Left to their own, they would claim this land for the Iron Horde.\n\nTake my power, and together we shall break them.", objectives = "" }
WordHunterWoW_QuestEN[35897] = { title = "The Missing Piece", description = "Terokk's daughter Lithic was a skilled huntress, but found her true passion in goldsmithing.\n\nShe forged this bangle as a gift for her father, and he wore it for many years. Only after Lithic passed away did he remove the bangle, for her memory was too much for the old king to bear.\n\nPlace the bangle upon the effigy, and I shall tell you of Terokk's fall.", objectives = "" }
WordHunterWoW_QuestEN[35905] = { title = "Supply Drop", description = "Your laborers below have finished with the harvest and are ready to cart supplies back to your garrison. Don't worry about the safety of your caravan this time; I will dispatch a rangari detail to shadow them from the woods and protect them.\n\nThe Exarchs will always watch over you.\n\nYour supplies should be waiting for you when you return to your garrison. Good luck with your campaign, {name}!", objectives = "" }
WordHunterWoW_QuestEN[35907] = { title = "Attempted Murder", description = "Your bartender Lunzul is dying, commander. She's been poisoned and needs an antidote immediately.\n\nOne of your scouts reported seeing a Shattered Hand orc nearby recently - that's our best bet.\n\nThere is a small arakkoa camp to the east that sits near a known Shattered Hand encampment. I suggest we start our search there.\n\nI've already spoken to your flight master about securing us a flight; every second counts.", objectives = "" }
WordHunterWoW_QuestEN[35915] = { title = "Attempted Murder", description = "Kolrigg is dyin', commander. He's been poisoned and needs an antidote before it's too late.\n\nOne o' yer scouts reported seein' a Shattered Hand orc nearby not long ago - I wager that's our best shot.\n\nThere's a small arakkoa camp tae the east that sits near a known Shattered Hand encampment. We should start our search there, sir.\n\nI've already spoken to yer flight master about flyin' us out; every second counts.", objectives = "" }
WordHunterWoW_QuestEN[35921] = { title = "Bread and Circuses", description = "Hey, mister, this crumb-bum won't let me in. Interested in some cold, hard cash?\n\nMy boss is promoting fights at the Ring of Trials. You look like you could hold your own.\n\nYou should go fight.", objectives = "" }
WordHunterWoW_QuestEN[35922] = { title = "Bread and Circuses", description = "Hey, mister, this crumb-bum won't let me in. Interested in some cold, hard cash?\n\nMy boss is promoting fights at the Ring of Trials. You look like you could hold your own.\n\nYou should go fight.", objectives = "" }
WordHunterWoW_QuestEN[35924] = { title = "Assassin's Mark", description = "Their poison is more powerful than I thought. We need to find the orc responsible for making it.\n\nMaster assassins always leave their mark somewhere on one of their kills. It's a calling card; a claim to fame in their circles.\n\nThis was definitely the work of such an assassin.\n\nWe should split up and see if we can find some sign on one of the outcast corpses that will lead us to their creator. Rendezvous at the bottom of the hill, commander.", objectives = "" }
WordHunterWoW_QuestEN[35925] = { title = "The Gronn Strategy", description = "Raz,\n\nYour orders are to capture four additional gronn for weaponization.\n\nOf your first group, only one survived the entire process.\n\nOne attacked our soldiers relentlessly and had to be put down. Another fell victim to a misfire while being fitted. Yet another rolled onto its cannons in its sleep. We're still cleaning up that mess.\n\nRest assured, your efforts are not in vain.\n\n- Captain Brak", objectives = "" }
WordHunterWoW_QuestEN[35926] = { title = "Assassin's Mark", description = "We need tae find the orc responsible fer makin' the poison tae make an antidote.\n\nMaster assassins always leave their mark somewhere on one o' their kills. It's a claim tae fame o' sorts. An' trust me, this was the work of a master assassin.\n\nLet's split up and see if we can find some sign on one o' the outcast corpses that will lead us tae their killer. I'll meet ye at the bottom o' the hill, commander.", objectives = "" }
WordHunterWoW_QuestEN[35933] = { title = "Azeroth's Last Stand", description = "Countless times you have battled against impossible odds and unspeakable evil - and returned the victor. Now, once more, you have answered the call of duty, prepared to risk your life to save the world that you love - our world.\n\nYou are Azeroth's last hope, {name}.\n\nWhile the challenges that stand before us are daunting, there is no other that I would trust to lead this mission.\n\nThe enemy at the front may have the information we need to win this war. Seek and destroy!\n\nGo now, {name}! For Azeroth!", objectives = "" }
WordHunterWoW_QuestEN[35934] = { title = "Nisha's Vengeance", description = "Since I left on my last hunt, the Iron Horde have drawn nearer and reinforced their positions.\n\n<A grin spreads across Rexxar's lips.>\n\nThey've created a target-rich environment.\n\nI must continue nursing Nisha to health for now. You go in my stead, friend. Fill them with the fear and pain that they inflicted on her.\n\nMake their screams fill the canyon!", objectives = "" }
WordHunterWoW_QuestEN[35944] = { title = "Proof of Strength: Goren Tooth", description = "This tooth is proof of your strength at slaying goren and your gladiator friend has born witness!\n\nTake the tooth back to Jonaa and claim your accolades!", objectives = "" }
WordHunterWoW_QuestEN[35945] = { title = "Greblin Fastfizzle", description = "I've been hanging here forever!\n\nI was flying around, surveying the area for Nixxie when -- blamo! One of those stupid ogres throws a rock right at me!\n\nMy glider busted and here I am... and boy is this uncomfortable.\n\nHelp me down will ya? I'll make it worth your while.", objectives = "" }
WordHunterWoW_QuestEN[35947] = { title = "The Power of Poison", description = "G.V.? We need a name and a location. Not damned initials.\n\n<Velonara pulls out a small vial.>\n\nThis is my last vial of wracking poison. We use it to extract information from prisoners. It is... potent.\n\nCoat your weapon with it and head into the Shattered Hand camp just ahead. Engage them as normal and demand answers - the poison will take care of the rest. I've had enough of these orcs.", objectives = "" }
WordHunterWoW_QuestEN[35948] = { title = "Proof of Strength: Goren Tooth", description = "This tooth is proof of your strength at slaying goren and your gladiator friend has born witness!\n\nTake the tooth back to Limbflayer and claim your accolades!", objectives = "" }
WordHunterWoW_QuestEN[35959] = { title = "The Power of Poison", description = "G.V.? We need a full name. A  location!\n\nI have an idea fer how we can find those out.\n\n<Hulda pulls out a small vial.>\n\nThis is my last vial o' wracking poison. We use it when we need tae extract information from prisoners.\n\nCoat yer weapon wi' it and head into the Shattered Hand camp just ahead. Engage them as normal and demand answers - the poison will take care o' the rest.", objectives = "" }
WordHunterWoW_QuestEN[35970] = { title = "Preservation Capitalization", description = "I'm looking for precious artifacts. The kind of artifacts that can help solve some of the greatest mysteries of Draenor, and make the Steamwheedle Preservation Society a ton of moolah. And ladies love the moolah, know what I'm sayin?\n\nSo, get me the artifacts, I'll get the ladies, and you get... wait, what are you looking for again?", objectives = "" }
WordHunterWoW_QuestEN[35972] = { title = "Ogre Onslaught", description = "Those ogres are standing in the way of a full Steamwheedle Preservation excavation.\n\nThey are brutal, violent, horrible smelling beasts. And if I'm being completely honest with myself, I'm pretty mad they broke my glider.\n\nDo me a favor will ya? Wipe 'em off the face of Draenor.\n\nIt will make everyone's life easier, or at the very least, it will make my life easier.", objectives = "" }
WordHunterWoW_QuestEN[35973] = { title = "Brokyo Beatdown", description = "I'm almost done here, but I can't leave in good conscience.\n\nI spotted an ogron named Brokyo that is wearing a priceless ring. Priceless as in crazy expensive.\n\nI'm sure Nixxie will give me a promotion if I bring that ring back to her.", objectives = "" }
WordHunterWoW_QuestEN[35985] = { title = "Garrison Campaign: The Broken Precipice", description = "Hey there! You're the commander of this keep, right? I represent the Steamwheedle Preservation Society.\n\nWe've been trying to get a very important excavation up and running in Nagrand. Unfortunately, we've had trouble with ogres in the area.\n\nIn fact, one of our best preservationists recently went missing while surveying the area. He's the third society member we've lost up there this week!\n\nWe aren't really equipped for a rescue mission... so whad'ya say? We could really use the help.", objectives = "" }
WordHunterWoW_QuestEN[35997] = { title = "Empire's Fall", description = "The Ogre Sorcerer King, Imperator Mar'gok, has mastered magical techniques we would consider on the fringe of arcane science. His felbreakers, among others, can actively dampen or nullify magic. Even fel magic!\n\nIf we're to locate Gul'dan, we need to figure out how it's done. Acquire a felbreaker's tome from his felbreaker captain and acquire the sigil of the sorcerer king himself - I must know what he knows.\n\nYes, {name}, this means I expect you to storm Highmaul and defeat everyone inside. Get to it!", objectives = "" }
WordHunterWoW_QuestEN[35998] = { title = "Legacy of the Sorcerer Kings", description = "For over a thousand years, the ogre sorcerer kings maintained an iron grip over their empire using a variety of artifacts. Trusted lieutenants were given magical gems that allowed them to enforce the emperor's will out in the field. These \"Abrogator Stones\" still maintain their power even today, and can be found scattered throughout the Highmaul complex. Sometimes in clusters.\n\nCollect oa of these Abrogator Stones for me!", objectives = "" }
WordHunterWoW_QuestEN[36004] = { title = "Power Unleashed", description = "You've more than earned a reward, commander. I'll wrap things up here and meet you back at my tower - you can use my portal as a shortcut.\n\nSpeak to me when you arrive and I will use Kairoz's power with the crystals you gathered earlier to upgrade your ring!", objectives = "" }
WordHunterWoW_QuestEN[36005] = { title = "The Scrying Game", description = "We've learned everything we need from the ogres, {name}. Thanks to your efforts, I believe I can pierce the veil of secrecy that's cloaking Gul'dan.\n\nI WILL find him, {class}.\n\nOnce my spell is finished we should be ready to leap into action. I won't begin until you let me know you're ready.", objectives = "" }
WordHunterWoW_QuestEN[36006] = { title = "Hunter: Hunted", description = "The weapon that stabbed the archmage was imbued with fel magic. He's slowly being poisoned!\n\n{name}, we don't have any time. Khadgar will be dead in minutes. I need you to track down Garona before she gets away - find that murder weapon and maybe we can find a cure!\n\nFollow the traces of fel energy she left behind. Track her down into the Zangarra lowlands and capture her with this Violet Hold Incarceration rune.\n\nHurry!", objectives = "" }
WordHunterWoW_QuestEN[36007] = { title = "Touch of the Kirin-Tor", description = "<Khadgar's breathing is labored and his face is drained of color, but his eyes still flash with energy.>\n\nYou saved me, {name}. Once again I underestimated Gul'dan, and it nearly cost me everything.\n\nCome, help me up. While Jaina is here, the two of us can work together to upgrade your ring. You've earned it! Let me know when you're ready.", objectives = "" }
WordHunterWoW_QuestEN[36009] = { title = "Heart of the Fury", description = "It is foolish to pursue Gul'dan with magical means alone. But thanks to you we have a prisoner: Garona. If we can break Gul'dan's mind-control over her, we will learn all his secrets.\n\nI can do it, but I'll need some powerful spell components.\n\nFirst on the list is the heart of an elemental fury. There's one imprisoned in the center of the Blackrock Foundry. Fight your way in, destroy the furnace, and slay the elemental within.", objectives = "" }
WordHunterWoW_QuestEN[36010] = { title = "Flamebender's Tome", description = "The Iron Horde, and the Burning Blade clan in particular, have forged a unique relationship with Draenor's ancient elementals. They can work with iron and flame in ways that even I don't fully understand.\n\nYet.\n\n{name}, slay the Burning Blade's highest-ranking artisan: Flamebender Ka'graz. She is down in the very heart of the Black Forge of the Blackrock Foundry, an area known as the Burning Font. If we're lucky, her secrets are codified in a Flamebender's Tome.", objectives = "" }
WordHunterWoW_QuestEN[36012] = { title = "Reverse Piracy", description = "{name}, during the attack on Karabor Iron Horde dreadnaughts looted or sank most of the draenei eastern fleet. A priceless artifact was captured: A genuine Draenic Thaumaturgical Orb.\n\nI must have it! Those orcs don't know what they've got!\n\nMy sources indicate that the orb was aboard a ship that's being retrofitted down in the Dread Grotto beneath the Blackrock Foundry. Search the ship and the area nearby for the Sha'tari Vault that contained the orb. We've got to get it back!", objectives = "" }
WordHunterWoW_QuestEN[36013] = { title = "Might of the Elemental Lords", description = "Somehow, the Blackrock Clan has forged an alliance with the creatures of fire and stone. I must know how!\n\nSearch the entirety of the Blackrock Foundry. We are looking for stone tablets dating back to the prehistory of Draenor. They will likely be broken apart into fragments that you'll need to assemble by hand. Look for elemental runes carried by high-ranking members of the Iron Horde.\n\nAssemble them and bring me those tablets, {name}. I will use their power to augment the powers of your ring!", objectives = "" }
WordHunterWoW_QuestEN[36014] = { title = "Blackhand's Secret", description = "{name}, you've given me a lot to think about. There's a section of the Flamebender's Tome that speaks about a \"sacrifice,\" and a more recent notation referring to \"the chieftain.\" I think it's talking about Warlord Blackhand.\n\nDid Blackhand sacrifice someone? Himself? A piece of himself? Is that why his hand is deformed?\n\nBefore I risk channeling these elements into a spell, I need to know. And there's only one way to find out.\n\nKill Warlord Blackhand. And bring me his severed arm.", objectives = "" }
WordHunterWoW_QuestEN[36016] = { title = "The Unbroken Circle", description = "Reading these tablets is like stepping back in time to the moment of Draenor's creation. There is a power here greater than any I have dealt with since I was Medivh's apprentice. I believe I can control it, but - can you handle it?\n\nIf you think you are ready, prepare yourself. Hold your ring close to your heart. I will channel pure elemental energies into it.\n\nSpeak with me to begin!", objectives = "" }
WordHunterWoW_QuestEN[36017] = { title = "Prisoner of the Mind", description = "I'd had some time to compare the Flamebinder's tome with the elemental tablets you collected. Where it gets interesting is when I cross-reference the incantations you obtained from the ogre felbreakers... I can see I'm losing you. I will get to the point: I believe I can cast a spell that will nullify Gul'dan's mind control over his assassin Garona.\n\nMind-controlled or not, she may be dangerous, so I won't begin the spell until you're with me. Let me know when you're ready!", objectives = "" }
WordHunterWoW_QuestEN[36018] = { title = "We're Not Finished...", description = "{name}, I'm going to have to hit the books and do more research to figure out how to locate Gul'dan or untangle his mind control of Garona. It's not glamorous, but the life of a mage is often spent in long hours of grueling study.\n\nAs for you, there's much to do. Ensure that your garrison is fully upgraded, locate the best possible equipment, and continue fighting the Iron Horde.\n\nI will summon you when the next step of our journey is ready.", objectives = "" }
WordHunterWoW_QuestEN[36022] = { title = "Extrinsic Motivation", description = "The Shattered Hand aren't strangers to pain. They each cut off their own hand as a sign of their allegiance to Kargath.\n\nIf you're going to get them to talk, it might take more than my poison.\n\nSlaughter them all. We'll see how far they're willing to go for their beloved warlord.", objectives = "" }
WordHunterWoW_QuestEN[36023] = { title = "Extrinsic Motivation", description = "The Shattered Hand are nae strangers tae pain. They each cut off their own hand as a sign o' their allegiance to Kargath.\n\nIf you're going tae get the information we need, it might take more than my poison.\n\nSlaughter them all. We'll see how far they're willing tae go fer their beloved warlord.", objectives = "" }
WordHunterWoW_QuestEN[36027] = { title = "The Staff of Archmage Vargoth", description = "", objectives = "" }
WordHunterWoW_QuestEN[36028] = { title = "Gardul Venomshiv", description = "We need to take out Gardul and take his poison recipe while we still have the element of surprise on our side. We need it to craft the antidote. This may be our only opportunity.\n\nIf what you learned is true, his camp is just south of here. You take him down, and I'll make sure none of his guards interfere.\n\nLet's get moving.", objectives = "" }
WordHunterWoW_QuestEN[36029] = { title = "Gardul Venomshiv", description = "We need tae take out Gardul and take his poison recipe while we still have the element o' surprise on our side. We need the recipe tae figure out the antidote. This may be our only opportunity.\n\nIf what ye learned is true, his camp is just south of here. Ye take him down, and I'll make sure none of his guards interfere.", objectives = "" }
WordHunterWoW_QuestEN[36037] = { title = "A Centurion Without a Cause", description = "", objectives = "" }
WordHunterWoW_QuestEN[36047] = { title = "We Have Him Now", description = "We have Gardul right where we want him, commander.\n\nYou're far more equipped to face him than I am. Dispose of him, take his formula from his corpse, and grab as many barrels of poison as you can.\n\nI'll guard this ramp and make sure no reinforcements come to his aid.", objectives = "" }
WordHunterWoW_QuestEN[36048] = { title = "We Have Him Now", description = "We have Gardul right cornered, commander.\n\nYe have a much better chance against him than me. Take him out, grab the formula from his corpse, and grab as many barrels o' poison as ye can carry.\n\nI'll stay here and make sure nae reinforcements come to Gardul's aid.", objectives = "" }
WordHunterWoW_QuestEN[36054] = { title = "Sealing Fate: Gold", description = "Gold is indeed treasure, but additional treasure for gold?  That's the offer I present.  A Seal of Twisted Fate twists time, providing a burst of additional luck just when you need it.\n\nRemember, you can only obtain three Seals of Twisted Fate per week.  This counts as one of those three.  Next week, I may have others.", objectives = "" }
WordHunterWoW_QuestEN[36055] = { title = "Sealing Fate: Apexis Crystals", description = "You seem like the type who is always seeking power, no? These seals provide an investment, if you will, in your future power.\n\nI also seek power, but one that is a more immediate and tangible. If you manage to find some crystals, we can make a deal. \n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I may have others.", objectives = "" }
WordHunterWoW_QuestEN[36056] = { title = "Sealing Fate: Garrison Resources", description = "That extravagant fortification you built is impressive. Tell me, does it keep all the bad things away? Yes?  How about an exchange for a bit of fate? A wall can be thick enough, but one is never lucky enough. Besides, safety can be so overpriced...\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I may have others.", objectives = "" }
WordHunterWoW_QuestEN[36057] = { title = "Sealing Fate: Honor", description = "To kill another for honor is peculiar...a relic of an older time, perhaps?  No matter, this seal is of no use to me.  It is far too burdened with power for me to control.\n\nRemember, you can only collect three seals per week.  This counts as one of those three.  Next week, I may have others.", objectives = "" }
WordHunterWoW_QuestEN[36059] = { title = "A Worthy Vessel", description = "The time has come, {name}.\n\nAwaken the Talon King from his long slumber. Call him into this world so that he may destroy our enemies!", objectives = "" }
WordHunterWoW_QuestEN[36062] = { title = "Kimzee Pinchwhistle", description = "", objectives = "" }
WordHunterWoW_QuestEN[36075] = { title = "Proof of Strength: Ogron Horn", description = "This horn is proof of your strength at slaying ogron and your gladiator friend has born witness!\n\nTake the horn back to Jonaa and claim your accolades!", objectives = "" }
WordHunterWoW_QuestEN[36076] = { title = "Proof of Strength: Ogron Horn", description = "This horn is proof of your strength at slaying ogron and your gladiator friend has born witness!\n\nTake the horn back to Limbflayer and claim your accolades!", objectives = "" }
WordHunterWoW_QuestEN[36078] = { title = "Proof of Strength: Gronnling Scale", description = "This scale is proof of your strength at slaying ogron and your gladiator friend has born witness!\n\nTake the scale back to Jonaa and claim your accolades!", objectives = "" }
WordHunterWoW_QuestEN[36080] = { title = "Proof of Strength: Gronnling Scale", description = "This scale is proof of your strength at slaying ogron and your gladiator friend has born witness!\n\nTake the scale back to Limbflayer and claim your accolades!", objectives = "" }
WordHunterWoW_QuestEN[36081] = { title = "Proof of Strength: Gronn Eye", description = "This eye is proof of your strength at slaying ogron and your gladiator friend has born witness!\n\nTake the eye back to Jonaa and claim your accolades!", objectives = "" }
WordHunterWoW_QuestEN[36083] = { title = "Proof of Strength: Gronn Eye", description = "This eye is proof of your strength at slaying ogron and your gladiator friend has born witness!\n\nTake the eye back to Limbflayer and claim your accolades!", objectives = "" }
WordHunterWoW_QuestEN[36084] = { title = "Proof of Strength: Botani Bloom", description = "This bloom is proof of your strength at slaying botani and your gladiator friend has born witness!\n\nTake the bloom back to Jonaa and claim your accolades!", objectives = "" }
WordHunterWoW_QuestEN[36085] = { title = "On Ebon Wings", description = "Now we bring our fight to the Adherents. Raastok is certain his new invention will give us control of the Apexis weapons, but we must get close - very close.\n\nKa'alu and her ravens will fly us to the Windswept Terrace. We shall gain a foothold there before pressing on to the Terrace of Dawn.", objectives = "" }
WordHunterWoW_QuestEN[36086] = { title = "Proof of Strength: Botani Bloom", description = "This bloom is proof of your strength at slaying botani and your gladiator friend has born witness!\n\nTake the bloom back to Limbflayer and claim your accolades!", objectives = "" }
WordHunterWoW_QuestEN[36090] = { title = "Proof of Strength: Orc Thorn", description = "This thorn is proof of your strength at slaying the infested and your gladiator friend has born witness!\n\nTake the thorn back to Jonaa and claim your accolades!", objectives = "" }
WordHunterWoW_QuestEN[36091] = { title = "Proof of Strength: Orc Thorn", description = "This thorn is proof of your strength at slaying the infested and your gladiator friend has born witness!\n\nTake the thorn back to Limbflayer and claim your accolades!", objectives = "" }
WordHunterWoW_QuestEN[36092] = { title = "Proof of Strength: Ancient Branch", description = "This branch is proof of your strength at slaying ancients and your gladiator friend has born witness!\n\nTake the branch back to Jonaa and claim your accolades!", objectives = "" }
WordHunterWoW_QuestEN[36094] = { title = "Proof of Strength: Ancient Branch", description = "This branch is proof of your strength at slaying ancients and your gladiator friend has born witness!\n\nTake the branch back to Limbflayer and claim your accolades!", objectives = "" }
WordHunterWoW_QuestEN[36095] = { title = "Azuka Bladefury", description = "Agent Springslip is dead. A fire smolders inside a large wound where his heart used to be.\n\nFlipping through a report you find on his corpse you are able to piece together some basic information. Azuka has betrayed the ogres, she has killed Ugbright and taken his power for herself.\n\nYou should report this information to Bodrick at once.", objectives = "" }
WordHunterWoW_QuestEN[36096] = { title = "Proof of Strength: Ravager Claw", description = "This claw is proof of your strength at slaying ancients and your gladiator friend has born witness!\n\nTake the claw back to Jonaa and claim your accolades!", objectives = "" }
WordHunterWoW_QuestEN[36097] = { title = "Proof of Strength: Ravager Claw", description = "This claw is proof of your strength at slaying ancients and your gladiator friend has born witness!\n\nTake the claw back to Limbflayer and claim your accolades!", objectives = "" }
WordHunterWoW_QuestEN[36098] = { title = "Proof of Strength: Wasp Stinger", description = "This stinger is proof of your strength at slaying ancients and your gladiator friend has born witness!\n\nTake the stinger back to Jonaa and claim your accolades!", objectives = "" }
WordHunterWoW_QuestEN[36100] = { title = "Building for Professions", description = "I see that you have acquired the blueprints for a profession building! Use the Architect Table to build in a small plot.", objectives = "" }
WordHunterWoW_QuestEN[36101] = { title = "Proof of Strength: Wasp Stinger", description = "This stinger is proof of your strength at slaying ancients and your gladiator friend has born witness!\n\nTake the stinger back to Limbflayer and claim your accolades!", objectives = "" }
WordHunterWoW_QuestEN[36103] = { title = "Proof of Strength: Basilisk Scale", description = "This scale is proof of your strength at slaying basilisks and your gladiator friend has born witness!\n\nTake the scale back to Jonaa and claim your accolades!", objectives = "" }
WordHunterWoW_QuestEN[36104] = { title = "Proof of Strength: Basilisk Scale", description = "This scale is proof of your strength at slaying basilisks and your gladiator friend has born witness!\n\nTake the scale back to Limbflayer and claim your accolades!", objectives = "" }
WordHunterWoW_QuestEN[36105] = { title = "Proof of Strength: Elemental Crystal", description = "This crystal is proof of your strength at slaying elementals and your gladiator friend has born witness!\n\nTake the crystal back to Jonaa and claim your accolades!", objectives = "" }
WordHunterWoW_QuestEN[36106] = { title = "Proof of Strength: Elemental Crystal", description = "This crystal is proof of your strength at slaying elementals and your gladiator friend has born witness!\n\nTake the crystal back to Limbflayer and claim your accolades!", objectives = "" }
WordHunterWoW_QuestEN[36107] = { title = "Trophy Hunter of Gorgrond", description = "", objectives = "" }
WordHunterWoW_QuestEN[36108] = { title = "Trophy Hunter of Gorgrond", description = "", objectives = "" }
WordHunterWoW_QuestEN[36117] = { title = "Garrison Campaign: The Broken Precipice", description = "Hey there! You're the commander of this keep, right? I represent the Steamwheedle Preservation Society.\n\nWe've been trying to get a very important excavation up and running in Nagrand. Unfortunately, we've had trouble with ogres in the area.\n\nIn fact, one of our best preservationists recently went missing while surveying the area. He's the third society member we've lost up there this week!\n\nWe aren't really equipped for a rescue mission... so whad'ya say? We could really use the help.", objectives = "" }
WordHunterWoW_QuestEN[36131] = { title = "Proving Your Worth", description = "Now that you have proven yourself as a warrior, let's see how your fishing skills hold up. I have fashioned a bait out of the icespine stingers you brought me. Use it to catch the Zangar eels in these coastal waters.", objectives = "" }
WordHunterWoW_QuestEN[36132] = { title = "Anglin' In Our Garrison", description = "You have proven your worth, traveler.  Now take this frostwolf fishing journal back to your garrison and study up.  You will be catching all you can eat in no time.", objectives = "" }
WordHunterWoW_QuestEN[36134] = { title = "Garrison Campaign: Awakening", description = "We've tracked Warlord Bladefury and the stolen artifact to the salt fields of western Gorgrond.\n\nThisalee Crow will meet you there with an advance scouting team.\n\nThe entire garrison is on high alert. We must be ready to intercept the enemy if necessary.", objectives = "" }
WordHunterWoW_QuestEN[36136] = { title = "Garrison Campaign: Awakening", description = "We've tracked Warlord Bladefury an' da stolen artifact ta northern Gorgrond.\n\nCholuna be dere wit a scouting team.\n\nI got dey entire garrison on high alert. Go, meet wit her, and intercept da enemy if necessary.", objectives = "" }
WordHunterWoW_QuestEN[36137] = { title = "Easing into Lumberjacking", description = "Sir, we're going to need a lot of lumber if we're going to build this garrison into a suitable fortress. That means we're going to have to do a little work.\n\nWhile I certainly wouldn't ask you to dirty your hands with manual labor, I do need you to go out and find timber for our mill. Once you mark a tree an able-bodied lazy-good-for-nothing peon will come and chop it down and give you the timber.\n\nFrostfire isn't the best place for timber, but I did see a suitable small tree nearby.", objectives = "" }
WordHunterWoW_QuestEN[36138] = { title = "Turning Timber into Profit", description = "Now that you know how to put peons to work harvesting timber, we're going to create a work order for your mill.\n\nBut first we're going to need some timber to process!\n\nAll around Draenor are juicy trees ripe for the chopping. Go out and find suitable timber for the lumber mill. Come back here when you have enough and we'll get started on a work order.\n\nAnd as usual, let the peons do the hard work. Just keep 'em protected. Draenor's a dangerous place!", objectives = "" }
WordHunterWoW_QuestEN[36141] = { title = "Icespine Stingers", description = "I will help you, but you are going to need to prove to me that you are not only a worthy fisherman, but also a fearless warrior.\n\nThe canyon north of us is full of icespine stingers.  Slaughter them and bring their stingers back to me.  They should work well as bait in these local waters.", objectives = "" }
WordHunterWoW_QuestEN[36142] = { title = "Sharper Blades, Bigger Timber", description = "Incredible news, Commander {name}. Your ever-loyal servant (that's me) has managed to secure us timber lords. Now maybe you don't know what a timber lord is, so let explain: think of a blood-crazed, mass murderer who enjoys nothing more than killing. Now take that same enthusiasm for killing and apply it to killing trees! That's a timber lord.\n\nWhat this means is that we can now cut medium sized timber - but first we need to give these timber lords a test run.\n\nThere's a suitable tree nearby. Good luck!", objectives = "" }
WordHunterWoW_QuestEN[36160] = { title = "Garrison Campaign: Every Rose Has Its Thorn", description = "These feelings are too strong. I can no longer hide my love away.\n\nI need to tell Thorn the truth. I need to tell Thorn, I love her.\n\nShe mentioned her favorite flower is a rose.  I've been so heads down with my work... I don't even know where I could find a rose on Draenor.", objectives = "" }
WordHunterWoW_QuestEN[36161] = { title = "Where There Is Smoke...", description = "Burning Blade assassins have infiltrated the garrison. We must not let them take the Heart of Gorgorek, commander.", objectives = "" }
WordHunterWoW_QuestEN[36162] = { title = "A Stolen Heart", description = "Don't let Azuka take the heart, commander. Don't let her win.", objectives = "" }
WordHunterWoW_QuestEN[36163] = { title = "Garrison Campaign: The Exarch's Call", description = "Ahhh, just the {race} I were hopin' ta see, my dear.\n\nYrel stopped by the garrison earlier lookin' fer ya. Such a lovely lass, that one! Asked me all about ma family back home when I be feelin' homesick. Bless her. Anyway, what were I goin' on about ag'in?\n\nOh! She asked if ye'd meet her at Elodor to the east.\n\nShe's been invited by the draenei council ta face the Exarch trials, whatever those may be.\n\nAnyway, ye'd better scooch!", objectives = "" }
WordHunterWoW_QuestEN[36164] = { title = "The Trial of Courage", description = "An Exarch must be a pillar of strength, and no greater strength is there than the courage to face danger.\n\nFar to the northwest, among the snowy crags of Frostfire Ridge, lives a primal fury named Everburn.\n\nOnly when you face one of these creatures eye to eye, will you know the extent of your courage.", objectives = "" }
WordHunterWoW_QuestEN[36165] = { title = "No Time to Waste", description = "We're in luck, commander. The antidote is relatively easy tae make.\n\nI've made a small amount with what I had on me. You should take it tae Kolrigg before it's too late. It'll keep him alive long enough for me tae make more.", objectives = "" }
WordHunterWoW_QuestEN[36166] = { title = "No Time to Waste", description = "Commander, we're in luck. The antidote recipe is fairly simple.\n\nI was able to make a small amount with what I had on me. You should take it to Lunzul before it's too late. It should keep her alive long enough for me to make more.", objectives = "" }
WordHunterWoW_QuestEN[36167] = { title = "The Trial of Heart", description = "The Trial of Heart is a test of your willingness to persevere in the face of great adversity.\n\nFar to the west, there is a rangari outpost at Cerulean Lagoon.\n\nThey have sent a request for help. Some sort of infection is making everyone in the area sick. They desperately need aid.\n\nGo and seek out the rangari stationed there. Help them find the cause of this terrible ailment.", objectives = "" }
WordHunterWoW_QuestEN[36168] = { title = "The Trial of Faith", description = "No Exarch trial is complete without a holy pilgrimage to the sacred resting place of our fallen champions.\n\nOn the way, I ask that you take Vindicator Maraad's ashes and lay them to rest within the hallowed halls of Auchindoun.\n\nThere, the spirits of our fallen ancestors will test Yrel's greatest weakness.\n\nGood luck.", objectives = "" }
WordHunterWoW_QuestEN[36169] = { title = "The Trial of Champions", description = "The first three trials you have passed with flying colors.\n\nFor the final trial, you shall face the Exarch Council.\n\nSpeak to me when you are ready to begin.", objectives = "" }
WordHunterWoW_QuestEN[36176] = { title = "A Call for Huntsman", description = "<The note is barely legible, but it seems to be an advertisement for a local hunting competition out of Embaari Village.>\n\n\"Any and all competitors are welcome to test their skills in a friendly hunting challenge.\"", objectives = "" }
WordHunterWoW_QuestEN[36177] = { title = "Friendly Competition", description = "So you wish to join the competition, {name}? Best of luck to you.\n\nBe the first to gather a sack full of hides and talons from local wildlife and return them to me before the other competitors!\n\nWinner earns the opportunity for an apprenticeship under craftsman Garaal.\n\nGood luck!", objectives = "" }
WordHunterWoW_QuestEN[36179] = { title = "Unwanted Pests", description = "Those creatures out in the shallows keep busting the turrets as fast as we can get them operational.\n\nI'm supposed to go clear them out but my blaster is completely busted; the damn thing barely can light a candle like this!\n\nCould you do me a favor and go kill a few of those pests while I get my blaster fixed at the shop?\n\nJust let Gazwitz know you covered for me so I can get reimbursed for the repair.", objectives = "" }
WordHunterWoW_QuestEN[36182] = { title = "Tree-i-cide", description = "Commander, the goblins have brought you a present. They call it the Tree Murderer 9000.\n\nWhat's it do? I reckon it murders trees - but more importantly it will allow for the harvesting of large timber. Do you know how much timber a large tree holds? Me neither, but I bet it's a lot!\n\nThere's a large piece of timber ready to be murdered nearby. Why don't you give the contraption a test run? Bring me back whatever it harvests and I'll put it to good use.", objectives = "" }
WordHunterWoW_QuestEN[36183] = { title = "Admiral Taylor", description = "Admiral Taylor had figured out who was behind all this. He told us to save who we could... he wanted to handle matters himself.\n\nWe never heard from him again, but we have our orders.\n\nPlease... please find him. He went towards the farm.", objectives = "" }
WordHunterWoW_QuestEN[36185] = { title = "Fair Trade", description = "Alright. Here you go.\n\nBe sure to deliver them to Garaal quickly. He has a heavy interest in detail and fine craftsmanship. He'll surely appreciate your work.", objectives = "" }
WordHunterWoW_QuestEN[36189] = { title = "Easing into Lumberjacking", description = "Sir, we're going to need a lot of lumber if we're going to build this garrison into a suitable fortress. That means we're going to have to do a little work.\n\nWhile I certainly wouldn't ask you to dirty your hands with manual labor, I do need you to go out and find timber for our mill. Once you mark a tree a lumberjack will come chop it down and give you the timber.\n\nLet's give our lumberjacks a test run. There's a tree nearby!", objectives = "" }
WordHunterWoW_QuestEN[36192] = { title = "Turning Timber into Profit", description = "Now that you know how to put lumberjacks to work harvesting timber, we're going to create a work order for your mill.\n\nBut first we're going to need some timber to process!\n\nAll around Draenor are juicy trees ripe for the chopping. Go out and find suitable timber for the lumber mill. Come back here when you have enough and we'll get started on a work order.\n\nAnd as usual, let the lumberjacks do the hard work. Just keep 'em protected. Draenor's a dangerous place!", objectives = "" }
WordHunterWoW_QuestEN[36193] = { title = "An Act of Kindness", description = "I know that you and Vindicator Yrel are here on important matters, but I must ask you a favor.\n\nA squad of rangari left on patrol just before the poisonous mist set in.\n\nIf they were caught out in the swamp, they are surely in trouble.\n\nHarvest the Restorative Goldcaps growing among the reeds, and use them to restore any fallen rangari that you find.\n\nIf you find yourself in trouble, eat one to combat the poison.", objectives = "" }
WordHunterWoW_QuestEN[36194] = { title = "Sharper Blades, Bigger Timber", description = "Incredible news, Commander {name}. Your ever-loyal servant has managed to secure us commandojacks. Now maybe you don't know what a commandojack is, so let me explain: they're like lumberjacks, only highly trained in the art of killing. Mostly they're out of work mercenaries and assassins.\n\nWhat this means is that we can now cut medium sized timber - but first we need to give these commandojacks a test run.\n\nThere's a suitable tree nearby. Good luck!", objectives = "" }
WordHunterWoW_QuestEN[36195] = { title = "Tree-i-cide", description = "Commander, your engineers have brought you a present. They call it the Wood Annihilator XXI the Third, Jr.\n\nWhat's it do? I reckon it annihilates trees - but more importantly it will allow for the harvesting of large timber. Do you know how much timber a large tree holds? Me neither, but I bet it's a lot!\n\nThere's a large piece of timber ready to be annihilated nearby. Why don't you give the contraption a test run? Bring me back whatever it harvests and I'll put it to good use.", objectives = "" }
WordHunterWoW_QuestEN[36199] = { title = "Moonshell Claws", description = "I will help you, but you are going to need to prove to me that you are not only a worthy fisherman, but also a fearless warrior.\n\nThe beach southeast of us is full of moonshell crawlers.  Slaughter them and bring their claws back to me.  They should work well as bait in these local waters.", objectives = "" }
WordHunterWoW_QuestEN[36201] = { title = "Proving Your Worth", description = "Now that you have proven yourself as a warrior, let's see how your fishing skills hold up. I have fashioned a bait out of the moonshell claws you brought me. Use it to catch the shadow sturgeon in these coastal waters.", objectives = "" }
WordHunterWoW_QuestEN[36202] = { title = "Anglin' In Our Garrison", description = "You have proven your worth, traveler.  Now take this eventide fishing journal back to your garrison and study up.  You will be catching all you can eat in no time.", objectives = "" }
WordHunterWoW_QuestEN[36205] = { title = "The Fractured Hammer", description = "It is obvious that this elaborate smithing hammer has seen better days.\n\nNow fractured and dirty, it is merely a shadow of its former self.\n\nOne thing is certain, its previous owner was neither ogre nor Iron Horde.\n\nPerhaps someone at Stonefang Outpost would know who this belongs to.", objectives = "" }
WordHunterWoW_QuestEN[36207] = { title = "Waruk the Frostforger", description = "Many say my father was a legendary blacksmith, Waruk the Frostforger they called him. They will tell you tales of his mighty weapons, crafted with nothing more than ice and steel. Waruk the Lieforger, I call him.\n\nHe promised he wouldn't be gone long, \"I must support our troops!\" he said.\n\nWhy did he have to go? Why did they let him get captured!?\n\nI have no more need for broken tools than I do broken promises. His grave is east of here, you can leave this with the rest of his unwanted belongings.", objectives = "" }
WordHunterWoW_QuestEN[36208] = { title = "The Crystal Shard", description = "I'm glad you arrived when you did.\n\nThe Laughing Skull orcs practice some strange spirit magic, but one of their traditions could be quite useful in our situation.\n\nWhile I make preparations, can you gather the reagents?\n\nFirst, we'll need crystals from the husks of goren corpses. You can find their bodies in the canyon.", objectives = "" }
WordHunterWoW_QuestEN[36209] = { title = "What's Under There?", description = "It is done.\n\nWith this enchantment, not only can you roam amongst the goren freely, but you can move as they do.\n\nYour travels through the canyon are now made easier. You have safe access to places otherwise impossible to reach.\n\nPerhaps these tunnels will lead to more information that could be used against the Iron Horde.", objectives = "" }
WordHunterWoW_QuestEN[36210] = { title = "Hard Shell", description = "I have already learned much from watching the Laughing Skull.\n\nTraveling through goren tunnels was thought to be impossible due to the acid they leave behind, but the orcs found a way around it.\n\nWe will need some of the shells of goren within the canyon.\n\nIf you see any of their tunnel craters ready to burst, approach them and goren will come pouring out. This way, you can kill many at once and find the shells more quickly.", objectives = "" }
WordHunterWoW_QuestEN[36219] = { title = "Garrison Campaign: The Ring of Blood", description = "Hey Champ,\n\nYou were out when I stopped by. I've got a sweet gig set up at the Ring of Blood in Nagrand. Lots of ogres looking for the next big fight. Big money. You in?\n\nWho am I kidding, who wouldn't be interested in fame, fortune, and brawlin'? I'll meet you at my stash so we can talk a bit in private before your big debut.\n\n<A map is included with a dollar sign scrawled on an abandoned ogre tower.>", objectives = "" }
WordHunterWoW_QuestEN[36220] = { title = "How Tough Are You?", description = "Mogor's holding a special match over at the Ring of Blood to crown the new Blood Champion and I think you have what it takes!\n\nNow, these ogres respect one thing and one thing only: badass...ness. They have a big fella at the front door making sure only the toughest gladiators enter the proving grounds.\n\nIf you're in, kill the grizzled gladiator Lug'dol at the tower just up the road and present his head to Kroggol the Wall. That oughta show 'em what you're made of.", objectives = "" }
WordHunterWoW_QuestEN[36221] = { title = "Entry Fee", description = "You looking for da Ring of Blood? HAH! That good one. Not just anybody able to compete in da ring. You gotta pay the entry fee: fifty blood marks.\n\nHow do you get them? Oh, tiny one, you killing me!\n\n<Kroggol hands you a small stone caked in blood.>\n\nDat one is yours. You kill others in da proving grounds to get da rest. Take dem to Wodin da troll servant by Mogor when you done.\n\nDon't talk to Mogor, though. Mogor da boss.", objectives = "" }
WordHunterWoW_QuestEN[36222] = { title = "The Champion of Blood", description = "You have da blood stones required as proof of your worth. Hmm. Yes, you might be da champion Mogor be lookin' for.\n\nYou be one of only two to complete da blood stone trial. Da two of ya be fightin' for da glory of becoming Blood Champion.\n\nSpeak to Gurgthock and we be seein' if you be a champion... or just another stain on da arena floor.", objectives = "" }
WordHunterWoW_QuestEN[36223] = { title = "Leave Every Soldier Behind", description = "The ogron possess something of value to the Iron Horde. I am sure they're unaware, likely just bored and in need of something to torture.\n\nWe could simply leave them to their fate, but we should follow up on this clue. With any luck, it will help us stop the Iron Horde from turning Gorgrond's most fearsome creatures into weapons.\n\nTry to find Corporal Thukmar and his notes.", objectives = "" }
WordHunterWoW_QuestEN[36230] = { title = "The Restless Spirit", description = "This hammer was once used to craft magnificent weapons for my Frostwolf brothers and sisters.\n\nWhen I was taken prisoner by the Thunderlords, however, I refused to wield it. How could I craft weapons to be used against my own people?\n\nIt saddens me to see that it has been damaged and abused.\n\nI wished to one day pass it down to Kugra, but now, her anger prevents her from even visiting my grave.\n\nPlease {name}, can you help me repair my hammer and seek revenge on those that caused this?\n\nFor Kugra....", objectives = "" }
WordHunterWoW_QuestEN[36236] = { title = "The Cryptic Tome of Tailoring", description = "The different sections of the tome describe tailoring techniques that seem strange compared to traditional methods.\n\nThe author's name does not appear anywhere in the tome. Maybe someone in your garrison knows more about the book's origins.", objectives = "" }
WordHunterWoW_QuestEN[36238] = { title = "Mending A Broken Heart", description = "{name}, thank you for avenging my death... but I have just one more favor to ask of you.\n\nIf you help me see this through, I will forever be in your debt.\n\nTake these items and meet me at the forge in Stonefang Outpost.\n\nI have imbued them with a portion of my essence, but we still need the aid of another to reforge the hammer.\n\nIt is time for me to reconcile with Kugra, so that we both may finally find peace....", objectives = "" }
WordHunterWoW_QuestEN[36239] = { title = "A Mysterious Satchel", description = "An empty satchel with an old, magical aura.\n\nIt appears quite dilapidated, with remnants of herbs and mushrooms along the inner lining. Perhaps exploring Umbrafen will offer a clue.", objectives = "" }
WordHunterWoW_QuestEN[36240] = { title = "Slow and Steady", description = "Excellent!\n\nWhen you've collected enough herbs from the local wildlife, return to me and I'll craft them into an ink for Master Ardule.\n\nThe sporebats and giants should have what you're looking for.\n\nAnd remember, be careful!", objectives = "" }
WordHunterWoW_QuestEN[36241] = { title = "The Power of Preservation", description = "The ink is very precious to our people. It has the ability to preserve ancient texts.\n\nMaster Ardule can explain further. He's just inside.", objectives = "" }
WordHunterWoW_QuestEN[36242] = { title = "Where There Is Smoke...", description = "You garrison is under attack by the Burning Blade!\n\nKill the Burning Blade masters that are leading the assault and report back to Warmaster Zog.", objectives = "" }
WordHunterWoW_QuestEN[36248] = { title = "A Stolen Heart", description = "This invasion is clearly an attempt to seize the Heart of Gorgorek.\n\nWe need to fortify our guard before it's too late!", objectives = "" }
WordHunterWoW_QuestEN[36255] = { title = "Enchanted Highmaul Bracer", description = "A powerful enchantment emanates from these ancient Highmaul bracers.\n\nMaybe Yu'rina the Mystic, your garrison enchanting quartermaster, can tell you more about the bracer.", objectives = "" }
WordHunterWoW_QuestEN[36256] = { title = "The Arakkoan Enchanter", description = "The arakkoa said it was going to investigate an anomaly in the Cracking Plains that might be related to another armor piece.", objectives = "" }
WordHunterWoW_QuestEN[36257] = { title = "Failed Apprentice", description = "Oru'kai was the first ogre mage to master the art of enchanting. Upon his death, his items were scattered across Draenor. I have tracked his scepter to the field you see before us. \n\nAs you can see, the scepter's enchantment is making it difficult to retrieve. A would-be apprentice, Torag Stonefury, took one of Oru'kai's rings in to break the enchantment, but he failed and became trapped in ice. \n\nFree Torag, take the ring, and complete his task, and I will consider a reward.", objectives = "" }
WordHunterWoW_QuestEN[36260] = { title = "Oru'kai's Scepter", description = "If I had known being an enchanter was this dangerous, I would have stayed in Wor'gol. \n\nHere, take this ring. The bird man told me to use the ring on the scepter to nullify the enchantment.\n\nBring the scepter back to him and maybe he will teach you what he promised to teach me.", objectives = "" }
WordHunterWoW_QuestEN[36261] = { title = "Garrison Campaign: Missing Grunt", description = "With the Heart of Gorgorek residing inside the garrison walls, we need to stay vigilant. The Burning Blade are known for attacking swiftly, and without warning.\n\nI have a number of grunts patrolling the keep. Dul'zak, one of our newer recruits, should have reported back by now.", objectives = "" }
WordHunterWoW_QuestEN[36262] = { title = "Ameeka, Master Tailor", description = "Ameeka created this book to document and pass down our most cherished crafting techniques to our children. She must have dropped it while traveling. She will be relieved to see her book.\n\nFrom what I have heard from other villagers, she was last seen on the road to Elodor. Perhaps you can find her there.", objectives = "" }
WordHunterWoW_QuestEN[36266] = { title = "The Clothes on Their Backs", description = "Such kindness you have shown me, perhaps I can ask for one more?\n\nIn our village, we salvage and reuse old cloth to patch clothes and light armor. Sadly, most of my supply was taken or destroyed in the recent attacks.\n\nThe Shadowmoon cultists might think twice about stealing from us if you were to relieve them of their own resources.\n\nIf you can collect some ceremonial Shadowmoon robes for me, I will demonstrate some of my favorite tailoring techniques for you.", objectives = "" }
WordHunterWoW_QuestEN[36269] = { title = "Hexcloth", description = "I shall now impart to you the finer points of creating hexcloth.\n\nThe process is quite simple. It involves immersing carefully woven fur into the ichor drawn from Gorgrond Flytraps.\n\nNormally, you would need to harvest it yourself, but I actually managed to liberate some from the Shadowmoon during their last raid.\n\nYou are welcome to use it.", objectives = "" }
WordHunterWoW_QuestEN[36271] = { title = "Breaking into the Trap Game", description = "When we came through the portal, we weren't able to bring any of our animals with us. For us to produce leather and furs, we'll need to trap some of the native beasts and bring them back here.\n\nWe can get a load of leather from the elekk, or furs from the talbuk, right here in Shadowmoon.\n\nTake this iron trap and use it on a wounded adult talbuk or elekk, then bring the trap on back here and we'll start a work order.", objectives = "" }
WordHunterWoW_QuestEN[36272] = { title = "Feeding An Army", description = "We've had a chance to work with these beasts for a while now, and that's allowed us to develop a brand-new trap for you to try out. It should be much sturdier than the last one!\n\nMind giving 'er a run, commander? The Improved Iron Trap will let you capture some of the meatiest wildlife, like the big boars and riverbeasts out in Gorgrond. We'll be able to turn them into some tasty steaks.", objectives = "" }
WordHunterWoW_QuestEN[36273] = { title = "Whacking Weeds", description = "Something needs to be done about the podling menace in Spiteleaf Thicket!\n\nAlongside Hemet Nesingwary, I've hunted some of the largest and most terrifying beasts around. Never in my life have I encountered a creature as vile, depraved, nefarious or degenerate as a podling!\n\nThe vicious little monsters spread themselves like weeds and if something isn't done, they'll spread across the entire continent!\n\nMake your way into Spiteleaf Thicket and slay as many podlings as you can find!", objectives = "" }
WordHunterWoW_QuestEN[36274] = { title = "Bigger Trap, Better Rewards", description = "Good news, commander! With the materials we've gathered here in Draenor, we've been able to construct a trap strong enough to immobilize even the mightiest beast!\n\nWhy don't you head on out to Nagrand and give it a try? Word has it that the western plains are home to some of the most magnificent beasts this side of Crystal Lake.\n\nI'm going to warn you, though, these beasts are tough. You may want to bring some friends along.", objectives = "" }
WordHunterWoW_QuestEN[36275] = { title = "The Search For Research", description = "My research notes are missing!\n\nThey must have gone missing during the podling attack on the research station. All of my work will be lost if they are not found!\n\nCome to think of it, I'm also missing my expedition supply bag, as well as my anti-fungal boots....\n\nHow can I do biological research without my equipment?!\n\nNo... this will not do at all.\n\nPlease, go and search the Zangar Shore for my missing belongings so that I may continue my fungal research!", objectives = "" }
WordHunterWoW_QuestEN[36280] = { title = "Garrison Campaign: The Ring of Blood", description = "Hey Champ,\n\nYou were out when I stopped by. I've got a sweet gig set up at the Ring of Blood in Nagrand. Lots of ogres looking for the next big fight. Big money. You in?\n\nYou're the one that brought a new meaning to pain at the Ring of Trials not too long ago, right? This is the next step in your climb to fame! You've gotta get down here.\n\nI'll meet you at my stash so we can talk a bit in private before your big debut.\n\n<A map is included with a dollar sign scrawled on an abandoned ogre tower.>", objectives = "" }
WordHunterWoW_QuestEN[36281] = { title = "Garrison Campaign: The Ring of Blood", description = "Hey Champ,\n\nYou were out when I stopped by. I've got a sweet gig set up at the Ring of Blood in Nagrand. Lots of ogres looking for the next big fight. Big money. You in?\n\nIf you think the Stonemaul arena was a thrill, this is way, way bigger than that. It's going to be HUGE, I'm calling it now.\n\nI'll meet you at my stash so we can talk a bit in private before your big debut.\n\n<A map is included with a dollar sign scrawled on an abandoned ogre tower.>", objectives = "" }
WordHunterWoW_QuestEN[36282] = { title = "Garrison Campaign: The Ring of Blood", description = "Hey Champ,\n\nYou were out when I stopped by. You're the talk of the arena, friend! I mean, the Ring of Trials? Stonemaul? You're killing it out there!\n\nI've got a sweet gig set up at the Ring of Blood in Nagrand. Lots of ogres looking for the next big fight. Big money. You in?\n\nI'll meet you at my stash so we can talk a bit in private before your big debut.\n\n<A map is included with a dollar sign scrawled on an abandoned ogre tower.>", objectives = "" }
WordHunterWoW_QuestEN[36284] = { title = "A Fascinating Fungus", description = "The Zangar Shore is home to many peculiar strains of fungi, some of which are similar to those of our native Azeroth. However, one strain in particular is most fascinating!\n\nI call it \"Zangarium Draenormycota,\" due to its prevelance in Draenor's fungal ecosystem. This unique strain of fungus is highly adaptable and can be found on many of the living organisms throughout Zangar Shore.\n\nWhy does it exist? What properties does it hold?\n\nTo answer these questions, I will need additional spore samples.", objectives = "" }
WordHunterWoW_QuestEN[36285] = { title = "Dirgemire", description = "In order to fully understand the nature and properties of the Zangarium Draenormycota, I need to examine the strain within a complex fungal structure. The fungal brain of a spore giant would do nicely.\n\nNot just any spore giant will serve though, it needs to be big... mean... primordial... the perfect specimen!\n\nIn a cavern deep below the surface is an ancient spore giant the locals fearfully refer to as Dirgemire. Slay the monster, but be sure to carefully preserve the fungal brain for our research!", objectives = "" }
WordHunterWoW_QuestEN[36286] = { title = "Transponder 047-B", description = "The back of the transponder is etched in scribbled writing.\n\n<URGENT: If found, please return to Goggles near Eledor. It is of the utmost importance!>\n\n", objectives = "" }
WordHunterWoW_QuestEN[36287] = { title = "Snatch 'n' Grab", description = "We were able to map all of the data from the transponder you recovered! Now our location analyzer is complete!\n\nWe're just missing a few final pieces, then the real testing begins.\n\nOne of my pilots mentioned seeing a beached Iron Horde ship over by the shore. If you can salvage some parts we may just be able to get this thing up and running!", objectives = "" }
WordHunterWoW_QuestEN[36289] = { title = "Out of the Shadows", description = "Congratulations again, Blood Champion. You be fightin' like nobody I ever seen.\n\nWhile you were in da ring, one ayour bruddas came by and asked for you ta return ta your base. He called himself Bodrick Grey.", objectives = "" }
WordHunterWoW_QuestEN[36290] = { title = "Out of the Shadows", description = "Congratulations, Blood Champion. You be fightin' like nobody I ever seen.\n\nWhile you were in da ring, one a your bruddas came by and asked for you ta return ta your base. He called himself a shadow hunter.", objectives = "" }
WordHunterWoW_QuestEN[36292] = { title = "Investigating the Invasion", description = "I'm going to lead a small squad behind enemy lines.\n\nMeet me by Dreadmaul, {class}. From there we can decide our next course of action.", objectives = "" }
WordHunterWoW_QuestEN[36294] = { title = "Phylarch the Evergreen A", description = "", objectives = "" }
WordHunterWoW_QuestEN[36295] = { title = "Phylarch the Evergreen B", description = "", objectives = "" }
WordHunterWoW_QuestEN[36296] = { title = "Phylarch the Evergreen", description = "[PHYLARCH ACQUISITION TEXT GOES HERE]", objectives = "" }
WordHunterWoW_QuestEN[36301] = { title = "Trega's Tailoring Kit", description = "The bag is filled with patterns and unfamiliar tailoring tools. You find the name \"Trega\" embroidered on the inside of the bag.\n\nYou seem to recall seeing her in Wor'gol. With any luck, she's still there.", objectives = "" }
WordHunterWoW_QuestEN[36307] = { title = "Investigating the Invasion", description = "I'm going to lead a small squad behind enemy lines.\n\nMeet me by Dreadmaul, {class}. From there we can decide our next course of action.", objectives = "" }
WordHunterWoW_QuestEN[36308] = { title = "Enchanted Highmaul Bracer", description = "A powerful enchantment emanates from these ancient Highmaul bracers.\n\nMaybe Eileese Shadowsong, your garrison enchanting quartermaster, can tell you more about the bracer.", objectives = "" }
WordHunterWoW_QuestEN[36309] = { title = "The Strength of Iron", description = "A stitched patch along the side of the satchel clearly identifies its owner.\n\nYou remember hearing stories of a great blacksmith just north of Embaari.", objectives = "" }
WordHunterWoW_QuestEN[36310] = { title = "The Arakkoan Enchanter", description = "The arakkoa said it was going to investigate an anomaly along the Forgotten Shore that might be related to another armor piece.", objectives = "" }
WordHunterWoW_QuestEN[36311] = { title = "Father and Son", description = "Please find my boy!\n\nBefore the looters came we were on the hill just northeast of here.\n\nThere weren't many of them, but I'm a blacksmith, not a fighter!\n\nHave I let my only son down?", objectives = "" }
WordHunterWoW_QuestEN[36313] = { title = "Failed Apprentice", description = "Oru'kai was the first ogre mage to master the art of enchanting on Draenor. Upon his death, his items were scattered across Draenor. I have tracked his staff to the shore you see before us. \n\nAs you can see, the staff's enchantment is making it difficult to retrieve. A would-be apprentice, Deema, took one of Oru'kai's rings in to break the enchantment, but she failed and became trapped as well. \n\nFind and free Deema, take the ring, complete her task, and I will consider a reward.", objectives = "" }
WordHunterWoW_QuestEN[36314] = { title = "The Intricate Pendant", description = "The crimson gem used in this pendant is unlike any you've seen before, and the filigree wrapped around it is masterfully crafted.\n\nThere's likely to be much you can learn from the person who made this. Perhaps someone at your garrison will recognize the work.", objectives = "" }
WordHunterWoW_QuestEN[36315] = { title = "Oru'kai's Staff", description = "If I had known being an enchanter was this dangerous, I would have stayed in Shattrath. \n\nHere, take this ring. The arakkoa told me to use the ring on the staff to nullify the enchantment.\n\nBring the scepter back to him and maybe he will teach you what he promised to teach me.", objectives = "" }
WordHunterWoW_QuestEN[36316] = { title = "Victory is Within Reach", description = "We have dealt a crippling blow to the Adherents, but our fight is not yet finished.\n\nGather your allies and prepare for the final siege on Skyreach!\n\n\"Shadows gather when the raven swallows the day.\n\nBurning sky is extinguished as black wings fold gently about the heavens.\n\nRest, my children, rest. For even the sun must sleep.\"\n\nThis was Rukhmar's lullaby, sung by her to the first arakkoa. My, how we've lost our way.", objectives = "" }
WordHunterWoW_QuestEN[36341] = { title = "Primal Fury", description = "It looks like this is it, commander.\n\nWe must stop the Iron Horde at all costs. I have sent stormcrows to your garrison, and called for Bodrick Grey to deploy your troops to the Gates of Tanaan at once.\n\nBy the time you get to northern Talador, he should be waiting for you... with an entire army.\n\nThere is no time to delay.", objectives = "" }
WordHunterWoW_QuestEN[36342] = { title = "Primal Fury", description = "It looks like this is it, commander.\n\nWe must stop the Iron Horde at all costs. I have sent stormcrows to your garrison, and called for Shadow Hunter Rokhan to deploy your troops to the Gates of Tanaan at once.\n\nBy the time you get to northern Talador, he should be waiting for you... with an entire army.\n\nThere is no time to delay.", objectives = "" }
WordHunterWoW_QuestEN[36344] = { title = "Feeding An Army", description = "We've had a chance to work with these beasts for a while now, and that's allowed us to develop a brand-new trap for you to try out. It should be much sturdier than the last one.\n\nThe Improved Iron Trap will let you capture some of the meatiest beasts on Draenor. You will find that a single riverbeast or boar from Gorgrond can feed many warriors.\n\nTrap one and bring it back, and we will cook you a savage meal.", objectives = "" }
WordHunterWoW_QuestEN[36345] = { title = "Breaking into the Trap Game", description = "When we came through the portal, we weren't able to bring any of our animals with us. For us to produce leather and furs, we'll need to trap some of the native beasts and bring them back here.\n\nAlthough the plains are frozen, there are many clefthooves and wolves in Frostfire. We can gather leather from the clefthooves, or furs from the wolves.\n\nTake this iron trap and use it on a wounded adult beast. Bring the trapped creature back to us, and we will begin our work.", objectives = "" }
WordHunterWoW_QuestEN[36346] = { title = "Bigger Trap, Better Rewards", description = "Ah, commander, it is good to see you again. With the materials we have gathered here in Draenor, we have been able to construct a trap strong enough to immobilize even the mightiest beast.\n\nThese enormous creatures can be found on the western side of Nagrand, among the most fertile plains.\n\nA word of warning: these beasts are great and powerful. You may want to bring some friends along.", objectives = "" }
WordHunterWoW_QuestEN[36352] = { title = "Locating the Lapidarist", description = "Are you sure I can't take this off your hands? I'll give you a fair price!\n\nAlright, alright... if you insist on finding the owner, you might want to try visiting Wor'gol.\n\nRumor has it there is a master craftsman there who's skilled in manipulating precious metals and stones. Might be your guy.", objectives = "" }
WordHunterWoW_QuestEN[36353] = { title = "For Old Times' Sake", description = "", objectives = "" }
WordHunterWoW_QuestEN[36368] = { title = "Lost Lumberjack", description = "All o' them mole machines got mighty unreliable here in Gorgrond. I hear tell that one of 'em might've crashed here in Tangleheart.\n\nSee if you can find Frenna. She would've been on the one we tracked to this location. I'll go lookin' for the mole machine to see if it can be repaired.", objectives = "" }
WordHunterWoW_QuestEN[36378] = { title = "No Pressure, No Diamonds", description = "You wish to understand the secrets of our gems, {race}? In exchange for returning my pendant, I am willing to help.\n\nI must warn you, however, that the materials will not be easy to obtain.\n\nTo the north, you will find magma pools that give birth to living lava creatures. Contained within these, you may find magnificent diamonds.\n\nPlease return to me with a few of these diamonds...", objectives = "" }
WordHunterWoW_QuestEN[36379] = { title = "Peeking into the Portal", description = "I sent Scout Pazerp to get a better look at the portal. She should have reported back by now; what could be taking her so long?\n\nShe is one of my best scouts, I hope she is alright.", objectives = "" }
WordHunterWoW_QuestEN[36380] = { title = "Diamonds Are Forever", description = "Please watch closely {name}. I shall craft this jewel into a fine pendant for you.\n\nHopefully you will learn a bit of true jewelcrafting in the process.", objectives = "" }
WordHunterWoW_QuestEN[36382] = { title = "Peeking into the Portal", description = "I sent Scout Pazaztick to be gettin' a better look at da portal. He shoulda reported back by dis time; what be taking him so long?\n\nDis is what happens when you hire da goblins as help.", objectives = "" }
WordHunterWoW_QuestEN[36384] = { title = "Field Trial", description = "Look, I didn't tell Kimzee about this because I don't want to hurt her feelings, I chose not to leave Pinchwhistle Point.\n\nSee, I've been working on a serum that I think should be able to cure the infected, but when I tried to test it I got surrounded and I injured my leg during the escape.\n\nI know I'm on the right track but I need to test it. Do me a favor and take this vial and go try it out on one of the infected outside.", objectives = "" }
WordHunterWoW_QuestEN[36385] = { title = "Legacy of the Ancients", description = "Opening the ancient tome you see that it's not actually a tome at all, but a container. Inside are four empty slots.\n\nUpon closer inspection each slot has next to it a carving of what appears to be a unique Draenor ancient, some glyphs and a receptacle used to hold a piece of the pictured ancient. There also appear to be directions to where these ancients may be found: medium timber -- Shadowmoon, Gorgrond, the Spires of Arak and Nagrand.\n\nThese are assassination instructions. From trees to kill trees.", objectives = "" }
WordHunterWoW_QuestEN[36404] = { title = "Clearing the Garden", description = "This clearing is the perfect spot to grow herbs for our Garrison, there is just one little problem.  All these dang raccoons!\n\nI need you to clear them out and we can get this garden growing.", objectives = "" }
WordHunterWoW_QuestEN[36408] = { title = "A Power Lost", description = "<The fragment gleams in the light as its aura's final pulse fades.>\n\nThe power within the fragment appears to be drained.\n\nYou recall hearing travelers speak of a local in Embaari Village who specializes in imbuing gems with magic.", objectives = "" }
WordHunterWoW_QuestEN[36409] = { title = "Restoration", description = "As mentioned, our larger defense crystals have been drained of power, creating gaps in our defenses. The crystal you brought me is only a reminder of the severity of this situation. It's Shadowmoon magic to blame, I'm sure of it.\n\nOne of our rangari scouts spotted an orc fleeing north, past Palemoon Village, and into the valley beyond. Go, find this orc, and see if you can't retrieve whatever vessel he's storing the power inside of. If we get it back, I'm sure I can restore the crystals.", objectives = "" }
WordHunterWoW_QuestEN[36417] = { title = "From Their Cold Dead Hands", description = "Those ogres took all of my hexweave!\n\nI kept it hidden at the bottom of my bag. How could they possibly know of its importance?\n\nIf they discover even a portion of hexweave's properties, it means trouble for us all.\n\n{name}, this is a Frostwolf problem. It requires a Frostwolf solution.\n\nWill you help me?", objectives = "" }
WordHunterWoW_QuestEN[36419] = { title = "Dyed in the Fur", description = "I can't believe they tried to physically rip the magic out of the material!\n\nIt seems we were never in danger of my secrets falling into the wrong hands after all. Better safe than dead...\n\nIn return for your help, I will share with you my methods of fusing magic to cloth.\n\nFlytrap Ichor is very rare in this region, but I do have a bit in reserve. Take this woven fur and dip it in the ichor here. You will see for yourself what all of the fuss is about.", objectives = "" }
WordHunterWoW_QuestEN[36423] = { title = "Pets Versus Pests", description = "I've been trying to get this place ready for your pets, but we've uncovered some rude pests while building the garrison.  I tried to take care of them myself, but they are too tough for my meager team.\n\nThere's an angry carrot in the garden, an enormous rat eating our food rations, and an ornery water creature harassing the fishermen.  If you can take care of them, I'll be free to finish up my work on your menagerie.", objectives = "" }
WordHunterWoW_QuestEN[36425] = { title = "Egg Punt", description = "<A sweaty, pulsing egg - no doubt flush with ravager larvae.\n\nA swift kick should take care of these.>", objectives = "" }
WordHunterWoW_QuestEN[36427] = { title = "The Rise and Fall of Barov Industries: Alexi Barov", description = "[PHYLARCH ACQUISITION TEXT GOES HERE]", objectives = "" }
WordHunterWoW_QuestEN[36428] = { title = "Curing With Force", description = "The infection is getting stronger so I made some adjustments and I'm pretty sure I have the right formula now.\n\nIt should now work but it needs to have less competition with the infected blood for it to have any effect.\n\nThis means you will need to weaken them before you apply the serum for it to function properly.\n\nThe infection is getting more advanced and will soon be untreatable so we have this one shot to save as many as we can.", objectives = "" }
WordHunterWoW_QuestEN[36429] = { title = "The Rise and Fall of Barov Industries: Weldon Barov", description = "[PHYLARCH ACQUISITION TEXT GOES HERE]", objectives = "" }
WordHunterWoW_QuestEN[36432] = { title = "Seeking the Scout", description = "We are still trying to locate all of our scouts out in the field. One of these, Altauur, enjoys handling the more dangerous missions.\n\nHe has not checked in and I feel we should check to make sure he has not taken on more than he can handle.", objectives = "" }
WordHunterWoW_QuestEN[36434] = { title = "Penny From Heaven", description = "<Durotan looks at you curiously.>\n\nThose from your world are not much for subtlety, are they?\n\nGo on ahead and greet our new companion. We will join you as soon as we can make ready.", objectives = "" }
WordHunterWoW_QuestEN[36435] = { title = "Unintelligible Intelligence", description = "The notes are unreadable, but based on previous experience, the text appears to be very similar to standard Orcish.\n\nIt is possible that the notes could contain strategic information. Perhaps it would be of great value to the Frostwolf Orcs.\n\nSomeone in Wor'gol might be able to help interpret the text.", objectives = "" }
WordHunterWoW_QuestEN[36436] = { title = "Plant Pruning", description = "There may be more to this aberrant growth than it seems, but we will need to clear the way a bit before we can get to the bottom of this, yes?\n\nI suggest clearing out some of the angrier defenders to be on the safe side.", objectives = "" }
WordHunterWoW_QuestEN[36437] = { title = "Ambassador to the Ancient", description = "It appears that a genesaur was killed here not long ago and this growth has sprung up.  It is stirring up the local monsters and I fear for our outpost.\n\nThere is a strange ancient that wallows in grief here and is not hostile. Perhaps you could \"harvest\" its story?", objectives = "" }
WordHunterWoW_QuestEN[36438] = { title = "Beatface vs. Boulder", description = "The saberon took their treasure up the rise and barricaded themselves in after Birchus attacked. It will be difficult to get in but I hear you have resources to handle this.\n\nOne of their entrances is covered with a large boulder. Too large for you or I, but perhaps an ogre with a large enough hammer could break it. I think you know who I am talking about...", objectives = "" }
WordHunterWoW_QuestEN[36439] = { title = "Shredder vs. Saberon", description = "The saberon took their treasure up the rise and barricaded themselves in after Birchus attacked. It will be difficult to get in but I hear you have resources to handle this.\n\nOne of their entrances is covered with tough vegetation. I believe you have a mechanical solution to this problem in the form of a shredder. I think you know what to do...", objectives = "" }
WordHunterWoW_QuestEN[36440] = { title = "Saberon Population Reduction", description = "We are closer to our goals but a host of sharp toothed saberon bar our way.\n\nIf we are to get anywhere up here, some of the more aggressive ones will need to be put down I think.", objectives = "" }
WordHunterWoW_QuestEN[36441] = { title = "Reclaiming Property", description = "You are attracted by a low green glow to the container.  Inside there is a glowing bundle of herbs that was most likely stolen from the overgrowth below.\n\nIt would be best to collect all of these so the saberon don't continue their dabbling in plant magic and irritating the nearby magnaron.", objectives = "" }
WordHunterWoW_QuestEN[36442] = { title = "Taking the Death Bloom", description = "Your work has born fruit. Inside the nearby cave a powerful saberon shaman is learning to channel the genesaur magic using the Death Bloom we seek. The solution is before us: kill the shaman, take the Death Bloom, return it to Birchus. That should improve the safety of our outpost.", objectives = "" }
WordHunterWoW_QuestEN[36443] = { title = "Laying Dionor to Rest", description = "You have given me a tremendous gift with this bloom. I can finally send Dionor back to the Overgrowth for good and end this nightmare. All that remains is the ritual... stay and behold something you will never see again in your lifetime...", objectives = "" }
WordHunterWoW_QuestEN[36448] = { title = "Reduction in Force", description = "I was a fool to trust him after the fiasco over the Barov family fortune! What I should have done is killed him the first chance I had.\n\nAnd now he thinks he's going to plumb this land for all that it's worth and cut me out?!\n\nNo, dear brother, not this time! There can only be one CEO of Barov Industries and it will be me.\n\nMy peasant friend, you must do me this service. Find my brother, Alexi, and serve him a notice of termination!\n\nYou will likely find him out in the wilds, near small timber.", objectives = "" }
WordHunterWoW_QuestEN[36449] = { title = "Reduction in Force", description = "I was a fool to trust him after the fiasco over the Barov family fortune! What I should have done is killed him the first chance I had.\n\nAnd now he thinks he's going to plumb this land for all that it's worth and cut me out?!\n\nNo, dear brother, not this time! There can only be one CEO of Barov Industries and it will be me.\n\nMy peasant friend, you must do me this service. Find my brother, Weldon, and serve him a notice of termination!\n\nYou will likely find him out in the wilds, near small timber.", objectives = "" }
WordHunterWoW_QuestEN[36457] = { title = "Bypassing Security", description = "Oh, my goodness!\n\nThis is a list of captives, it appears they may be awaiting transfer... or possibly even execution.\n\nThere is one name on this list that I do recognize: my master!\n\nI have been awaiting his return, but now it appears that he may have fallen into enemy hands.\n\nThis is a disaster! Please, {name}, we must rescue him.\n\nAccording to the notes, he has been taken to Grom'gar, located far east of here.\n\nOne moment... I think I may have just the thing to help you break in undetected...", objectives = "" }
WordHunterWoW_QuestEN[36460] = { title = "Just Another Stick in the Wall", description = "So, get this.\n\nAs I was flyin' in, I took the opportunity to scope out what might be a defensible position.\n\nJust on the other side o' these boulders is an ideal clearing to hole up in. I even brought a set of blueprints to get us all settled in!\n\nThat's not too presumptuous, is it?\n\nAnyway, whenever you're ready just hit this plunger!", objectives = "" }
WordHunterWoW_QuestEN[36469] = { title = "Pets Versus Pests", description = "I been tryin' ta get dis place ready for your pets, but we uncovered some rude pests while buildin' da garrison.  I tried takin' care o' dem myself, but they be too tough for my little friends.\n\nBeat da angry carrot in da garden, da rat eatin' our food, and da ornery water creature harassing da fishermen.  If you can do it, I be free to finish up da work on your menagerie.", objectives = "" }
WordHunterWoW_QuestEN[36471] = { title = "A New Darkmoon Challenger!", description = "Look at me, now look at my horse, now look back at me, are I not the most impressive battler of pets that you have ever seen?\n\nLook now at my compatriot over there. Is he on a horse? Of course not! Is his hat made of fireworks? Not in a million years! Everything about me is more impressive, from my coat color to my last name, which I made myself.\n\nDare you step up to the might of Christoph Willikens Dennis Ragnaros VonFeasel the First?\n\nI can see you trembling!", objectives = "" }
WordHunterWoW_QuestEN[36474] = { title = "The Razorbloom", description = "The Laughing Skull shaman Kaz ran off while we were coming here.\n\nShe claimed to be looking for more of her people in the jungles to the south.\n\nDraka insisted on following her to safeguard us against betrayal.\n\nCommander, if Kaz is telling the truth, then she and Draka are going to need all the help they can get.\n\nWill you join them? They could not have gotten far.\n\nThis could prove to be the perfect test for your new shredder and lumber mill resources.", objectives = "" }
WordHunterWoW_QuestEN[36475] = { title = "Stealing the Declaration", description = "Commander, you and Raleigh did a great job finding me, but I'm exactly where I need to be.\n\nWe've been working tirelessly since we got here, trying to crack these Draenic texts.\n\nI really thought I was gonna get the scrolls, but they nabbed me at the last possible second!\n\nPlease, you've gotta help me out... up the hill to the east, you'll find the Master Siegesmith's tent.\n\nIf you can grab the documents out of his chest, possibly this key too, I'll finally have enough to translate their languages.", objectives = "" }
WordHunterWoW_QuestEN[36477] = { title = "Broken Promises", description = "A heavily-scratched ring, faintly stained with blood.\n\nSomeone at the Darkmoon Faire might be able to provide more information about this item.", objectives = "" }
WordHunterWoW_QuestEN[36481] = { title = "Firebird's Challenge", description = "You're ready to fly high and give the Firebird's challenge a shot? That's great!\n\nSimply collect 15 rings to win! Speak to me when you're ready for takeoff!", objectives = "" }
WordHunterWoW_QuestEN[36482] = { title = "A Green Ogron?", description = "Kaz always told me green ogron are bad.\n\nThe botani here have a green ogron and it is mean.\n\nIt was strong enough to take out my dad's entire hunting party.\n\nAre you strong enough to kill it?", objectives = "" }
WordHunterWoW_QuestEN[36483] = { title = "Battle Pet Roundup", description = "Looks like we've got some visitors in the battle pen today, and they're looking for a fight.  Why don't you show 'em how a master of pet battles handles himself?", objectives = "" }
WordHunterWoW_QuestEN[36488] = { title = "Thieving Dwarves", description = "Cutter is on the trail of the artifact the dwarves stole. He has the nose of a wolf when it comes to hunting in the jungle.\n\nFollow the canyons south until you find him.\n\nIt would seem the wolf queen and I are going to do more damage here before we leave.\n\nWe will follow as quickly as we can.", objectives = "" }
WordHunterWoW_QuestEN[36494] = { title = "News from Talador", description = "Rokhan sends word that you are needed at Frostwall. The Iron Horde have landed on the shores of Talador.", objectives = "" }
WordHunterWoW_QuestEN[36495] = { title = "News from Talador", description = "Bodrick Grey sends word from your garrison that they have spotted a fleet of Iron Horde at the shores of Talador.\n\nWe must not allow them to destroy Shattrath.", objectives = "" }
WordHunterWoW_QuestEN[36498] = { title = "Iron Horde Invasion", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Vindicator Maraad at the Shattered Beachhead in Blasted Lands.\n\nUse the portal at the Wizard's Sanctum in Stormwind to head directly to the front line.\n\nThis new threat is known only as the Iron Horde. They have taken over the Dark Portal and must be stopped.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[36499] = { title = "Iron Horde Invasion", description = "All able bodied members of the Horde are hereby ordered to report to Thrall in Blasted Lands.\n\nUse the portal at the Cleft of Shadow in Orgrimmar to head directly to the front line.\n\nThis new threat is known only as the Iron Horde. They have taken over the Dark Portal and must be stopped\n\nDestiny calls!", objectives = "" }
WordHunterWoW_QuestEN[36502] = { title = "Trophy of Glory: Biolante", description = "Defeating Biolante has yielded you a trophy worthy of showing off at your outpost. \n\nReturn this to Maraad to increase your glory!", objectives = "" }
WordHunterWoW_QuestEN[36503] = { title = "Trophy of Glory: Biolante", description = "Defeating Biolante has yielded you a trophy worthy of acclaim.\n\nTake this to Durotan at Beastwatch.", objectives = "" }
WordHunterWoW_QuestEN[36505] = { title = "A Warrior's Shroud", description = "Although this cloak has seen better days, the workmanship is still quite impressive. Any normal cloak would have most certainly fallen apart by now.\n\nPerhaps one of the Frostwolf orcs within Wor'gol would be willing to help you repair it.", objectives = "" }
WordHunterWoW_QuestEN[36508] = { title = "Is This One of Yours?", description = "I found this one skulking nearby. She claims to be an ally of yours.\n\nIs this true? Or does she cook slowly over my fire?", objectives = "" }
WordHunterWoW_QuestEN[36510] = { title = "Fire Ammonite", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Frostfire Ridge for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", objectives = "" }
WordHunterWoW_QuestEN[36511] = { title = "Jawless Skulker", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Gorgrond for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", objectives = "" }
WordHunterWoW_QuestEN[36512] = { title = "Together We Are Strong", description = "", objectives = "" }
WordHunterWoW_QuestEN[36513] = { title = "Fat Sleeper", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Nagrand for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", objectives = "" }
WordHunterWoW_QuestEN[36514] = { title = "Blind Lake Sturgeon", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Shadowmoon Valley for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", objectives = "" }
WordHunterWoW_QuestEN[36515] = { title = "Blackwater Whiptail", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Talador for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", objectives = "" }
WordHunterWoW_QuestEN[36516] = { title = "Cut 'Em Out!", description = "After all that you've done for us, I would love to help you. Regrettably, I don't have the materials I would need to repair this perfectly.\n\nUse my knife to gather a few hides from the clefthoof that roam near the spire and find some sootweed pitch to properly cure them.\n\nUnfortunately, those miserable ogres have taken up residence in the only place that I know of sootweed to grow. You may be in for a fight {name}.\n\nReturn to me if you can obtain these and I will gladly help you repair your cloak.", objectives = "" }
WordHunterWoW_QuestEN[36517] = { title = "Abyssal Gulper Eel", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Spires of Arak for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", objectives = "" }
WordHunterWoW_QuestEN[36518] = { title = "The True Path", description = "", objectives = "" }
WordHunterWoW_QuestEN[36519] = { title = "The True Path", description = "", objectives = "" }
WordHunterWoW_QuestEN[36522] = { title = "Solidarity in Death", description = "", objectives = "" }
WordHunterWoW_QuestEN[36523] = { title = "A Green Ogron?", description = "Them botani got themselves a green ogron. A green ogron!\n\nI mean I may not know much about plant people but that canno' be a good thing.\n\nThink ya can take it in a fight?", objectives = "" }
WordHunterWoW_QuestEN[36567] = { title = "Bigger is Better", description = "Ya know boss, I think I know how we can take this place to the next level. Bigger walls. More buildings. Some space to stretch your arms after a long day of adventuring.\n\nDon't get me wrong, it's going to take a lot of resources, but what else are these things for?\n\nWe can plot it out on the drafting table whenever you're ready. It's going to be GLORIOUS.", objectives = "" }
WordHunterWoW_QuestEN[36573] = { title = "Strike While the Iron is Hot", description = "With the Heart of the Mangaron, we wield a powerful weapon against the Iron Horde.\n\nThey amass far to the north at the Iron Approach. This will not be easy, but we must seize the opportunity to deal a blow to the Iron Horde while we possess the artifact.\n\nWe are prepared to depart at your command. Speak with Grinslicer when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[36574] = { title = "Strike While the Iron is Hot", description = "With the Will of the Genesaur, we wield a powerful weapon.\n\nOur scouts have discovered an Iron Horde base, and I believe it is time to seize an opportunity.\n\nThey amass far to the north at the Iron Approach. This will not be easy, but we must deal a blow to the Iron Horde while we possess the artifact.\n\nWe are prepared to depart at your command. Speak with Grinslicer when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[36575] = { title = "Strike While the Iron is Hot", description = "With the Will of the Genesaur, we wield a powerful weapon.\n\nOur scouts have discovered an Iron Horde base, and I believe this is the time to seize an opportunity.\n\nThey amass far to the north at the Iron Approach. This will not be easy, but we must deal a blow to the Iron Horde while we possess the artifact.\n\nWe are prepared to depart at your command. Speak with Rangari Rajess when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[36576] = { title = "Strike While the Iron is Hot", description = "With the Heart of the Magnaron, we wield a powerful weapon against the Iron Horde.\n\nThey amass far to the north at the Iron Approach. This will not be easy, but we must seize the opportunity to deal a blow to the Iron Horde while we possess the artifact.\n\nWe are prepared to depart at your command. Speak with Rangari Rajess when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[36589] = { title = "Heavy Arms", description = "The burned out shell of some sort of weapon of mass destruction. It might be worth asking around your garrison to see if anyone can help get it working again.", objectives = "" }
WordHunterWoW_QuestEN[36592] = { title = "Bigger is Better", description = "Commander, I've been working on schematics that you might be interested in.\n\nWhat do you think about pushing out the walls and making room to get some additional structures in here? Our forces have been growing, and things are getting a little cramped, and I'd really like us to put some of those additional blueprints to use.\n\nIf you could, take a look at the plans on the table here. As soon as I have your go ahead, I'll get everyone to work immediately.", objectives = "" }
WordHunterWoW_QuestEN[36594] = { title = "\"Spare\" Parts", description = "I've never seen anything like this before! No problem though, boss man. If it can be used to blow things up, I can get it working again.\n\nWe are definitely going to need some parts--some sort of ammunition wouldn't hurt either.\n\nSounds like those Iron Horde guys over yonder are no stranger to things that go boom.\n\nTake these tools with you and let's see if we can't commandeer us some spare parts!", objectives = "" }
WordHunterWoW_QuestEN[36595] = { title = "He Drew Aggro...culture", description = "What you saw was the wake of the genesaur, Iyu. It was chasing this mechanical monstrosity and the person who drove it.\n\nI believe the pilot of this vessel is still alive and trapped within the ruins of the camp.\n\nIf you wish them to be recovered, I recommend doing so now.", objectives = "" }
WordHunterWoW_QuestEN[36601] = { title = "News from Nagrand", description = "One of your soldiers stopped by asking for you while you were out. Something about a caravan heading out to Nagrand.\n\nWhatever it was, it can't have gone well for them. That's Warsong territory.", objectives = "" }
WordHunterWoW_QuestEN[36602] = { title = "News from Nagrand", description = "One of your soldiers stopped by asking for you while you were out. Something about a caravan heading out to Nagrand.\n\nWhatever it was, it can't have gone well for them. That's Warsong territory.", objectives = "" }
WordHunterWoW_QuestEN[36606] = { title = "News from Nagrand", description = "Welcome back, sir.\n\nOne of Bodrick's men delivered a message about a caravan being dispatched for Nagrand. He's awaiting your approval on a new outpost.\n\nI've been hearing whispers around camp about Nagrand. They say it's Warsong territory. They might need your help sir.", objectives = "" }
WordHunterWoW_QuestEN[36607] = { title = "News from Nagrand", description = "Welcome back, sir.\n\nOne of our shadow hunters delivered a message about a caravan being dispatched for Nagrand. Rokhan's awaiting your approval on a new outpost.\n\nI've been hearing whispers around camp about Nagrand. They say it's Warsong territory. They might need your help sir.", objectives = "" }
WordHunterWoW_QuestEN[36608] = { title = "Finding Nat Pagle", description = "Now that you have proof, we might just have a shot at convincing Nat Pagle to join us out here.\n\nLast I heard, he was in fishing with the local Angler's faction out in Pandaria.  Somewhere off the coast of  Krasarang Wilds.  Head out there, show him your catch and see if you can get him to come back with you!", objectives = "" }
WordHunterWoW_QuestEN[36609] = { title = "The Great Angler Returns", description = "What's this species, a molten catfish you say? I have never even heard of a fish like this, much less seen one in person!\n\nI have to find more fish like this, it's what I live for! And if the fishing is as good as you say it is, there is just no way I can pass this opportunity up.  Take this page from my journal as proof that you found me and I will meet you back at your Garrison.", objectives = "" }
WordHunterWoW_QuestEN[36611] = { title = "A True Draenor Angler", description = "If you want me to help you permanently, you have to show me a few of these big Draenor catches first.  Head out into the wild and bring me back the biggest fish you can find from all the surrounding areas.\n\nI made this custom lure for you to use, please take care of it, it's never let me down!", objectives = "" }
WordHunterWoW_QuestEN[36612] = { title = "Luring Nat", description = "Now that you are experienced enough with Draenor fishing, we might have a shot at convincing Nat Pagle to join us out here.\n\nIf we want Nat to actually come all the way out here, we are going to have to show him real proof of the incredible catches on Draenor.  Head out to the lava lakes here in Frostfire and see what you can do.  All that time you spend honing your skill here in Draenor should pay off now.", objectives = "" }
WordHunterWoW_QuestEN[36614] = { title = "My Very Own Fortress", description = "Boss! Guess what?! I finally got that new larger draft paper in that I ordered when we first came here. And ya know what larger draft paper means?\n\nIt means I can draw a bigger fortress!\n\nAnd if I can draw it, I can certainly make it! Making's the easy part, as long as you've got a few thousand stones and logs lying around.\n\nSo whada'ya say, boss? Shall we get building?", objectives = "" }
WordHunterWoW_QuestEN[36615] = { title = "My Very Own Castle", description = "Commander! Some good news. I finally got that new larger draft paper in that I ordered when we first came here. And do you know what larger draft paper means?\n\nIt means I can draw a bigger castle!\n\nAnd if I can draw it, we can certainly make it! Making it is the easy part, assuming you have a few thousand stones and logs lying around.\n\nSo what do you say, sir? Shall we get building?", objectives = "" }
WordHunterWoW_QuestEN[36616] = { title = "An Angler on Our Team", description = "You truly are a master fisherman!\n\nI would be delighted to join you here on Draenor and help you catch as many lunkers as you can. But first, let's grab a drink.", objectives = "" }
WordHunterWoW_QuestEN[36617] = { title = "A Winter Veil Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[36624] = { title = "Ashran Appearance", description = "Our base on Ashran is almost complete, commander.\n\nIt would be a huge show of support if you could make a trip out there and put your stamp of approval on their staging area.\n\nI can arrange a flight if you are interested.", objectives = "" }
WordHunterWoW_QuestEN[36626] = { title = "Host Howell", description = "Lieutenant Howell said you might be showing up.\n\nIt's such an honor to meet you in person. The lieutenant is at the inn, I'll escort you over there.", objectives = "" }
WordHunterWoW_QuestEN[36627] = { title = "Big Frostfire Gun", description = "One of my finest works, {name}! Momma would be so proud of me right now... if she was still in one piece.\n\nWe gotta test this bad boy out though before I'm comfortable letting you run around with it all willy-nilly.\n\nI heard there were some clefthooves out back causing a ruckus.", objectives = "" }
WordHunterWoW_QuestEN[36629] = { title = "Inspiring Ashran", description = "I hope you will find our facilities to be up to your high standards.\n\nThis inn is run by Jaesia Rosecheer, in my opinion this is the best place to hearth in Draenor.\n\nWe have new recruits coming through the portal daily. In fact our latest recruit, Knewbie McGreen just came through the portal today.\n\nIf you are looking to trade for weapons or armor, Vindicator Nuurem will be happy to help.", objectives = "" }
WordHunterWoW_QuestEN[36630] = { title = "A Surly Dwarf", description = "Before you go there is someone you might want to talk with.\n\nHe's opinionated, a bit gruff, and very overbearing, but he's the best damn warrior I've met in ages.\n\nHe belongs on the front lines with you, commander. And trust me, he knows it.", objectives = "" }
WordHunterWoW_QuestEN[36632] = { title = "The Secrets of Gorgrond", description = "Commander, I was dispatched to intercept you.\n\nYrel and Maraad have landed at Wildwood Wash, the rangari base of operations for the area.\n\nYour presence is requested immediately. \n\nWe keep a small feywing presence just east of here. If you speak with the flight master they should be able to provide you safe passage to the Wash.", objectives = "" }
WordHunterWoW_QuestEN[36633] = { title = "Delvar Ironfist", description = "", objectives = "" }
WordHunterWoW_QuestEN[36641] = { title = "Your First Alchemy Work Order", description = "Now that the alchemy lab is complete, we can start producing alchemical catalysts for you. When you have the ingredients, please speak with my assistant to start the first work order.", objectives = "" }
WordHunterWoW_QuestEN[36642] = { title = "Your First Leatherworking Work Order", description = "Now that the tannery is complete, we can start producing burnished leather for you. When you have the ingredients, please speak with my assistant to start the first work order.", objectives = "" }
WordHunterWoW_QuestEN[36643] = { title = "Your First Tailoring Work Order", description = "Now that the tailoring emporium is complete, we can start producing hexweave cloth for you. When you have the ingredients, please speak with my assistant to start the first work order.", objectives = "" }
WordHunterWoW_QuestEN[36644] = { title = "Your First Jewelcrafting Work Order", description = "Now that the gem boutique is complete, we can start producing taladite crystals for you. When you have the ingredients, please speak with my assistant to start the first work order.", objectives = "" }
WordHunterWoW_QuestEN[36645] = { title = "Your First Enchanting Work Order", description = "Now that the enchanter's study is complete, we can start producing draenic dust for you. When you have the ingredients, please speak with my assistant to start the first work order.", objectives = "" }
WordHunterWoW_QuestEN[36646] = { title = "Your First Engineering Work Order", description = "Now that the engineering works is complete, we can start producing gearspring parts for you. When you have the ingredients, please speak with my assistant to start the first work order.", objectives = "" }
WordHunterWoW_QuestEN[36647] = { title = "Your First Inscription Work Order", description = "Now that the scribe's quarters are complete, we can start producing war paints for you. When you have the ingredients, please speak with my assistant to start the first work order.", objectives = "" }
WordHunterWoW_QuestEN[36648] = { title = "Assault on Stonefury Cliffs", description = "Bloodmaul ogres from Frostfire Ridge have been ambushing trade routes throughout the continent, and are putting captured soldiers to work in their slag mines.\n\nBodrick Grey has requested the rescue of friendly troops that have been taken prisoner in the main Bloodmaul compound at Stonefury Cliffs.", objectives = "" }
WordHunterWoW_QuestEN[36649] = { title = "Assault on Shattrath Harbor", description = "Shattrath City is in the hands of Sargerei forces under the leadership of the traitor Exarch, Socrethar.\n\nMembers of the Sha'tari Defense have been requesting aid against the Shadow Council forces in the eastern portions of the city.", objectives = "" }
WordHunterWoW_QuestEN[36662] = { title = "Scrappin'", description = "Ever since we built da menagerie, a lot o' \"visitors\" been showin' up.  I know da look, and they be lookin' for a fight.  Brudda, you show 'em you da real master 'round here.", objectives = "" }
WordHunterWoW_QuestEN[36667] = { title = "Assault on Shattrath Harbor", description = "Shattrath City is in the hands of Sargerei forces under the leadership of the once Exarch, Socrethar.\n\nThe Shadow Council forces in the eastern portion of the city are gaining in power through the aid of demons from the Nether, and need to be culled before they become a threat to all of our operations.", objectives = "" }
WordHunterWoW_QuestEN[36669] = { title = "Assault on Stonefury Cliffs", description = "Bloodmaul ogres from Frostfire Ridge have been ambushing trade routes throughout the continent, and are putting captured soldiers to work in their slag mines.\n\nShadow Hunter Rokhan has requested the rescue of friendly troops that have been taken prisoner in the main Bloodmaul compound at Stonefury Cliffs.", objectives = "" }
WordHunterWoW_QuestEN[36674] = { title = "Assault on the Iron Siegeworks", description = "Iron Horde war machines are being shipped onto battlefields by the dozens, and our forces are struggling to hold their ground. Most of these machines seem to be originating from the Iron Siegeworks in eastern Frostfire Ridge.\n\nA strategic attack to disrupt and dismantle the Iron Horde at the siegeworks could be just what we need to turn the tide of the war.", objectives = "" }
WordHunterWoW_QuestEN[36675] = { title = "Assault on Magnarok", description = "Colossal magnaron, gronn, and other stone monstrosities have been threatening our outposts in the west. Most seem to originate from Magnarok in Frostfire Ridge.\n\nIf we strike at them at their home, we should be able to force them back. It's risky, but it may be our best move. While you're there, see if you can recover any of our supplies.", objectives = "" }
WordHunterWoW_QuestEN[36676] = { title = "Assault on the Everbloom Wilds", description = "Botani and the plant monstrosities they conjure have been slowly encroaching on our outposts in the north. For every plant we kill, new ones seem to rise in its place.\n\nBodrick Grey has put together a plan for striking at the heart of their lands, in Everbloom Wilds. He thinks this will draw them back into the wilds of Gorgrond, giving us more room to maneuver around them.", objectives = "" }
WordHunterWoW_QuestEN[36677] = { title = "Assault on the Broken Precipice", description = "Massive ogron have been battering our frontlines, and no matter how many we down, there seem to be more to replace them.\n\nMost of these ogron appear to be coming from the Broken Precipice, deep in western Nagrand. If we're to stand a chance in the coming battles, we need to find a way to remove these ogron from the battlefield.", objectives = "" }
WordHunterWoW_QuestEN[36678] = { title = "Assault on Mok'gol Watchpost", description = "Warsong raiders out of Mok'gol Watchpost have been terrorizing anything and everything not behind a tall wall. We've warned travelers not to stray out alone, but many don't listen.\n\nIf we were to launch an assault on Mok'gol Watchpost, we would almost certainly put the Warsong back on the defensive, restricting most of their riders to Nagrand.", objectives = "" }
WordHunterWoW_QuestEN[36679] = { title = "Assault on Darktide Roost", description = "There's been a resurgence of rylaks on the battlefield in our skirmishes against the Iron Horde. If we don't stop them at the source, we'll quickly lose control of the roads and be pushed back into our outposts.\n\nThe most likely source of these additional rylaks is in southeastern Shadowmoon Valley, at Darktide Roost. If we move quickly, we should still have time to get ahead of the problem.", objectives = "" }
WordHunterWoW_QuestEN[36680] = { title = "Assault on Socrethar's Rise", description = "Recent reports suggest a notable rise of activity by Sargerei forces at Socrethar's Rise in southern Shadowmoon Valley.\n\nSocrathar's disciples pose a threat to draenei and our garrison alike. We need to quell them at our soonest convenience.", objectives = "" }
WordHunterWoW_QuestEN[36681] = { title = "Assault on Lost Veil Anzu", description = "Some of our best scouts have gone missing in the vicinity of the lost ruins of Veil Anzu.\n\nBodrick Grey has requested any available resources be dispatched to identify the threat and see if any of our men yet remain alive within the ruins.", objectives = "" }
WordHunterWoW_QuestEN[36682] = { title = "Assault on Pillars of Fate", description = "Remnants of the Shadowmoon clan continue to operate out of the peaks on the eastern border of Spires of Arak.\n\nBodrick Grey is concerned at their proximity to the garrison, and has put out a request that we thin their forces as soon as possible.", objectives = "" }
WordHunterWoW_QuestEN[36683] = { title = "Assault on Skettis", description = "We've been receiving regular reports of birdmen from the south ambushing and burning caravans along the main roads.\n\nGuards from our outposts are requesting that we launch a counter attack against the main presence of Adherents of Rukhmar at Skettis in Spires of Arak.", objectives = "" }
WordHunterWoW_QuestEN[36684] = { title = "Battle in Ashran", description = "As we do battle all across Draenor, the cowardly Horde try to seize our territory within Ashran.\n\nOur men would be inspired to see you join the battlefield, striking terror into the hearts of the Horde.", objectives = "" }
WordHunterWoW_QuestEN[36685] = { title = "Assault on the Heart of Shattrath", description = "Sargerei forces from deep in Shattrath have grown stronger and bolder by the day. We can no longer risk ignoring the threat that they pose.\n\nBring allies if you wish to face the Sargerei so deep within the city.", objectives = "" }
WordHunterWoW_QuestEN[36686] = { title = "Assault on the Pit", description = "The Blackrock forces based out of the Pit in Gorgrond make up the bulk of the Iron Horde army. If we crush them on their home soil, the rest of the Iron Horde will have little hope of standing against us.\n\nIf you choose the battle, bring friends. The Blackrock won't be defeated easily.", objectives = "" }
WordHunterWoW_QuestEN[36687] = { title = "Challenge at the Ring of Blood", description = "A challenge has been issued at the Ring of Blood.\n\nBring friends and do battle to prove your right as champion.", objectives = "" }
WordHunterWoW_QuestEN[36688] = { title = "Assault on Skettis", description = "We've been receiving regular reports of birdmen from the south ambushing and burning caravans along the main roads.\n\nGuards from our outposts are requesting that we launch a counter attack against the main presence of Adherents of Rukhmar at Skettis in Spires of Arak.", objectives = "" }
WordHunterWoW_QuestEN[36689] = { title = "Assault on Pillars of Fate", description = "Remnants of the Shadowmoon clan continue to operate out of the peaks on the eastern border of Spires of Arak.\n\nRokhan is concerned at their proximity to key choke points leading into Shadowmoon Valley, and has put out a request that we thin their forces as soon as possible.", objectives = "" }
WordHunterWoW_QuestEN[36690] = { title = "Assault on Lost Veil Anzu", description = "Some of our best scouts have gone missing in the vicinity of the lost ruins of Veil Anzu.\n\nRokhan has requested any available resources be dispatched to identify the threat and see if any of our men yet remain alive within the ruins.", objectives = "" }
WordHunterWoW_QuestEN[36691] = { title = "Assault on Socrethar's Rise", description = "Recent reports suggest a notable rise of activity by Sargerei forces at Socrethar's Rise in southern Shadowmoon Valley.\n\nSocrathar's disciples pose a threat all over Draenor. We must not allow them to gain a foothold so far from our reach.", objectives = "" }
WordHunterWoW_QuestEN[36692] = { title = "Assault on Darktide Roost", description = "There's been a resurgence of rylaks on the battlefield in our skirmishes against the Iron Horde. If we don't stop them at the source, we'll quickly lose control of the roads and be pushed back into our outposts.\n\nThe most likely source of these additional rylaks is in southeastern Shadowmoon Valley, at Darktide Roost. If we move quickly, we should be able to stop their operation cold.", objectives = "" }
WordHunterWoW_QuestEN[36693] = { title = "Assault on Mok'gol Watchpost", description = "Warsong raiders out of Mok'gol Watchpost have been terrorizing anything and everything not behind a tall wall. We've warned travelers not to stray out alone, but many don't listen.\n\nIf we were to launch an assault on Mok'gol Watchpost, we would almost certainly put the Warsong back on the defensive, restricting most of their riders to Nagrand.", objectives = "" }
WordHunterWoW_QuestEN[36694] = { title = "Assault on the Broken Precipice", description = "Massive ogron have been battering our frontlines, and no matter how many we down, there seem to be more to replace them.\n\nMost of these ogron appear to be coming from the Broken Precipice, deep in western Nagrand. If we're to stand a chance in the coming battles, we need to find a way to remove these ogron from the battlefield.", objectives = "" }
WordHunterWoW_QuestEN[36695] = { title = "Assault on the Everbloom Wilds", description = "Botani and the plant monstrosities they conjure have been slowly encroaching on our outposts in the north. For every plant we kill, new ones seem to rise in its place.\n\nRokhan has put together a plan for striking at the heart of their lands, in Everbloom Wilds. He thinks this will draw them back into the jungles of Gorgrond, giving us more room to maneuver around them.", objectives = "" }
WordHunterWoW_QuestEN[36696] = { title = "Assault on the Iron Siegeworks", description = "Iron Horde war machines are being shipped onto battlefields by the dozens, and our forces are struggling to hold their ground. Most of these machines seem to be originating from the Iron Siegeworks in eastern Frostfire Ridge.\n\nA strategic attack to disrupt and dismantle the Iron Horde at the siegeworks could be just what we need to turn the tide of the war.", objectives = "" }
WordHunterWoW_QuestEN[36697] = { title = "Assault on Magnarok", description = "Colossal magnaron, gronn, and other stone monstrosities have been threatening our garrison. Most seem to originate from Magnarok, just to the north.\n\nIf we strike at them at their home, we should be able to force them back. It's risky, but it may be our best move. While you're there, see if you can recover any of our supplies.", objectives = "" }
WordHunterWoW_QuestEN[36698] = { title = "Battle in Ashran", description = "As we do battle all across Draenor, the cowardly Alliance try to seize our territory within Ashran.\n\nOur men would be inspired to see you join the battlefield, striking terror into the hearts of the Alliance.", objectives = "" }
WordHunterWoW_QuestEN[36699] = { title = "Assault on the Heart of Shattrath", description = "Sargerei forces from deep in Shattrath have grown stronger and bolder by the day. We can no longer risk ignoring the threat that they pose.\n\nBring allies if you wish to face the Sargerei so deep within the city.", objectives = "" }
