WordHunterWoW_QuestEN[36702] = { title = "Meatball", description = "", objectives = "" }
WordHunterWoW_QuestEN[36706] = { title = "Ashran Appearance", description = "Our base on Ashran is almost complete, commander.\n\nIt would be a huge show of support if you could make a trip out there and put your stamp of approval on their staging area.\n\nI can arrange a flight if you are interested.", objectives = "" }
WordHunterWoW_QuestEN[36707] = { title = "Warspear Welcome", description = "Lieutenant Kragil said you might be showing up.\n\nI've been ordered to take you to the inn.", objectives = "" }
WordHunterWoW_QuestEN[36708] = { title = "Inspiring Ashran", description = "I hope you will find our facilities to be up to your high standards.\n\nThis inn is run by Narnin Dawnglow, in my opinion this is the best place to hearth in Draenor.\n\nWe have new recruits coming through the portal daily. In fact one of out latest recruits, Zarjhin, just came through the portal today.\n\nIf you are looking for weapons or armor Beska Redtusk will be happy to help.", objectives = "" }
WordHunterWoW_QuestEN[36709] = { title = "Burning Beauty", description = "Before you go, there is someone you should meet.\n\nShe might set some of your stuff on fire, but I believe she's the best mage this side of Draenor.\n\nShe belongs on the front lines with you, commander.", objectives = "" }
WordHunterWoW_QuestEN[36711] = { title = "Abu'gar", description = "You thinkin' you might be able to help me out, mon?", objectives = "" }
WordHunterWoW_QuestEN[36719] = { title = "Into Aegwynn's Retreat", description = "If we're going to defeat that demon, we need something to put us on its level. Something... powerful...\n\n<Khadgar looks thoughtfully at Atiesh, his staff.>\n\nYou need a weapon. Something of great power. And if my assumptions are correct, it shouldn't be too far from here.\n\nI can send you to go find this weapon. Speak with me when you're prepared.", objectives = "" }
