WordHunterWoW_QuestEN[36790] = { title = "The Initiate's Revenge", description = "I... I'm finished. My spirit will be with the Raven Mother soon.\n\nI beg of you, stranger... avenge me! Slay these filthy beasts.", objectives = "" }
WordHunterWoW_QuestEN[36795] = { title = "Return to Karazhan: The Conjuring of Aluneth", description = "The book describes Aluneth: Aegwynn's own weapon.\n\nThe first few paragraphs describe Aluneth not as a weapon, but as an entity with its own will.\n\nThe next few pages, however, have been ripped out of the book...", objectives = "" }
WordHunterWoW_QuestEN[36801] = { title = "One Step Ahead", description = "Commander, Vindicator Maraad set off with Yrel and Thaelin Darkanvil to track the Iron Horde's movements in the nearby forest.\n\nThey await your arrival on a small rise to the southwest.", objectives = "" }
WordHunterWoW_QuestEN[36812] = { title = "Penny For Your Thoughts", description = "", objectives = "" }
WordHunterWoW_QuestEN[36813] = { title = "Subversive Infestation", description = "As lord of the Everbloom my charge was the weaponization of nature.\n\nYou have likely seen the fruits of my labor in your journeys across my world.\n\nMy discoveries have allowed my kind to control the invasive species of Draenor through subversive infestation. I speak of total systemic control of the invading organism - the mind and the body.\n\nNow that you are my master I offer these gifts to you, but first you must retrieve my research and tools from the Everbloom.\n\nDo this and great power is yours.", objectives = "" }
WordHunterWoW_QuestEN[36828] = { title = "Lumber, I Hardly Knew 'Er", description = "", objectives = "" }
WordHunterWoW_QuestEN[36832] = { title = "Get the Xuk Outta Here!", description = "Magnaron are not very receptive.", objectives = "" }
WordHunterWoW_QuestEN[36833] = { title = "May I Be of Service?", description = "", objectives = "" }
WordHunterWoW_QuestEN[36838] = { title = "Your Second Alchemy Work Order", description = "Place another work order with my assistant. Once it is complete, we will leave it out here for you to collect.", objectives = "" }
WordHunterWoW_QuestEN[36839] = { title = "Your Second Enchanting Work Order", description = "Place another work order with my assistant. Once it is complete, we will leave it out here for you to collect.", objectives = "" }
WordHunterWoW_QuestEN[36840] = { title = "Your Second Engineering Work Order", description = "Place another work order with my assistant. Once it is complete, we will leave it out here for you to collect.", objectives = "" }
WordHunterWoW_QuestEN[36841] = { title = "Your Second Inscription Work Order", description = "Place another work order with my assistant. Once it is complete, we will leave it out here for you to collect.", objectives = "" }
WordHunterWoW_QuestEN[36842] = { title = "Your Second Jewelcrafting Work Order", description = "Place another work order with my assistant. Once it is complete, we will leave it out here for you to collect.", objectives = "" }
WordHunterWoW_QuestEN[36843] = { title = "They Came From Above", description = "Please, traveler, I need your help.\n\nAruuna, my home, has been destroyed by the arakkoa. They swooped down from their spires and killed anyone who tried to escape. My family... did not make it out.\n\n My brother Barum stayed behind to find his daughter amidst the chaos. I beseech you, please, go to Aruuna and find Barum.\n\nHe is the only family I have left.", objectives = "" }
WordHunterWoW_QuestEN[36844] = { title = "Your Second Leatherworking Work Order", description = "Place another work order with my assistant. Once it is complete, we will leave it out here for you to collect.", objectives = "" }
WordHunterWoW_QuestEN[36845] = { title = "Your Second Tailoring Work Order", description = "Place another work order with my assistant. Once it is complete, we will leave it out here for you to collect.", objectives = "" }
WordHunterWoW_QuestEN[36848] = { title = "Ogre Waygates", description = "Six unique gates exist in Draenor, built by ogre magi in ages past.  We've discovered their potency has not diminished over the millennia.\n\nIf you can collect enough ogre waystones to activate one of these ancient waygates, we can build a portal from your garrison to that location.", objectives = "" }
WordHunterWoW_QuestEN[36861] = { title = "Pinchwhistle Gearworks", description = "Commander, a goblin courier arrived this morning.\n\nHe mentioned that he is from a settlement in the Spires of Arak called the Pinchwhistle Gearworks. They have requested our assistance with some sort of ecological disaster.\n\nIf we can earn their trust it'll be worth the effort. Head down there and see what sort of assistance we can provide.\n\nI've already spoken to the flight master and he's set up a special flight to get you out there.", objectives = "" }
WordHunterWoW_QuestEN[36862] = { title = "Pinchwhistle Gearworks", description = "Commander, a courier arrived this morning.\n\nHe said he's from a goblin settlement in Spires of Arak called the Pinchwhistle Gearworks. They've asked for our assistance with some sort of ecological disaster.\n\nWe're spread thin but if we can earn their trust then we might be able to gain a valuable ally.\n\nHead down there and see what sort of assistance we can provide. I've already spoken to the flight master and he's set up a special flight to get you out there.", objectives = "" }
WordHunterWoW_QuestEN[36864] = { title = "Three Feet Under", description = "", objectives = "" }
WordHunterWoW_QuestEN[36870] = { title = "Luring Nat", description = "Now that you are experienced enough with Draenor fishing, we might have a shot at convincing Nat Pagle to join us out here.\n\nIf we want Nat to actually come all the way out here, we are going to have to show him real proof of the incredible catches on Draenor.  Head out to local waters here in Shadowmoon Valley and see what you can do.  All that time you spend honing your skill here in Draenor should pay off now.", objectives = "" }
WordHunterWoW_QuestEN[36874] = { title = "Warlord of Draenor", description = "Durotan...\n\n<Raza'kul spits.>\n\nHe cowers behind the white flag of peace, relying upon diplomacy to win over our sworn enemies.\n\nEnemies that have taken our homes and driven us from our ancestral lands.\n\nThere is only one way to deal with the draenei and their newfound alliance of cowards - blood for blood.\n\nJoin me in crushing our enemies. Together we will flood this hallowed ground with the bones of the Alliance and earn tributes fit for a warchief!\n\nReturn here when your bloodthirst is sated.", objectives = "" }
WordHunterWoW_QuestEN[36876] = { title = "Warlord of Draenor", description = "The Exarchs do nothing but squabble amongst themselves over petty issues while our people are slaughtered in their homes by orc filth. If they will not raise a fist of defiance against our enemies, I will.\n\nI wish to join your Alliance and rid this world of Horde. ALL HORDE - \"Iron\" or otherwise.\n\nThis Altar of Bones that I stand upon represents glory in battle against our Horde enemy. Place an offering upon it and earn a conqueror's tribute worthy of your unrelenting bloodthirst.\n\nKill. Them. All.", objectives = "" }
WordHunterWoW_QuestEN[36881] = { title = "Warlords of Draenor: The Dark Portal", description = "{name}, is it? I'm glad you're here. We can use every able-bodied {class} that we can get.\n\nI am assembling a coalition of Azeroth's strongest to step through this Dark Portal and stop the Iron Horde invasion. This may be the only way to save Azeroth.\n\nWill you join us?", objectives = "" }
WordHunterWoW_QuestEN[36882] = { title = "The Great Angler Returns", description = "What's this species, an arcane trout you say? I have never even heard of a fish like this, much less seen one in person!\n\nI have to find more fish like this, it's what I live for! And if the fishing is as good as you say it is, there is just no way I can pass this opportunity up.  Take this page from my journal as proof that you found me and I will meet you back at your Garrison.", objectives = "" }
WordHunterWoW_QuestEN[36889] = { title = "Nemesis: Hunter - Hunted", description = "Our enemies surround us, and with each passing day their numbers grow. It is time to make a decisive strike against their armies, champion.\n\nAround me stand effigies of our most hated adversaries. You will be their downfall, {name}. You will become nemesis and they will run in fear at the sight of you.\n\nNow select the target of your rage and burn in effigy that race which you mean to eradicate. Speak to me when you have made your selection.", objectives = "" }
WordHunterWoW_QuestEN[36897] = { title = "Nemesis: Becoming Death", description = "You have chosen your quarry and surely soon they will feel your merciless wrath, but first you must venture out into the wilds of Draenor and rip out the still-beating heart of a human in mortal combat. Return here with your prize.\n\nThrough the heart of your enemy the spirits will attune your senses, granting you second sight and keenness in hearing - all to stalk your prey and claim dominance.", objectives = "" }
WordHunterWoW_QuestEN[36910] = { title = "The Incarnation of Aluneth", description = "<As the scrolls are added back into the book, the entirety of the spell becomes clear.>", objectives = "" }
WordHunterWoW_QuestEN[36911] = { title = "Taming a Talbuk", description = "If we're going to start sending out patrols in this wilderness, we'll need swift mounts for our troops. We can capture young beasts and bring them back here for training, eventually turning them into formidable beasts of war.\n\nThe talbuk is one of Draenor's fastest creatures, and that makes them just that much more difficult to capture. Take this talbuk lasso and head out to Shadowmoon Valley. Mount up and rope one of the young talbuk, and follow it until it's tamed. Don't let it get too far from you!", objectives = "" }
WordHunterWoW_QuestEN[36912] = { title = "Capturing a Clefthoof", description = "Greetings, friend. I have been told that you are in need of a master of beasts. I come from the icy slopes of Northrend to finally shake this snow from my fur.\n\nThis savage land holds many creatures that we may tame so that our forces may ride on formidable war mounts. The mighty clefthoof reminds me of the mammoths from my home. Take this lasso and head out to the northern reaches of Frostfire Ridge. Mount up and use it to capture one of the young beasts.", objectives = "" }
WordHunterWoW_QuestEN[36913] = { title = "Besting a Boar", description = "Have you seen the boars they have here? Bigger than I am! Let's get one of them, why not?\n\nYou're going to have to head to Gorgrond for that task. Way out in the desolate regions, you'll find the ones we're lookin' for.", objectives = "" }
WordHunterWoW_QuestEN[36914] = { title = "Wrangling a Wolf", description = "This next one will test you to your very limits, commander. The wolf is the most savage beast in all of Draenor.\n\nThe wolves of Nagrand, mounts of the fabled Warsong clan, can rend a man to bits in seconds. They're also faster and more agile than anything you've seen yet.\n\nHere's your lasso. Good luck, and don't get yourself killed!", objectives = "" }
WordHunterWoW_QuestEN[36915] = { title = "Entangling an Elekk", description = "Well, you're pretty good at this whole taming thing. What's next?\n\nWe've done big, and we've done pointy. Let's do big AND pointy. I'm talking Elekks.\n\nWay out on the fertile plains of Nagrand, you'll find the finest specimens of beast this world has to offer. Grab one of the younger elekks, and we'll see if we can't get it trained like the Draenei used to.", objectives = "" }
WordHunterWoW_QuestEN[36916] = { title = "Capturing a Clefthoof", description = "Way up north in the frozen peaks of Frostfire Ridge, you'll find the wooly clefthoof.\n\nThey're sturdy, for sure, and fierce when you corner them. Don't expect them to be tamed without a fight.\n\nHere's a lasso, see if you can't manage to tame one before it tugs the rope out of your hands.", objectives = "" }
WordHunterWoW_QuestEN[36917] = { title = "Taming a Talbuk", description = "The next beast is one of the fastest in Draenor, but will test your skills at infiltrating into enemy territory.\n\nThe young talbuk can be found on the flowery hills of Shadowmoon Valley. Take this talbuk lasso and head out.\n\nWhen you encounter one, mount up and throw this rope, then follow it until it is tamed. Good hunting!", objectives = "" }
WordHunterWoW_QuestEN[36918] = { title = "Requisition a Riverbeast", description = "I wasn't sure about this next beast, but it turns out that they've got a key strategic purpose. The riverbeast is quite at home in the water!\n\nYou'll find the best ones around in Talador, around about Duskfall Island. Look for the huge, floating lumps out in the water.\n\nTry not to get wet!", objectives = "" }
WordHunterWoW_QuestEN[36920] = { title = "From Within", description = "A few of our demon hunters, Kor'vas Bloodthorn and Cyana Nightglaive, took a small force of the Illidari across to Faronaar. Their mission was to weaken the Legion from within.\n\nI haven't heard from them in a while.\n\nIt would be best if you could find and lead them to success. Agreed?", objectives = "" }
WordHunterWoW_QuestEN[36921] = { title = "Nemesis: Manslayer", description = "<Raza'kul hands you the bloody heart.>\n\nThe ritual is complete. Your nemesis is marked for death.\n\nNow your work to rid this world of the enemy truly begins. Kill all humans that stand defiantly against the Horde. Let their deaths serve as a warning to the rest of the Alliance: they will leave Draenor or they will die.\n\nReturn when you have quenched your rage with the blood of man.\n\nConquer our enemy and be known as manslayer. Fail and be nothing.", objectives = "" }
